pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small "dead" gaps that likely cannot host future items.
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * 8.0; // strong penalty for tiny unusable gaps
        } else if gap < 40.0 {
            score += (40.0 - gap) * 2.0; // moderate penalty for medium gaps
        }

        // If the lookahead item cannot fit in this gap, penalize the dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Reward bins whose gap can host the next item.
            score -= 15.0;
        }
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; make the new-bin candidate less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight nudge to fill fuller bins first.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
