pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 are perfect fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modular class reward: post_residual divisible by common item classes
    if post_residual % 10 == 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 {
        score -= 12.0;
    }

    // Dead-space penalty: small unusable residuals (below min item size 1 -> use threshold)
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 4.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic class match: next item leaves again a clean residue
            let next_post = post_residual - next_item_size;
            score -= 25.0;
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Integer-division threshold on residual fraction
    let frac = pr / cap;
    if frac < 0.1 {
        score += 20.0; // nearly full bin: fine, but avoid tiny scraps -> slight penalty offset
        score -= 10.0;
    } else if frac < 0.35 {
        score -= 8.0; // sweet spot for medium items
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep it available but not preferred unless residuals are poor
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5 - (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 100.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

