        }
        // Very small absolute gaps (< 10) are almost certainly wasted.
        if post_residual < 10 {
            score += 30.0;
        }
        // Progressive penalty as gap shrinks relative to capacity (non-linear).
        score += (1.0 - pr / bin_capacity as f64).powf(3.0) * 20.0;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual below the running mean (compact bins).
    score += (pr - mean_residual).max(-30.0).min(30.0) * 0.3;

    // New-bin candidate: neutral baseline, only chosen when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.1 - pr * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
