        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: penalize bins when many bins are open, to consolidate.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if the
    // item leaves a large residual AND no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // Penalize new bin when existing bins are roomy enough to absorb items.
        if mean_r > item_size as f64 * 1.5 {
            score += 30.0;
        }
        // Reward new bin slightly when the item is large and would leave a
        // clean residual, avoiding fragmentation of open bins.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Lookahead: if next item is small, a fresh bin is fine to keep clean.
        if next_item_size > 0 && next_item_size <= 15 {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: reward placing item so that the next item still
        // fits into this bin's residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // Creating a gap the known next item cannot use: dead space.
            score += 20.0;
        }
    }

    // Slight preference for tighter bins (best-fit flavor) on top of residual.
    score += (bin_residual as f64) * 0.05;

    // Early in the stream, allow more aggressive new-bin opening to build
    // diverse residual portfolios; late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
