    // "reusable" classes (divisible by small moduli) are more valuable.
    let c = bin_capacity as f64;

    // Penalize dead space: small nonzero residuals are wasted capacity.
    if post_residual > 0 {
        let pr = post_residual;
        // harmonic class by divisibility
        let class_bonus: f64 = if pr % 50 == 0 {
            -12.0
        } else if pr % 25 == 0 {
            -9.0
        } else if pr % 20 == 0 {
            -7.0
        } else if pr % 10 == 0 {
            -5.0
        } else if pr % 5 == 0 {
            -3.0
        } else {
            3.0
        };
        score += class_bonus;

        // Dead-space cliff: residuals below the smallest plausible item
        // are nearly useless.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        } else if pr < 30 {
            score += 4.0;
        }
    } else {
        // Perfect closure of a bin is excellent.
        score -= 20.0;
    }

    // Lookahead: does post_residual fit the next item exactly or well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 + (slack as f64) * -0.15; // reward tight fit for next item
        if slack == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: residual must still be generically useful
        score += 2.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    // rather than fragmenting across a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current open bins are crowded
    // or the fit is poor. Penalize opening new bins by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        score += 30.0 - crowd * 2.0 + progress * 10.0;
        // But if placing in an open bin would strand a lot of space, allow new bin
        if post_residual < 25 && bin_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for larger items going into larger-residual bins.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
