        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item could also fit here afterwards: mild bonus scaled by closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space too small for the next item: penalize proportionally.
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    } else {
        // Last item: just minimize waste beyond post_residual baseline.
        score -= 5.0;
    }

    // Penalize creating very small unusable fragments (relative to typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is tighter than the mean (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - 20.0 * pressure - 2.0 * open_bins_count as f64;
    }

    // Slight late-stream conservatism: consolidate more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let smallest_item = 1u32;
        if post_residual < smallest_item {
            score += 1000.0;
        }
        // Penalize gaps too small for the lookahead item (unusable for next step).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Non-linear penalty on very small dead space (hardest to reuse).
        let pr = post_residual as f64;
        if pr <= 10.0 {
            score += (10.0 - pr) * 3.0;
        }
    } else {
        // Perfect fit is highly rewarded.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor filling existing.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if mean residual is high, prefer bins that reduce it most.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current placements are very poor.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -1.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Progression: later in stream, be more conservative (prefer exact fills).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
