    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Compare against mean residual: bins tighter than average are preferred targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: a fresh empty bin should only win when the best
    // existing fit is poor. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.6 * open_bins_count as f64 * (0.5 + progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room for lookahead pairing in a fresh bin
