        score += 0.0;
    }

    // Penalize bins whose residual is far below the mean residual (they are nearly full;
    // wasting them on a poor fit is costly) but reward using nearly-full bins for tight fits.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, discounted when many bins are open
        // or the item is large relative to capacity.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 40.0 + 60.0 * fill_ratio - 5.0 * (open_bins_count as f64).sqrt();
        // If lookahead suggests next item would pair with this item's residual, encourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Slight preference to keep residuals above small-item threshold usable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "small"
    // classes are near-perfectly packed; reward them heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

