        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // New-bin candidate handling: prefer reusing open bins generally.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are crowded
        // (mean residual low) and the item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item = item_size as f64;
