        score += 12.0 * (1.0 - post / (next_item_size as f64).max(1.0));
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Prefer bins below mean residual (consolidate space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: penalize mildly early, more strongly late,
    // unless post_residual is large (item is small and bin would stay useful).
    if bin_residual == bin_capacity {
        let base = 8.0 + 20.0 * progress;
        let utility = post / cap;
        score += base * (1.0 - 0.5 * utility);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" class (small, or divisible by common size granules) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if pr <= 10 {
        -25.0 // tiny dead space, nearly full
    } else if pr % 10 == 0 {
        -15.0 // residue on a common granule, reusable by many item sizes
    } else if pr % 5 == 0 {
        -8.0
    } else if pr % 2 == 0 {
        -3.0
    } else {
        4.0 // odd, awkward residue
    };
    score += class_bonus;

    // Fractional fill: reward high utilization of the bin.
    let fill = (bin_residual as f64) / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (or into its harmonic class), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 18.0;
        } else if next_item_size <= pr {
            score -= 6.0;
        } else {
            // next item cannot go here anyway; slight penalty for wasting fit
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.15 * (100.0 - post_residual as f64).max(0.0);
    }

    // New-bin candidate: penalize opening a fresh bin when the stream is early
    // and open bins exist, but reward it late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 25.0 * progress;
        if open_bins_count == 0 { score -= 50.0; }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 10.0; // existing bins too fragmented, new bin is good
        }
    }

    // Mild penalty if post_residual is below the minimum item size (dead space)
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (below the minimum item size) are pure waste: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that only fit a tiny fraction of future items are nearly dead too.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer consolidating into existing bins, penalize spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; grows with how many bins already fit the item.
        score += 35.0 + 12.0 * fitting_bins_count as f64;
        // But if the best existing fit would leave a dead gap, opening a new bin is fine.
        if post_residual == 0 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it to avoid opening a bin anyway.
        score -= 30.0;
    }

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        // If this placement leaves room exactly for the next item, reward it.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        // If this placement wastes space the next item could have used, penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mild preference toward bins whose residual deviates above the mean
    // (fill the emptiest usable bin first keeps more tight bins available).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post residual is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap <= 2.0 {
                score -= 60.0; // next item fits perfectly after this placement
            } else {
                score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            score += 15.0 * (1.0 - post_residual as f64 / nxt.max(1.0)).abs();
        }
    } else {
        // Last item: just minimize waste strongly.
        score -= 50.0;
    }

    // Compare against mean residual: prefer leaving less than average waste.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized mildly, but less when many bins are open
        // and current item would create a lot of dead space in existing bins.
        let waste_penalty = (post_residual as f64 / bin_capacity as f64) * 80.0;
        score = waste_penalty + 20.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        // If the next item also fits nicely in a fresh bin, encourage opening.
        if next_item_size > 0 && (bin_capacity as u64) >= (item_size as u64 + next_item_size as u64) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
