pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its non-linear couplings
    let x = pr / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Polynomial base: reward tight fits (low post-residual), with curvature
    // that grows later in the stream (dead space matters more as stream ends).
    let mut score = pr as f64 * (1.0 + 1.5 * progress) - 30.0 * x2 * progress - 20.0 * x3;

    // Smooth interaction: mid-range residuals penalized more as progress advances
    score += 25.0 * x * (1.0 - x) * progress;

    // Lookahead coupling: bonus if next item fits smoothly into post-residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let fit_quality = (pr - n) / cap;
            score -= 15.0 * (1.0 - fit_quality) * (1.0 - progress);
        } else {
            // dead space that next item cannot use
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64) * 0.3 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo structure on capacity fractions.
    // Residuals in "dead zones" (very small) are wasted; reward them being avoided.
    let cap_frac = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-10 harmonic tier of post_residual: multiples of 10 are "usable slots".
    let tier = post_residual % 10;
    score += match tier {
        0 => -12.0,           // perfectly harmonic leftover
        1..=4 => -2.0,        // near-harmonic
        5..=9 => 3.0,         // off-harmonic dead zone
        _ => 0.0,
    };

    // Integer-division thresholds: post_residual below 10 is nearly dead space.
    if post_residual < 10 {
        score -= 25.0; // perfect fit reward
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > bin_capacity / 2 {
        score += 10.0; // leaving a half-empty bin is wasteful
    }

    // Lookahead coupling: can next item fit into post_residual (harmonic pairing)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: subtract proportional bonus, extra if harmonic multiple
            let chain = (next_item_size as f64) / cap_frac;
            score -= 10.0 + 20.0 * chain;
            if post_residual % next_item_size == 0 {
                score -= 6.0; // exact harmonic partition
            }
        } else {
            // next item won't fit here; penalize if this bin was its only chance
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty keeps new bins closed unless item is large relative to mean residual.
        score = cap_frac * 0.9 - (item_size as f64) * 0.8 + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open
        }
        if item_size >= 60 {
            score -= 25.0; // large items deserve fresh bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05 * (post / cap_frac);

    // Mean residual alignment: prefer bins near the mean (balanced packing).
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1..=100 stream,
    // small gaps below ~15 are likely unusable) get a steep nonlinear penalty.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits: bonus proportional to fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the leftover: penalize more the smaller the gap
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading into many bins; a new empty bin
    // (bin_residual == bin_capacity) gets penalized so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild attraction toward bins with residuals close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.2;

    // Late in the stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Slight preference for bins whose residual deviates from the mean residual
    // toward smaller values (compact the packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 50.0;

    // 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 100.0; // perfect chaining: next item fills this bin exactly
        } else if diff > 0.0 {
            // next item fits: reward proportional to tightness of the chain
            score -= (next_item_size as f64 / post_residual as f64) * 40.0;
            // extra bonus if chain leaves near-zero residual after two steps
            let two_step = post_residual - next_item_size;
            score -= (two_step as f64 / bin_capacity as f64) * 30.0;
        } else {
            // next item won't fit here: penalize tight fits that strand space
            score += (-diff / bin_capacity as f64) * 25.0;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // but if no open bin fits, new-bin candidate is the only option and wins naturally
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty on waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here: mild penalty, stronger if post_residual is large waste.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor or scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of opening a bin; reduced late in stream or when open bins are fragmented.
        score = 45.0 - 15.0 * progress - 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If some bin fits and mean residual is healthy, discourage opening a new bin.
        score += pressure * (mean_residual / bin_capacity as f64) * 20.0;
        // Large items early benefit from a fresh bin.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit coupling).
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * (gap - mean_residual).abs();
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening over time
    let mut score = norm_pr * (1.0 + 2.5 * progress * progress);

    // Smooth cubic penalty for medium dead space that is hard to fill later
    let dead = norm_pr * (1.0 - norm_pr);
    score += 6.0 * dead * dead * (0.5 + progress);

    // Reward tight fits (near-full bins) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: bonus if next item fits into this bin's post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_fit = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 2.0 * slack_fit * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use
        score += 1.5 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Prefer bins with residual near the mean (keeps residual distribution balanced)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: smooth preference early, discourage late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.6 * progress) + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
