    }

    // New-bin candidate: penalize opening a fresh bin unless current placement
    // would create bad dead space or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress; // cheaper to open bins early
        if item_size as f64 > 0.6 * cap {
