    // Prefer filling bins that deviate below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small "dead" gaps that likely cannot host future items.
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * 8.0; // strong penalty for tiny unusable gaps
        } else if gap < 40.0 {
            score += (40.0 - gap) * 2.0; // moderate penalty for medium gaps
        }

        // If the lookahead item cannot fit in this gap, penalize the dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Reward bins whose gap can host the next item.
            score -= 15.0;
        }
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; make the new-bin candidate less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight nudge to fill fuller bins first.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (near-zero dead space)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post-residual,
    // this is a chain placement — heavily favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: penalize leftover after two placements,
            // but still better than not fitting at all.
            let two_step_left = post_residual - next_item_size;
            score -= 100.0 - two_step_left as f64;
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            score += 30.0;
        }
    }

    // Reward tight fits relative to the item size
    score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare post_residual against mean residual: leaving more than average
    // residual wastes space; leaving less than average is efficient.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Late in the stream, consolidation matters more; penalize small leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    // Mildly discourage opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used again (post_residual < min item size).
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: slight penalty proportional to wasted potential.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, prefer tight fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins below the mean residual (balance reduction).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // New-bin candidate handling: only allow opening a new bin when the item is large
    // relative to residual of typical open bins, or when few bins fit the item.
    if bin_residual == bin_capacity {
        let open_bin_bonus = if fitting_bins_count == 0 {
            -1000.0 // must open a new bin
        } else if fitting_bins_count == 1 {
            -30.0 // competing with the last-chance bin: slight edge to reuse
        } else {
            // New bin attractive when item is big (would leave small post_residual anyway)
            let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
            if big_item { 5.0 } else { 20.0 + 0.2 * open_bins_count as f64 }
        };
        score += open_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post residual, with a non-linear (quadratic) waste curve.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth stream-progress coupling: early on, tolerate larger residuals
    // (bins stay flexible); late, squeeze residual hard.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Interaction: item size vs post residual — reward tight fits (small post)
    // more strongly for large items.
    score -= norm_item * (cap - post) * 0.5;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // are smooth-penalized via a sigmoid-like term on norm_post.
    let dead = 1.0 / (1.0 + (norm_post * 10.0 - 2.0).exp());
    score += dead * 15.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward strongly (smooth bell around exact fit).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let bell = (-(gap * gap) / 50.0).exp();
        score -= bell * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean — picking below-mean residual bins balances the pool.
    score += 0.3 * (post - mean_residual);

    // Mild new-bin penalty scaled by open bins count to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of 10, matching typical item granularity) are favored.
    let class = post_residual % 10;
    score += match class {
        0 => -12.0,                      // perfect harmonic class: highly reusable
        1..=3 => 6.0,                    // nearly-full slivers: dead space risk
        4..=7 => 2.0,                    // mid classes: mildly usable
        _ => 9.0,                        // 8..9: awkward dead space
    };

    // Integer-division thresholds on post_residual: reward coarse bands of leftover.
    let band = post_residual / 20; // 0..5
    score -= band as f64 * 4.0;    // bigger leftover bands are more flexible

    // Dead-space penalty: tiny leftover that no item (>=1) can exploit well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit is golden
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 5.0; // next item cannot follow here
        }
        // Harmonic pair check: item + next forms a near-capacity pair
        if item_size + next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, reduced when stream is late (fewer future items
        // to fill it) and when mean residual of open bins is small.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 - 25.0 * progress - 0.3 * mean_residual;
        // If the item is large relative to capacity, a new bin is more acceptable
        if item_size >= 50 {
            score -= 10.0;
        }
        return score;
    }

    // Tightness reward: filling a bin closer to capacity is better
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Spread control: prefer bins whose residual deviates favorably from the mean
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size of 1..100 stream, treat < 10 as
    // near-dead) are heavily penalized; medium unusable gaps less so.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if pr < 10 {
        // Dead space: gap can never be filled by any item.
        score += 60.0;
    } else if pr < 20 {
        // Nearly dead: only tiny items could use it.
        score += 25.0;
    } else if pr < 30 {
        score += 8.0;
    }

    // If a lookahead item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > pr {
        // Lookahead cannot use this bin's remaining space: mild penalty,
        // stronger when the leftover gap is large (wasted capacity).
        score += (pr as f64) * 0.15;
    } else if next_item_size > 0 {
        // Lookahead fits but leaves further slack: small penalty proportional
        // to the second leftover.
        let second_left = pr - next_item_size;
        score += second_left as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // tight packing into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with the number of already-open bins, so it is only chosen when no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if current item is huge relative to mean residual, opening a
        // fresh bin may be better: reduce the penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 25.0;
        }
        // If no open bin fits at all, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for filling bins with larger residual when stream is
    // early (keep bins flexible), and tighter bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack left over
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 400.0 - (slack as f64).min(60.0) * 3.0;
    }
    // Next item does NOT fit after this placement: penalize depending on wasted residual
    else if next_item_size > 0 {
        let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += dead * 1.5;
    }

    // Penalize creating small unusable dead space (hard-to-fill fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose residual is already below mean (tight bins get used first)
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild preference to pack into existing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Early in stream: be slightly more willing to open fresh bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let new_bin_bonus = 120.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 4.0;

    // Penalize dead space relative to capacity, with a non-linear squaring.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow in this bin; penalize slightly more
            // when the leftover space is small and hard to reuse.
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Global state coupling: penalize bins far from the mean residual
    // when the mean residual is low (fragmented state), reward them when high.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - mean_residual / bin_capacity as f64);

    // Dynamic time horizon: early in the stream, be more willing to open
    // new bins (spread items); late in the stream, pack tightly.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score -= (1.0 - t) * 15.0;
        score += t * 10.0;
    } else {
        // Existing bins get better late via tighter packing incentive.
        score -= t * 6.0 * fill;
    }

    // Small bonus for medium post-residuals that remain generally usable
    // (residual >= 10 keeps the bin viable for typical small items).
    if post_residual >= 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize dead space more strongly late in the stream (cubic coupling).
    score += 60.0 * norm_pr.powi(3) * progress;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = pr / (item_size as f64 + 1.0);
    score -= 20.0 / (1.0 + tightness);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Mild preference to fill bins when many are open, coupled smoothly with mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: make it moderately unattractive unless residuals are large.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: capacity fractions define "usable" dead-space bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Class the post-residual into harmonic bins: 1/2, 1/3, 1/4, 1/6 of capacity.
    // Leftovers in fine-grained classes (small fractions) are "dead space" -> penalize.
    if frac < 1.0 / 6.0 {
        score += 12.0; // near-useless sliver
    } else if frac < 1.0 / 4.0 {
        score += 6.0;
    } else if frac < 1.0 / 3.0 {
        score += 2.0;
    } else if frac < 1.0 / 2.0 {
        score -= 3.0; // half-capable residual is valuable
    } else {
        score -= 6.0; // large residual still highly usable
    }

    // Integer-division threshold: does next_item_size fit into post_residual?
    // Reward exact or near-exact chain fits (modulo small).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual - next_item_size;
        let chain_mod = chain % 10; // harmonic class on tens
        let bonus = if chain == 0 {
            20.0 // perfect two-item packing
        } else if chain_mod == 0 {
            10.0 // clean multiple of 10 leftover
        } else {
            4.0
        };
        score -= bonus;
    } else if next_item_size > 0 {
        // next item cannot chain here: leftover likely wasted
        score += 5.0;
        // but if the leftover is a large fraction, penalize less
        if frac >= 0.5 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are congested
    // or this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; shrinks as stream progresses (sunk bins matter less early).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * (0.9 - 0.25 * progress);
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
        // If open bins are nearly full on average, new bin is fine.
        score -= (mean_residual / cap).min(1.0) * 15.0;
        // Large next item justifies reserving fresh capacity.
        if next_item_size >= (cap * 0.6) as u32 {
            score -= 8.0;
        }
    }

    // Congestion coupling: when many bins compete, prefer tightest fit more aggressively.
    if open_bins_count > 1 && bin_residual != bin_capacity {
        score -= (fitting_bins_count as f64).ln().max(0.0) * 2.0;
        score += (item_size as f64 / cap) * 4.0; // slight preference to fill big items into roomy bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that can never fit a future item (>=1) is pure waste; small gaps
    // (< ~10) are effectively dead. Non-linear penalty rising as post_residual
    // shrinks into the dead zone.
    if post_residual > 0 {
        let dead_zone = 12.0;
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: penalize opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 2.0;
    } else {
        // Reward reusing existing bins, more so when many bins are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits into the post_residual, reward it;
    // if next item is large and post_residual wastes space, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Stream progression: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (a tight bin), placing here consolidates space; slight reward.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit now.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: mild reward scaled by tightness
            score -= 10.0 * (nr / pr);
        } else {
            // next item would NOT fit after this placement: penalize dead space
            score += 8.0 * (nr - pr) / nr;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when the item is large relative to
    // residual space or when no open bin is a good host; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size >= 50 {
            score -= 15.0; // big items pair well in a fresh bin
        }
    }

    // Late in the stream, consolidate harder (avoid leaving many open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large unusable dead space (post residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item nearly fills the remaining space.
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * chain_fit;
        } else {
            // Next item won't chain; penalize leaving moderate but useless space.
            score += 4.0;
        }
    } else {
        // Last item: strongly prefer minimal waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 15.0 + 20.0 * progress;
        // If mean residual of open bins is large, opening a new bin is wasteful.
        new_bin_cost += mean_residual * 0.3;
        // If many bins already fit the item, opening new is worse.
        if fitting_bins_count > 1 {
            new_bin_cost += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        score += new_bin_cost;
    } else {
        // Slight preference for fuller bins among existing bins (best-fit bias).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Global state: with many open bins, consolidate to avoid fragmentation.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean (it's tight),
    // favor using it to preserve large residuals elsewhere.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (mean_residual - bin_res_f) / mean_residual;
        score -= 6.0 * deviation.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: early on tolerate larger residuals; later penalize them
    score += 20.0 * pr_norm * (1.0 - progress) - 15.0 * pr_norm * progress * progress;

    // Smooth quadratic interaction between progress and post residual
    score += 10.0 * (pr_norm - 0.5) * (pr_norm - 0.5) * progress;

    // Penalize dead space that cannot fit a typical future item (smoothly)
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste = ((next - pr).max(0.0)) / cap;
        score += 12.0 * waste * waste * (0.5 + progress);
        // Reward reserving space for the lookahead item
        score -= 6.0 * (pr - next).max(0.0) / cap * (1.0 - progress);
    }

    // Last-chance bin: reward using it smoothly
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 / (total_items as f64).sqrt();

    // Slight bonus for tightening toward mean residual (pack uniformity)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals are grouped into classes of 20.
    // Residuals near the top of a class (e.g. 19, 39, 59) are "almost usable" for
    // small items and get a small penalty; residuals just past a class boundary
    // (0..9) are dead space and are heavily penalized.
    let class = post_residual % 20;
    score += (class as f64) * 0.8;

    // Dead-space band: residuals in 1..=9 rarely fit anything (items >= 10).
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }
    // Perfect fill.
    if post_residual == 0 {
        score -= 35.0;
    }

    // Lookahead coupling: does the next item fit in the post-placement residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: reward, scaled by how snugly the next
            // item nests (smaller leftover after the lookahead is better).
            let lookahead_left = post_residual - next_item_size;
            score -= 12.0 + (lookahead_left as f64) * 0.15;
        } else {
            // The residual can't serve the next item: penalize, but less if the
            // residual is large enough to be generally reusable.
            if post_residual >= 30 {
                score += 6.0;
            } else {
                score += 18.0;
            }
        }
        // Harmonic match: next_item_size in the same 20-class as post_residual
        // implies near-perfect two-item packing.
        if next_item_size <= post_residual && (post_residual % 20) >= (next_item_size % 20) {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fill overall.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a single item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: mildly penalize so we only open a new bin when all open
    // bins would create bad fits. The penalty grows slightly with the number of
    // open bins (bin proliferation control) and with a healthy mean residual
    // (existing bins still have room to absorb items).
    if bin_residual == bin_capacity {
        score += 15.0
            + 0.6 * (open_bins_count as f64)
            + 0.05 * mean_residual.max(0.0);
    }

    // Progression: early in the stream, tolerate more open bins (exploration);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 6.0 * progress;
    }

    // Coupling with mean residual: if this bin's post_residual is far below the
    // mean, we are consuming the "best" bin; if far above the mean, we leave the
    // fleet with lots of scattered space. Reward consuming high-residual bins.
    score += 0.08 * (mean_residual - post_residual as f64);

    // Item-size harmonic: large items (>= 60) should prefer bins with large
    // residuals (already implied), but small items (<= 20) should be steered to
    // bins whose residual is in the 21..40 band to avoid wasting big residuals.
    if item_size <= 20 && post_residual >= 60 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small usable leftover).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: make it moderately attractive only when current bin fits are poor
    // (i.e., item leaves a large awkward gap or doesn't leave room for lookahead).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.35 * (bin_capacity as f64);
        let lookahead_conflict = next_item_size > 0 && next_item_size > post_residual;
        if poor_fit || lookahead_conflict {
            score -= 20.0;
        } else {
            score += 55.0; // keep item in an existing bin when fit is decent
        }
    }

    // Lookahead: bonus if post placement still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here; penalize leftover after that
            let next_left = post_residual - next_item_size;
            score -= 200.0 - next_left as f64;
        } else {
            // next item cannot use this residual: penalize small dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin's tight fit on a small item
    if item_size < bin_residual / 2 && bin_residual < 40 {
        score += 50.0;
    }

    // Late in stream: prefer using existing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 30.0 + 60.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    // (smaller than the minimum conceivable item).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 - 2.5 * post_residual as f64;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 0.05 * slack;
        } else {
            // Penalize blocking the next item proportionally to how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 + 0.15 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing ones (penalize new-bin tendency).
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost of opening a bin.
        score = 100.0;
        // Attractive early or when bins are crowded and mean residual is high.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        score -= 0.3 * open_bins_count as f64;
        if mean_residual < 20.0 {
            score -= 10.0; // all bins nearly full -> new bin is fine
        }
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with residual close to mean (balance load) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight preference for fuller bins (best-fit flavor) when many bins are open.
        score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty
    // that grows super-linearly for large leftover space (dead space).
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes increasingly costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: penalize post_residual that fails to accommodate the
    // lookahead item, smoothly scaled by how close it comes to fitting.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        let usable = ((pr - nxt).max(0.0)) / cap;
        // If the next item cannot fit here, mild penalty growing with gap;
        // if it fits snugly, reward.
        score += 8.0 * gap * gap * (1.0 + progress);
        score -= 6.0 * usable * (1.0 - usable);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin, unless post_residual is huge (bad fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement leaves
    // above-average dead space (fragmentation pressure).
    let frag = (pr - mean_residual).max(0.0) / cap;
    score += 5.0 * frag * frag * (open_bins_count as f64).sqrt();

    // New-bin candidate: neutral-ish baseline, slightly worse than a
    // decent fit but better than a terrible fit.
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (large enough to hold typical small items) are favored.
    let cap = bin_capacity as f64;

    // Reward residuals that are multiples of common class sizes (mod-10 classes)
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // residual exactly on a decade boundary -> very reusable
        if cls == 0 {
            score -= 12.0;
        } else if cls <= 2 {
            score += 6.0; // sliver waste
        } else if cls >= 8 {
            score -= 4.0; // nearly a decade, easy to round down usage
        }
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic capacity fraction: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac >= 0.5 {
        score -= 10.0 * frac; // half-full or more leftover still valuable
    } else if frac < 0.1 && pr > 0 {
        score += 15.0; // dead space below 10% of capacity
    }

    // Coupling with lookahead item: if next item fits the post residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        // extra bonus if next item also lands on a harmonic boundary after chaining
        let chained = pr - next_item_size;
        if chained % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here -> this residual risks becoming dead space
        score += 7.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or many bins are already open with low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_stream = mean_residual < item_size as f64;
        if item_size as f64 > 0.6 * cap || open_bins_count == 0 || (tight_stream && progress > 0.5) {
            score -= 5.0;
        } else {
            score += 20.0;
        }
    }

    // Mild preference for bins with residuals close to the mean (balanced packing)
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100)
    // are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        // Small gap: only usable by tiny items; scale penalty by gap size.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but leaves more dead space — mild penalty.
        score += (post_residual - next_item_size) as f64 * 0.3;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.4 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or all existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its "post_residual" is capacity - item.
        // Make it competitive but not free.
        score += 15.0;
        if item_size >= 50 {
            score -= 10.0; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // fresh bin can also absorb the next item
        }
    }

    // Mild alignment with mean residual state: prefer bins whose residual is
    // below average (tighter bins get filled first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect 2-step lookahead match (post_residual == next_item_size)
    let look_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
    score += look_diff * 0.6;

    // Strong bonus when the next item exactly fills the bin after this placement
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Penalize leaving dead space that no small item (min size 1) can't use,
    // but especially penalize residuals that are unusable relative to typical sizes
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny sliver, likely wasted
    }

    // Compare residual against mean residual across open bins: prefer packing
    // into bins with less residual (tighter bins) to consolidate fullness
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no tight lookahead exists
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * (1.0 - progress);
        // Allow new bin if this item is huge and next item is also large
        if item_size >= 70 && next_item_size >= 60 {
            score -= 40.0;
        }
        // If no open bin fits (fitting_bins_count counts fitting bins only,
        // so a call with residual==capacity means it fits trivially); discourage
        // unless mean residual is very low (all bins nearly full)
        if mean_residual > 25.0 {
            score += 15.0;
        }
    }

    // Mild penalty for opening bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0;

    // Reward near-perfect fills of the current bin
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets a strong extra reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that can never be reused by typical items:
    // small residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty, more if residual is large
            score += 5.0 + 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, prefer consolidating; late, allow more bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * progress;
        // If current item is large, a fresh bin is reasonable.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If open bins have plenty of average room, discourage a new bin.
        score += 0.15 * mean_residual;
    }

    // Prefer bins whose residual is below average (fill fuller bins first).
    if bin_residual != bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
        score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Mild time-decay preference for compactness as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr * (1.0 - norm_pr));

    // Penalize large dead space non-linearly (quartic in normalized residual)
    score += 30.0 * norm_pr * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential-like polynomial
    let tight = (1.0 - norm_pr).powi(4);
    score -= 20.0 * tight;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            let slack_after_next = (pr - next) / cap;
            score -= 12.0 * (1.0 - slack_after_next * slack_after_next);
        } else {
            score += 6.0 * ((next - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" classes (divisible by small moduli) are more valuable.
    let c = bin_capacity as f64;

    // Penalize dead space: small nonzero residuals are wasted capacity.
    if post_residual > 0 {
        let pr = post_residual;
        // harmonic class by divisibility
        let class_bonus: f64 = if pr % 50 == 0 {
            -12.0
        } else if pr % 25 == 0 {
            -9.0
        } else if pr % 20 == 0 {
            -7.0
        } else if pr % 10 == 0 {
            -5.0
        } else if pr % 5 == 0 {
            -3.0
        } else {
            3.0
        };
        score += class_bonus;

        // Dead-space cliff: residuals below the smallest plausible item
        // are nearly useless.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        } else if pr < 30 {
            score += 4.0;
        }
    } else {
        // Perfect closure of a bin is excellent.
        score -= 20.0;
    }

    // Lookahead: does post_residual fit the next item exactly or well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 + (slack as f64) * -0.15; // reward tight fit for next item
        if slack == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: residual must still be generically useful
        score += 2.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    // rather than fragmenting across a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current open bins are crowded
    // or the fit is poor. Penalize opening new bins by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        score += 30.0 - crowd * 2.0 + progress * 10.0;
        // But if placing in an open bin would strand a lot of space, allow new bin
        if post_residual < 25 && bin_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for larger items going into larger-residual bins.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small to hold any plausible future item.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving a gap that exactly blocks the lookahead item's fit class:
    // if next item could have fit in the residual but not in post_residual, waste.
    if next_item_size > 0 {
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 15.0;
        }
        // Reward placements that still leave room for the lookahead item.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual is already high; encourage using lopsided bins.
    let residual_dev = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * residual_dev;

    // Pressure term: when many bins are open, prefer filling existing ones
    // over opening new bins (new bin has bin_residual == bin_capacity, so
    // add a fixed bonus that tight fits must overcome).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item fits after placement; reward closeness
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit: penalize leftover dead space
            score += 8.0 * diff / bin_capacity as f64;
        }

        // Chain potential: post_residual can hold next item plus a small item
        if post_residual > next_item_size && next_item_size > 0 {
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 5.0;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already partially filled
    let cap = bin_capacity as f64;
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty unless item is large relative to typical residual
        let tightness = (item_size as f64) / cap;
        score += 6.0 - 10.0 * tightness;
        // if no other bin fits, opening new bin is necessary: soften penalty
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // large items early in stream benefit from a fresh bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 70 && progress < 0.5 {
            score -= 8.0;
        }
    }

    // Avoid leaving tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize residual that is too small to be useful later.
    let usefulness = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        -40.0 // dead space penalty
    } else {
        0.0
    };
    score += usefulness;

    // Reward near-perfect packing quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 5.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream or when mean residual across bins is still large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / bin_capacity as f64;
        score += 55.0 + 45.0 * (1.0 - progress) + 60.0 * waste;
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
    }

    // Prefer bins whose residual deviates from mean in a way that absorbs item well
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: early on, tolerate loose fits; late, punish dead space harder.
    score += norm_post * norm_post * (pr) * (0.5 + 2.0 * progress * progress);

    // Lookahead: reward bins whose post-residual can host the next item (smooth polynomial bonus).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap) * (gap / cap);
            score -= 6.0 * fit_quality * (1.0 + progress);
        } else {
            let miss = (-gap / cap).powf(2.0);
            score += 4.0 * miss;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins far from the mean residual (fragmentation pressure), smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + open_bins_count as f64 / 10.0);

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
