    } else {
        // dead-space class: penalize residuals that few item sizes can use
        let usable = ((pr as f64) / 10.0).floor().max(1.0) as f64;
        score += (10.0 - usable) * 4.0;
    }

    // Modulo-class coupling: residuals that combine with common sizes (multiples of 10)
    let class = pr % 10;
    if class == 0 {
        score -= 8.0;
    } else if class >= 7 {
