    // Prefer bins with below-mean residual (consolidate space).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New-bin candidate handling: empty bin must prove itself.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so mid-stream when consolidation matters.
        let new_bin_penalty = 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to capacity, a fresh bin is natural.
        score += new_bin_penalty - 20.0 * (item / cap);
        // If no open bin can fit (this is the only option), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild exploration term: early in the stream, keep residuals balanced.
    score += (1.0 - progress) * 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linearly scaled by stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr);

    // Smooth quadratic coupling: small residuals become more costly later in the stream.
    score += 12.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize residuals that cannot fit the lookahead item (smooth falloff).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 18.0 * progress * gap * (1.0 + gap);
    } else {
        // Last item: pure tight fit reward.
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Reward perfect-ish fits smoothly.
    score -= 10.0 * (-norm_pr * norm_pr * 40.0).exp();

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: prefer opening fresh bins when existing fits are loose,
    // but early in the stream keep open bins attractive.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score = pr - 25.0 * (1.0 - progress) * openness + 20.0 * progress * (item_size as f64 / cap);
    }

    // Mild consolidation pressure toward mean residual.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, i.e. common item granularity) are cheap.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if pr % 10 == 0 && pr >= 10 {
        score -= 25.0; // leftover aligned to typical item sizes
    } else if pr < 10 {
        score -= 45.0; // dead space but tiny: effectively a perfect fit
    } else {
        // penalize awkward leftovers quadratically
        score += ((pr % 10) as f64) * 1.8;
    }

    // Lookahead coupling: reward if the next item exactly fills the leftover,
    // punish if leftover is just barely too small for next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0; // chain fit
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.9;
        } else {
            score += (next_item_size - pr).min(40) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: make it unattractive unless current item is huge
    // relative to residuals or the stream is early and fresh bins are cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 + waste * 0.8 - (1.0 - progress) * 25.0;
        if item_size >= 70 {
            score -= 30.0; // big items justify fresh bins
        }
    }

    // Mild preference for tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range dead space (likely unusable for typical items)
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that can't fit the next item but is close to it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer tighter bins relative to the mean residual (best-fit coupling)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits too: good chaining, reward proportionally.
            score -= 0.5 * next_item_size as f64;
        } else {
            // Dead space relative to next item: penalize the gap.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a brand-new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 50.0;
        // If no other bin fits well (few fitting bins), new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
    }

    // Slight preference for filling emptier bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * (1.0 - progress) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong subtraction.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post residual blocks next item but is nonzero: mild penalty.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer filling existing bins maximally.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin, penalized so tight existing fits win.
        score += 10.0;
        // But if no tight fits exist (large mean residual spread) and stream is early,
        // opening a new bin preserves flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness_gap = mean_residual - bin_residual as f64;
        if tightness_gap < 0.0 && progress < 0.7 {
            score -= 6.0;
        }
    } else {
        // Slight preference for bins with residual below mean (consolidating waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Many open bins: encourage closing them out by filling.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // base: post residual, smoothly warped
    let mut score = pr / cap;

    // non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals matter less; early, prefer tight fits
    let warp = (pr / cap).powi(2) * (1.0 - progress) + (pr / cap).powi(4) * progress;
    score += 2.0 * warp;

    // reward filling bins deeply, modulated by progress
    score -= 0.8 * fit_ratio * (1.0 + progress);

    // penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.3 * (nx / cap);
        } else {
            score += 0.5 * (nx - pr) / cap;
        }
    }

    // last-chance bonus: unique fitting bin should be strongly preferred
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // relative residual vs mean residual: avoid bins with unusual residuals
    score += 0.2 * ((pr as f64 - mean_residual) / cap).abs();

    // new-bin candidate: mildly penalize early, allow late when residuals are fragmented
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 0.6 * (1.0 - progress) - 0.4 * fragmentation * progress + 0.1 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small post-residuals are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score += 8.0;
    } else {
        score += 15.0;
    }

    // Harmonic threshold classes via integer division on post_residual.
    let post_class = post_residual / 25; // 0..4 quarters of capacity left
    score += post_class as f64 * 6.0;

    // Lookahead coupling: reward leftovers that can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 { score -= 10.0; }
        } else {
            score += 10.0; // next item can't use this leftover
        }
    }

    // Modulo arithmetic on residual: leftovers that are multiples of common
    // item sizes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bin
    // would leave a large unusable remainder and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_leftover = post_residual > 30 && next_item_size > post_residual;
        if bad_leftover && progress < 0.7 {
            score -= 18.0;
        } else {
            score += 25.0;
        }
    }

    // Slight preference for tighter (below-mean) bins when many bins open.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band (1..=9)
    // are heavily penalized beyond their raw size, since no item (min size 10)
    // can ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: penalize opening a fresh bin unless existing bins
    // would leave bad dead space (implicit via their dead-space penalties).
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.25;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item cannot use the leftover space, the gap is
    // likely dead — add a small extra penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but reward exact fits extra.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement is extremely desirable (chains two items into one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 900.0;
        } else if diff <= 10 {
            score -= 350.0;
        } else if diff <= 25 {
            score -= 120.0;
        } else {
            // Next item fits but leaves a large gap; partial reward.
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item will not fit here; penalize leaving dead space the next item can't use,
        // scaled by how much of the residual is wasted relative to next item size.
        let waste = post_residual as f64 / next_item_size as f64;
        score += 30.0 * waste.min(3.0);
    }

    // Penalize placements that leave residual far below the mean residual
    // (fragmenting the bin pool unevenly), unless it's an exact fit.
    if post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit. Penalize the fresh bin moderately so good existing fits win,
    // but the base post_residual (= full capacity) already makes it unattractive;
    // add extra penalty scaled by how many bins could fit the item.
    if bin_residual == bin_capacity {
        score += 150.0 + 25.0 * fitting_bins_count as f64;
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild reward for using bins that are already mostly full (tight packing).
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that nothing (even lookahead) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 6.0; // post space unusable by next item
    } else if next_item_size > 0 {
        score -= 4.0; // lookahead fits the leftover
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large or fits are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let bias = 18.0 + 45.0 * (item_size as f64 / 100.0) * scarcity
                 + 10.0 * mean_residual / bin_capacity as f64
                 + 8.0 * progress;
        score += bias; // penalize new bin, rewardable via scarcity/large item
        if item_size >= 70 && fitting_bins_count <= 2 {
            score -= 25.0; // big item: fresh bin is fine
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post residual
    let x = pr / cap;
    // Smooth non-linear polynomial coupling with stream progress
    let mut score = pr;
    // Polynomial of x modulated by progress: favors small post_residual more as stream progresses
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += poly * cap * (0.5 + progress);
    // Interaction: post_residual vs mean residual deviation
    let dev = mean_residual - pr;
    score += 0.15 * dev * dev / cap;
    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 0.5 * cap * (1.0 - progress);
    }
    // Lookahead: reward if next item fits in the post residual (smooth reward)
    let fits_next = (next_item_size as f64) <= pr;
    if next_item_size > 0 {
        let ratio = (pr - next_item_size as f64).max(0.0) / cap;
        score -= ratio * cap * (0.3 + 0.4 * progress);
        if fits_next {
            score -= 5.0;
        }
    }
    // Penalize very tight fits less; penalize large dead space via cubic term
    score += x * x * x * cap * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near multiples of small
    // denominators (2,3,4,5 of typical item sizes) are "reusable" classes.
    let r = post_residual;
    if r > 0 {
        let mut reusable = 0.0;
        for d in [2u32, 3, 4, 5, 6, 8] {
            let m = r % d;
            if m == 0 {
                reusable += 1.0 / d as f64;
            } else if m == 1 {
                reusable += 0.1;
            }
        }
        score -= 6.0 * reusable;
    }

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead space: residuals too small for the minimum item size (1) are
    // worthless; residuals below typical item sizes are weak.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if post_residual exactly fits next item,
    // penalty if it nearly-but-not fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Harmonic pairing: post_residual divisible by next_item_size
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item
    // leaves a large, classically reusable residual elsewhere is impossible.
    if bin_residual == bin_capacity {
        score += 40.0
            + (open_bins_count as f64).sqrt() * 5.0
            + mean_residual * 0.5
            - (post_residual as f64) * 1.5;
    }

    // Fraction-of-capacity classes: bins whose fill is a nice fraction
    // (1/4, 1/2, 3/4 of capacity) are harmonically aligned.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    for frac in [0.25f64, 0.5, 0.75] {
        if (fill - frac).abs() < 0.01 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins with residual close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // === Aggressive 2-step lookahead matching ===
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            // Perfect match: the next item will exactly fill this bin -> very strong reward
            score -= 60.0;
        } else if diff <= 10.0 {
            // Near match: next item almost fills the leftover space
            score -= 30.0 - diff * 2.5;
        }
        if post < nxt && post > 0.0 {
            // Dead space with respect to the upcoming item: it cannot use this leftover
            score += (nxt - post).min(40.0) * 0.6;
        }
    } else {
        // Last item of the stream: pure tightness bonus
        if post == 0.0 {
            score -= 25.0;
        }
    }

    // Absolute tiny fragment: unusable dead space for any future item
    if post > 0.0 && post < 5.0 {
        score += 20.0;
    }

    // Last-chance bin: this is the only open bin that fits -> reward proportionally
    // to tightness, so a catastrophic fit still loses to opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Discourage wasteful openings early in the stream; allow them later
        score += 12.0 * (1.0 - progress);
        // Extra penalty if the new bin would be left very loose
        if post > 0.5 * cap {
            score += 8.0;
        }
    }

    // Mean-relative coupling: among comparable fits, prefer filling looser bins
    // (larger residual) and preserve tight bins for tight future fits.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual).min(50.0) * 0.12;
    } else {
        score += (mean_residual - res).min(50.0) * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly (small waste is disproportionately good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * (item_size as f64);

    // Penalize creating dead space that cannot fit the known next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Bonus if this placement leaves room exactly usable by the next item.
            score -= 3.0;
        }
        // Perfect pairing: this item + next item fill bin nicely.
        if item_size as u32 + next_item_size <= bin_residual {
            score -= (next_item_size as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins with larger residuals already.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Penalize opening new bins when plenty of bins exist and item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 + pressure * 2.0 + progress * 5.0;
        // A new bin is attractive only for large items or when nothing fits well.
        if item_size > 60 || (fitting_bins_count == 0) {
            score -= 25.0;
        }
        // Early stream: new bins are cheap to open.
        if progress < 0.2 {
            score -= 8.0;
        }
    }

    // Slight bonus for leaving residuals in "composable" ranges (multiples of common sizes).
    let r = post_residual;
    if r == 0 {
        score -= 20.0; // perfect closure
    } else if r <= 10 {
        score -= 5.0; // near-perfect
    } else if r < 20 {
        score += 2.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth polynomial shaping (favor tight fits)
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling of post_residual with stream progress:
    // early: prefer filling bins loosely; late: penalize large residuals more strongly
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += 0.8 * coupling;

    // Smooth penalty for dead space relative to mean residual across open bins
    let dead = (norm_pr - mean_residual / cap).abs();
    score += 0.5 * dead * (1.0 + progress);

    // Last-chance bonus: only bin that fits -> reward heavily, smoothly scaled by fit tightness
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr * norm_pr);
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 1.5 * fits_next * tightness.max(0.0) * (0.5 + progress);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: make empty bin attractive only when item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 1.2 + 3.0 * (1.0 - large) * (1.0 - large);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity fractions.
    // Residuals in (0,10] are dead space -> strong penalty.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 15.0; // near-dead space
    } else if post_residual <= 25 {
        score += 5.0;
    } else if post_residual <= 50 {
        score -= 4.0;
    } else {
        score -= 2.0; // roomy residual, still usable
    }

    // Modulo-10 harmonic band: residuals that are multiples of 10 pair well
    // with common item sizes (multiples of 10 dominate many streams).
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    // Residuals matching next item exactly -> lookahead bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item can still fit here: keep residual aligned with its class
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 8.0;
        } else if gap <= 25 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here; slight penalty proportional to overflow class
        let overflow = (next_item_size - post_residual) / 20;
        score += 2.0 + overflow as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual <= 10 && post_residual > 0;
        let many_open = open_bins_count > 0;
        if !(bad_fit && many_open) {
            score += 18.0 + (open_bins_count as f64) * 0.5;
        } else {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tight packing).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Early stream: keep bins flexible; late stream: prefer zero residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A post_residual that can't fit even the smallest plausible item (1..10)
    // is pure waste; penalize proportionally to how "almost usable" it is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but potentially usable gap: moderate penalty scaled by tightness.
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fits are gold: reward exact fill.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let bin_pressure = open_bins_count as f64 * 0.35;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        // Next item leaves a tiny dead gap: mild penalty.
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // moderately attractive only when open-bin fits are poor (large post_residual
    // waste or dead-space creation). Baseline: empty bin scores its full capacity
    // minus a discount, so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        // Late in the stream, slightly prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual coupling: when mean residual is high, bins are loose;
    // prefer the tightest placement (small post_residual already does this),
    // but when mean residual is low, be extra strict about waste.
    if mean_residual < 20.0 && post_residual > 0 {
        score += (20.0 - mean_residual) * 0.4 * (post_residual as f64 / 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward scaled by tightness.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 50.0 - tightness.min(50.0);
        } else {
            // Dead space relative to the lookahead item: penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Penalize small unusable residuals (below min item size 1 handled by dead-space logic);
    // penalize large leftovers less than small ones (large leftovers stay reusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: placing into a bin with residual near/below mean
    // keeps the pool balanced; a very large residual bin is better saved for big items.
    let res = post_residual as f64;
    if res > mean_residual * 1.5 {
        score += (res - mean_residual * 1.5) * 0.8;
    } else if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    }

    // New empty bin candidate: make it unattractive unless it's early in the stream
    // or no real alternative exists (fitting_bins_count would be 0 for open bins,
    // but the new-bin call still gets fitting_bins_count of open bins that fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 + 300.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // new bin can serve the (large) next item too
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item could ever fill.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 100.0;
    } else if post_residual < 10 {
        // small unusable slivers are cheap only if truly tiny
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many open bins already, discourage spreading thin.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin
    // (leaves room for a perfect follow-up pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large residuals
            // that block compact packing.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer filling bins with larger residuals when few bins fit the item,
    // to consolidate open bins.
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    // Slight time-decay pressure to close out bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let fit = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
    let mut score = pr as f64;

    // smooth non-linear coupling: dead-space penalty grows super-linearly for small residuals
    let dead = (1.0 - x).powi(3) * cap * 0.5;
    score -= dead;

    // stream-progress coupling: later in stream, prefer tighter packing (small post_residual)
    let progress_weight = 0.3 + 0.7 * t * t;
    score += progress_weight * pr * (1.0 + x * x);

    // last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 6.0 * (n - pr) / cap * 10.0;
        }
    }

    // scarcity of fitting bins: slight reward proportional to rarity
    score -= 10.0 * fit * (bin_residual as f64 - item_size as f64) / cap;

    // mean-residual coupling: penalize bins far from mean residual (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 + t);

    // new-bin candidate: make it moderately attractive only when item is large relative to typical residual
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 30.0 * (1.0 - large) - 20.0 * large * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but penalize tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Harmonic class of post_residual: modulo classes mod 10
    let pr = post_residual as i64;
    let class = (pr % 10) as f64;
    score += class * 0.8; // prefer residuals landing on multiples of 10

    // Lookahead coupling: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size < post_residual {
            // fraction of next item into post_residual
            let frac = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * frac;
            // integer division threshold: post_residual can hold >= 2 next items
            if post_residual / next_item_size >= 2 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: residual likely wasted
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins with decent fit,
    // but allow opening when existing residuals are fragmented
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // if mean residual is small (bins nearly full), opening new bin is fine
        if mean_residual < 20.0 {
            score -= 25.0;
        }
    }

    // Progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: prefer bins below mean residual (consolidation)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Capacity fraction thresholds on post_residual
    if post_residual == bin_capacity / 2 {
        score -= 8.0; // half-full residual is a nice harmonic target
    }
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 5.0; // divisor of capacity: perfectly tileable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Gaps too small for the lookahead item are likely to become dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (chaining).
        score -= 12.0;
    }

    // Perfect / near-perfect fits are gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, favor consolidation into
    // existing bins; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when this bin would leave
    // a large, useful residual while open bins are fragmented/dead-spacey.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 15.0 + open_bins_count as f64 * 3.0;
        // If the item is large, a fresh bin guarantees a clean, useful residual.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If mean residual across open bins is small (fragmented), opening
        // a new bin is preferable to forcing a bad fit.
        if mean_residual < item_size as f64 + 10.0 {
            score -= 30.0;
        }
        // If no existing bin fits (fitting_bins_count == 0 counting only this
        // new bin as candidate), opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward keeping residual near useful sizes.
        // A residual that is exactly next_item_size or >= 10 is reusable.
        if post_residual >= 10 {
            score -= 8.0;
        }
        // Penalize bins whose residual was already small (wasting them).
        if bin_residual < item_size + 10 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 {
        // Penalize mismatch between post_residual and next item size
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        // Reward if the next item still fits in the bin after placement
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
        }
    }

    // Penalize creating tiny unusable dead space (post_residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a brand-new bin when open bins could fit (new-bin candidate call)
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.5;
        // Less penalty if few open bins or mean residual is low (fragmented bins)
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins below mean residual (tighter fits first)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = (post_residual as f64).ln().max(0.0);
        score += 4.0 * dead;
    }
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or many bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 25.0 - 20.0 * progress + 30.0 * pressure;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Global state: prefer bins deviating from mean residual (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in stream: consolidate, fill existing bins harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * pr_norm);

    // Reward tight fits via cubic term on normalized post-residual
    score -= 12.0 * (1.0 - pr_norm).powi(3);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.6 * (nx - pr);
        } else {
            score -= 0.15 * (pr - nx).min(cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when bin deviates from mean residual (prefer balanced fills)
    score += 0.1 * (pr - mean_residual).abs();

    // Encourage opening new bins early when current bin would be nearly full
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    // Late-stream: consolidate into existing bins
    score -= 5.0 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residual divisible by small moduli (likely reusable)
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
        if post_residual % 3 == 0 {
            score -= 3.0;
        }
        // Dead-space penalty: tiny odd residuals are hard to fill
        if post_residual % 2 == 1 && post_residual < 12 {
            score += 8.0;
        }
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pairing bonus: post_residual exactly accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    }
    // Next item cannot use leftover: penalize large leftovers
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fraction-of-capacity thresholds
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        score += 6.0; // sliver of space
    } else if frac >= 0.10 && frac <= 0.30 {
        score -= 5.0; // useful mid-range leftover
    }

    // Early stream: prefer packing into existing bins (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Many open bins with high mean residual: discourage fragmentation
    if open_bins_count > 5 && (post_residual as f64) < mean_residual {
        score += 2.0;
    }

    // New-bin candidate baseline: keep it slightly unattractive unless leftovers are terrible
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin pairs well with upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Next-item lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalty scaled by gap smallness.
        score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual < bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize slightly more when many bins are open,
        // less when few bins are open (early stream, spreading can help).
        score += open_pressure * 0.5 - 4.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // filling it consolidates fragments.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.2;
    } else {
        score += (res - mean_residual) * 0.05;
    }

    // Late-stream tightening: favor tight fits more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: mild reward, tighter is better
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit after placement: penalize leaving awkward gap
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below mean
    // (tight packing) and penalize bins ending far above mean (wasteful)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: neutral-ish but penalize when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 50.0;
        // opening a new bin is attractive if no open bin fits well
        if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size as u32) {
            score += 20.0;
        }
        // discourage opening new bins early in the stream
        score += (step_index as f64 / total_items.max(1) as f64) * -0.0;
    }

    // Mild preference to fill bins as stream progresses
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 50.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += 8.0 * (next_item_size as f64 / cap);
        }
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // or residual would be wasted anyway.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred for good fits.
        score += 15.0;
        // But if the item would leave a lot of dead space in any bin anyway,
        // opening fresh becomes attractive (fresh bin keeps flexibility).
        let waste = (bin_capacity - item_size) as f64;
        if waste > 0.5 * cap {
            score -= 0.35 * waste;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (keeps balance).
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Fewer open bins is better: tiny reward for using existing bins.
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: strongly prefer small post_residual (quadratic + quartic coupling)
    let mut score = norm_post.powf(2.0) * 40.0 + norm_post.powf(4.0) * 60.0;

    // Smooth interaction: item size vs. remaining space — large items prefer tight fits
    let coupling = (norm_item * (1.0 - norm_post)).powf(2.0);
    score -= coupling * 25.0;

    // Stream-progress coupling: early on tolerate slack (future items may use it),
    // late in the stream squeeze residuals harder.
    let progress_term = (1.0 - progress) * norm_post * 12.0 - progress * norm_post * 8.0;
    score += progress_term;

    // Perfect fit reward (smooth via exponential instead of hard threshold)
    let tightness = (-norm_post * 30.0).exp();
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
    }

    // Mean residual coupling: if open bins are generally loose, penalize leaving
    // another loose residual; if bins are tight, reward keeping this one usable.
    let mean_norm = mean_residual / cap;
    score += (mean_norm - norm_post) * 6.0;

    // New-bin candidate handling: an empty bin is attractive only if the item is
    // large relative to capacity or progress is early (long stream ahead).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0
            - norm_item * 14.0
            - (1.0 - progress) * 8.0
            - (open_bins_count as f64).ln().max(0.0) * 1.5;
        score += new_bin_penalty;
    }

    // Lookahead: if the next item fits snugly into the post residual, reward it.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post - next).abs();
        if next <= post {
            score -= (-gap / cap * 25.0).exp() * 10.0;
        } else {
            score += (next - post) / cap * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "usable" classes (multiples of common item sizes) are preferred.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10 -> highly reusable leftover.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        // Penalize awkward leftovers by distance to nearest multiple of 10.
        let d = (post_residual % 10).min(10 - post_residual % 10) as f64;
        score += d * 0.8;
    }

    // Class B: post_residual divisible by 5 (half-class) -> mild bonus.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 2.0;
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let pr = post_residual;
    if pr < 10 {
        // Unusable dead space for items >= 10: heavy penalty.
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    } else if pr >= 50 {
        // Large leftover is flexible: reward.
        score -= 4.0;
    }

    // Lookahead harmonic coupling: does post_residual exactly fit next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect chain fit
        } else if next_item_size <= pr {
            // Harmonic class match: next item's class divides leftover band.
            if pr % next_item_size == 0 {
                score -= 8.0;
            } else if next_item_size % 10 == 0 && pr >= next_item_size {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover should be
            // small then, penalize big wasted space.
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tightest fit (already via post_residual),
        // add mild congestion penalty to spread load.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score that
    // beats only truly bad placements (small dead-space leftovers).
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 15.0;
        // Late in stream, opening new bins is cheap-ish; early, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: if open bins are generally full, keep this
    // bin's leftover small (tight packing); if bins are loose, relax.
    let gap = (mean_residual - post_residual as f64).abs();
    score += gap * 0.05;

    // Mild pressure against accumulating many open bins with sloppy fits.
    score += (open_bins_count as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical future items are effectively wasted capacity.
    if post_residual > 0 {
        // Dead space = residual too small for the smallest plausible item (<=10).
        if post_residual < 10 {
            score += 25.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // Smoothly penalize small-but-not-tiny gaps; gap in 10..~30 is awkward.
            let awkward = ((30.0 - post_residual as f64).max(0.0)) / 30.0;
            score += 8.0 * awkward * awkward;
        }
        // Perfect fit bonus: post_residual == 0 handled below.
    } else {
        // Exact fill: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (waste ratio).
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 6.0 * waste_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Next item won't fit here: penalize leaving a gap next item can't use.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but relax pressure when this bin would otherwise be a poor fit.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure;

    // Mean residual coupling: prefer bins whose residual is below average
    // (concentrate packing into already-opened bins with little room).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins are preferred unless they fit terribly.
        let mut nb = 12.0 + pressure;
        if fitting_bins_count == 0 {
            // No open bin can fit: new bin is the only option.
            nb -= 100.0;
        } else if fitting_bins_count == 1 {
            // The single fitting bin is a last chance; only open new bin
            // if that bin would leave a large dead gap.
            if post_residual < 10 {
                nb -= 30.0;
            }
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is already good (base = post_residual).

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted lookahead potential.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste.min(30.0);
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent existing bins exist (new-bin candidate check).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
        // If item is large and no good fit exists, new bin is less penalized.
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Slight penalty on very tiny dead space (< 10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_waste as f64 / (bin_capacity as f64));
            if slack_waste < 10 {
                score += 10.0; // would create sliver for next item
            }
        } else {
            // Next item won't fit here; mildly penalize hoarding space it can't use.
            score += 5.0;
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score -= 30.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (reduce bin count pressure).
    let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, unless
        // existing fits are poor (large mean residual mismatch).
        let new_bin_penalty = 45.0 + 55.0 * progress;
        let fit_quality = (post_residual as f64 / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score += new_bin_penalty - 20.0 * fit_quality.max(0.0);
    } else {
        // Existing bin: slight late-stream consolidation reward.
        score -= 10.0 * progress * fill_frac;
    }

    // Mild penalty when this bin's residual deviates far from mean residual
    // (encourage balanced residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs() / (bin_capacity as f64);
    score += 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (small post_residual); later, tolerate
    // spreading across bins since residual fragmentation matters more.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += poly * cap * (0.5 + progress);

    // Penalize wasted space relative to the mean residual of open bins.
    score += 0.35 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still host the next item;
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 0.15 * (ni - pr);
        }
    }

    // Mild penalty for proliferating many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-unattractive unless residuals
    // of open bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it falls into.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 residual fraction

    // Integer-division thresholds on post_residual (harmonic quarters of capacity).
    let quarter = post_residual / (bin_capacity / 4); // 0..4 class
    match quarter {
        0 => score -= 25.0,           // near-perfect fill: strongly reward
        1 => score -= 8.0,            // small dead space: mild reward
        2 => score += 4.0,            // half-full leftover: mild penalty
        _ => score += 12.0,           // large leftover: penalty
    }

    // Modulo arithmetic: residual in "awkward" classes (e.g. leaves residue that
    // only tiny items can use) get penalized.
    let m = post_residual % 10;
    if m == 1 || m == 2 {
        score += 6.0; // nearly unusable sliver
    } else if m >= 7 {
        score -= 3.0; // chunky residual, likely reusable
    }

    // Coupling with next item (lookahead): reward if next item fits the post residual well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_next = nx / pr.max(1.0);
            if fill_next > 0.8 {
                score -= 15.0; // next item almost exactly fills leftover
            } else if fill_next > 0.5 {
                score -= 5.0;
            } else {
                score += 3.0; // next item wastes the class
            }
        } else {
            // next item won't fit here anyway; residual class matters more
            score += 2.0;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless residual would be terribly small.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; scale with stream progress (early: cheaper to open bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * (0.35 + 0.25 * progress) + (open_bins_count as f64) * 2.0;
        // if item is large relative to capacity, opening fresh is fine
        score -= item_size as f64 * 0.15;
    }

    // Mean residual coupling: if this bin is far from the mean residual, slight penalty
    // (encourages balanced residual classes across bins).
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (sizes >= 1) are wasted; penalize tiny gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits (small but nonzero leftovers are bad,
    // exact fits are great).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are "odd" bins;
    // prefer placing into bins near the mean unless the fit is tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small miss), slight penalty for blocking.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: opening a bin is only attractive when no open bin
    // is a decent host (large item relative to typical residual, or many
    // bins already open with poor fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_hosts = (fitting_bins_count == 0) as i32;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let bonus = 25.0 + 40.0 * poor_hosts as f64 + if big_item { 30.0 } else { 0.0 }
            + 10.0 * progress;
        score += bonus; // default: keep new bin unattractive
        if poor_hosts == 1 {
            score -= 200.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: match post_residual to next_item_size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.0
        };
        score += gap;
        // Perfect lookahead match is a strong reward.
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Next item can't fit anywhere else and fits here: keep this bin viable.
        if fitting_bins_count == 1 && post_residual >= next_item_size {
            score -= 150.0;
        }
    }

    // Penalize bins whose residual deviates strongly from the mean (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev.abs();

    // Last-chance bin: opening a new bin is costly, prefer using it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // New empty bin candidate: penalize unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin also serves next item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * fill * fill * fill;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: prefer leaving room exactly for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual as i64 == next_item_size as i64 {
            score -= 12.0; // perfect two-item chain
        }
        // If next item cannot fit anywhere else, keep room for it.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Global residual pressure: when mean residual is high, prefer spreading load
    // into emptier bins; when low, prefer tight packing.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Time horizon: early in the stream, be conservative (slight preference for
    // new bins when fit is poor); late in the stream, squeeze into existing bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * t * fill;

    // Discourage opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But allow new bin early if this item is huge and fit would be very loose.
        if fill < 0.35 && t < 0.3 {
            score -= 8.0;
        }
    }

    // Mild penalty for bins that are already very full (fragmentation risk).
    if bin_residual < 20 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) penalty
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: waste penalty grows with stream progress (late = stricter)
    let progress_coupling = 0.6 + 1.4 * progress;
    score += progress_coupling * 8.0 * norm_pr * norm_pr;

    // Tight fit reward: smooth function of normalized item size
    let item_frac = item_size as f64 / cap;
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 6.0 * item_frac * tightness;

    // Dead-space avoidance: residuals too small for typical items are bad,
    // smooth trough around residual ~ mean item size
    let dead = (pr - 20.0).abs() as f64 / cap;
    score += 2.0 * dead * dead * (1.0 + progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Smooth penalty proportional to shortfall
        let shortfall = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 4.0 * shortfall * shortfall;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor fits;
    // penalty shrinks as stream progresses (early on, opening bins is cheap)
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.6 * progress) + 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate waste)
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "small"
    // classes are near-perfectly packed; reward them heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division thresholds on post_residual.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Modulo arithmetic: residuals that are multiples of small item sizes
    // (10, 20, 25) are reusable by future items -> reward.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Dead-space penalty: residual that is hard to fill (odd, non-divisible,
    // small but nonzero). Penalize residuals in (0,10) that aren't 0.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let n = next_item_size as f64;
            let leftover = pr - n;
            // reward proportionally to how little is left after chaining
            score -= 15.0 * (1.0 - leftover / cap);
            if leftover == 0.0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this residual at all -> mild penalty
            score += 5.0;
            // but if residual is a harmonic multiple class still useful later
            if post_residual % 10 == 0 && post_residual >= 10 {
                score -= 3.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        // but if post residual would be tiny dead space, soften the reward
        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // New-bin candidate handling: prefer reusing open bins generally.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are crowded
        // (mean residual low) and the item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item = item_size as f64;
        let crowdedness = 1.0 - (mean_residual / cap).min(1.0);
        let openness = (open_bins_count as f64) / 8.0;
        score += 25.0 + 20.0 * (1.0 - crowdedness) + 10.0 * progress - 8.0 * openness;
        // large items into fresh bins are fine
        if item > 50.0 {
            score -= 10.0;
        }
        // never let a fresh bin beat a perfect fit elsewhere
        if post_residual == 0 || fitting_bins_count >= 1 {
            score += 15.0;
        }
    }

    // Mild preference for tighter existing bins (small residual before placing).
    score += (bin_residual as f64) * 0.05;

    // Spread-awareness: many open bins with large mean residual -> favor
    // consolidating into the emptiest bins to close others sooner.
    if open_bins_count > 3 && mean_residual > cap * 0.4 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1)
    // can exploit are fine, but tiny awkward gaps (1..=9) are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that neither the current nor next item can use,
    // but slightly favor gaps >= next_item_size (usable by lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; opening new bins is discouraged.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // (high mean residual means little slack left anywhere).
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        if crowd < 0.15 {
            score -= 45.0; // bins nearly full: open a fresh one
        } else {
            score += 55.0 + 40.0 * crowd; // plenty of slack: reuse bins
        }
    }

    // Mild preference for bins with below-average residual (concentrate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead-space elimination)
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here; mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // post_residual too small for next item: dead space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when many bins are open but few fit
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are fragmented
        score += 120.0 + 10.0 * open_bins_count as f64;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 40.0; // fresh bin is good for the lookahead item too
        }
    }

    // Late in the stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tightness of the fit: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let post_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (super-linear in fill ratio).
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that becomes unusable: residuals below the smallest
    // plausible item (assume ~10) are wasted unless they fit the lookahead item.
    if !is_new_bin {
        let dead = (post_residual as f64) < 10.0
            || (next_item_size > 0 && post_residual < next_item_size);
        if dead {
            score += 12.0 * post_ratio + 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a chain fit — reward it heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward proportional to how well the next item would fill it.
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // New-bin policy: opening a bin is expensive; make the empty candidate
    // unattractive unless it's early in the stream (room to accumulate pairs)
    // or the current fit is terrible.
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let early_bonus = (1.0 - progress) * 8.0;
        score += 20.0 - early_bonus;

        // If many bins are open with large mean residual, opening another bin
        // fragments capacity — penalize more.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 15.0 {
            score += 10.0;
        }
        // Small items into a fresh bin early is fine (room to pair later).
        if item_size <= 40 && progress < 0.5 {
            score -= 6.0;
        }
    }

    // Mild time-horizon term: later in the stream, consolidation matters more,
    // so slightly favor reusing existing bins (handled via is_new_bin above)
    // and prefer bins whose residual is close to the item (best-fit sharpening).
    if !is_new_bin {
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = norm_pr * norm_pr * (2.0 + 2.0 * progress) + norm_pr * 1.5;

    // Reward near-perfect fits more strongly as stream progresses
    score -= 3.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual (wasted capacity)
    let mean_norm = mean_residual / cap;
    score += 1.2 * (norm_pr - mean_norm).abs();

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 1.5 * (next_item_size as f64 / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 0.8 * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0));
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate: make it attractive only when stream is early or fit is bad
    if bin_residual == bin_capacity {
        let badness = (item_size as f64 / cap).powi(2);
        score = 2.5 - 2.0 * progress - 1.5 * badness;
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod small divisors
    let pr = post_residual;
    let class2 = (pr % 2) as f64;
    let class3 = (pr % 3) as f64;
    let class5 = (pr % 5) as f64;
    let class10 = (pr % 10) as f64;

    // Prefer leftovers that fall into "usable" harmonic classes
    // (residuals divisible by common small item sizes are more likely reused)
    score -= (3.0 - class3) * 1.5;
    score -= (1.0 - class5) * 1.0;
    score -= (1.0 - class2) * 0.5;
    score += class10 * 0.8;

    // Integer-division thresholds on post_residual: dead-space bands
    let band = pr / 10; // which decade of leftover space
    score += (band as f64).powi(2) * 0.35;

    // Perfect-fill reward
    if pr == 0 {
        score -= 25.0;
    } else if pr < 10 {
        // tiny dead space is nearly worthless
        score += 6.0;
    }

    // Capacity fraction coupling: how full the bin becomes
    let fill = (bin_residual as f64 - post_residual as f64) / cap;
    score -= fill * 8.0;

    // Lookahead: harmonic match between leftover and next item
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            let diff = pr - n;
            // next item exactly consumes leftover (mod-coupled classes)
            if diff % 5 == 0 { score -= 5.0; }
            if diff % 10 == 0 { score -= 4.0; }
            score -= (diff as f64).powi(2) * 0.02;
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by gap
            score += ((n - pr) as f64) * 0.15;
        }
        // big next item: keep large residuals available
        if n > 50 && pr >= n {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless current leftovers are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * (open_bins_count as f64);
        score += 10.0 - fragmentation * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 4.0; // reserve space logic: fresh bin good for big next item
        }
    }

    // Stream progression: early on, be pickier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If this bin can host the next item too, bonus (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins with residuals far from mean (consolidate big gaps).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

