            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 500.0;
            }
        } else {
            // next item cannot fit into post_residual: penalize wasted potential
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: just minimize post_residual
        score -= 50.0;
    }

    // Compare against mean residual: bins below mean residual are tight/valuable
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0);

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive if item is large relative to capacity
    if bin_residual == bin_capacity {
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in the stream: prefer closing bins tight, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage opening yet another bin
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).max(0)
        } else {
            post_residual as i64
        };
        score += 0.6 * dead as f64;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: bonus if next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (8.0 - gap as f64 * 0.15).max(0.0);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid leaving large unusable gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.25;

    // Relative to mean residual: prefer bins whose post residual is below average
    // (concentrate waste in few bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.5 && fitting_bins_count > 0;
        if poor_fit {
            score += 45.0;
        } else {
            score += 15.0;
        }
        // Late stream: opening new bins is cheaper than scattering.
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic in post_residual modulated by stream progress
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize near-full bins less as stream progresses (tight packing desirable early)
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Interaction: post_residual vs mean residual deviation
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev;

    // Lookahead coupling: reward if next item fits smoothly in post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 10.0 * (1.0 - fit_gap / cap) * (pr >= nx) as i32 as f64;
        score += 6.0 * (fit_gap / cap) * (pr >= nx) as i32 as f64;
    }

    // Last-chance bonus: only one fitting bin, smooth sigmoid on progress
    if fitting_bins_count == 1 {
        let sig = 1.0 / (1.0 + (-6.0 * (progress - 0.5)).exp());
        score -= 15.0 * sig;
    }

    // Mild penalty for spreading across many open bins, smoothed
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress);

    // New-bin candidate handling: prefer using existing bins unless residual waste is large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into buckets
    // by integer division. Small leftovers (tight fits) are desirable.
    let cls = post_residual / 10; // class 0..=10 (0 = perfect fit)
    let cls_bonus: f64 = match cls {
        0 => -40.0,
        1 => -18.0,
        2 => -8.0,
        3 => -2.0,
        4 => 3.0,
        5 => 8.0,
        6 => 12.0,
        7 => 15.0,
        8 => 17.0,
        9 => 18.0,
        _ => 19.0,
    };
    score += cls_bonus;

    // Modulo coupling: residuals divisible into useful chunks are friendlier.
    let m = post_residual % 20;
    score -= match m {
        0 => 6.0,
        5 | 10 | 15 => 3.0,
        _ => 0.0,
    };

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves an awkward remainder
            let rem = post_residual - next_item_size;
            let awkward = (rem > 0 && rem < 10) as i32 as f64;
            score -= 10.0 - awkward * 8.0;
        } else {
            // next item cannot use this residual: penalize wasting space
            score += (next_item_size.min(post_residual + 40) as f64) * 0.15;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and the stream is not too far along.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = post_residual < 10;
        if !tight && fitting_bins_count >= 1 {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins below mean residual (balance load lightly).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
