    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 3.0; // bin likely reusable by the very next item
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with smaller residual among equally fitting bins (best-fit flavor).
    score += bin_residual as f64 * 0.08;

    // Prefer reusing bins that are already relatively full (residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Dynamic time horizon: early in the stream, keep bins flexible (mild penalty for very
    // small post_residual that wastes space); later, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let aggression = 0.5 + 1.5 * progress;
    score -= tight * 10.0 * aggression;

    // Many open bins: encourage consolidation by penalizing opening new bins.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But if nothing else fits well, new bin shouldn't be absurdly bad.
        score += new_bin_penalty;
    }

    // Slight bonus for placing large items into the emptiest bins (avoid fragmenting full bins).
    if item_size > bin_capacity / 2 && bin_residual >= bin_capacity - 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (norm_pr * norm_pr) * 8.0 * (0.5 + p2) * cap;
    score -= (norm_pr) * (1.0 - norm_pr) * 6.0 * (0.5 + p3) * cap;

    // Tight fit reward scaled smoothly by progress
    let fit = item_size as f64 / cap;
    score -= fit * fit * 10.0 * (0.5 + progress);

    // Penalize dead space: small post_residual that is still > 0
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 5.0 + 5.0 * progress;
        } else {
            let waste = (next_item_size as f64 - pr) / cap;
            score += waste * 10.0;
        }
    }

    // Mild penalty for many open bins with large mean residual
    score += (open_bins_count as f64).sqrt() * 0.5 * (mean_residual / cap);

    // New-bin candidate: prefer opening a new bin early, discourage late
    if bin_residual == bin_capacity {
        score += 25.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Dead-space penalty: small leftovers (< 10, the min item size) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward: exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Harmonic class of post_residual via integer division thresholds on capacity:
    // classes [0,10),[10,25),[25,50),[50,75),[75,100)
    let class = post_residual / 25; // 0..4
    match class {
        0 => score -= 8.0,   // tiny leftover: bin nearly closed, good
        1 => score -= 2.0,   // small but usable
        2 => score += 3.0,   // half-ish leftover: mediocre
        3 => score += 6.0,   // large leftover: weak packing
        _ => score += 9.0,   // nearly empty bin used for big item: wasteful
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / pr;
            score -= 15.0 * fill;
            // Harmonic bonus if next item exactly consumes the remainder class.
            if post_residual - next_item_size < 10 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit: penalize more if this bin was the only option.
            if fitting_bins_count == 1 {
                score += 10.0;
            }
            // Modulo-style penalty: leftover that no typical item (multiple of 10)
            // can use is dead space.
            if post_residual % 10 != 0 && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: only one fitting bin, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        // Opening a new bin is good early or when mean residual is small (bins tight).
        score = score * 0.5 - 5.0 * (1.0 - fragmentation) * (0.5 + progress);
        // Don't open a new bin if a decent fit exists elsewhere.
        if frac < 0.3 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) via smooth coupling.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 8.0 * tightness;

    // Mild pressure to keep the number of open bins low.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Pressure from number of open bins: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // Lookahead: if next item cannot ever fit post residual but could fit current residual, mild penalty.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means reusing an existing bin is better).
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits (low post_residual).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: excellent, reward proportionally to slack left after the next item.
            let after_next = post_residual - next_item_size;
            score -= 30.0 + 20.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space that is too small to be useful.
            if post_residual < next_item_size {
                score += 12.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter" fits,
    // which is generally good for packing; reward that.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and the item fits reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus a discount only if no other bin fits well.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 70.0; // forced new bin
        } else if post_residual as f64 > mean_residual {
            score -= 20.0; // current bins are quite full; fresh bin may be fine
        }
    }

    // Early-stream exploration: slightly favor keeping few bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 4.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    } else {
        // Last item: prefer fullest packing, any residual is waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it only wins
    // when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening a new bin is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open with slack, discourage yet another bin.
        score += 0.8 * open_bins_count as f64;
        // If mean residual is large, open bins likely can absorb the item.
        score += 0.3 * mean_residual;
    } else {
        // Prefer bins already below mean residual (consolidating slack).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Mild global pressure: many open bins -> consolidate into existing ones.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    // Time-horizon coupling: early on, keep bins balanced; late, pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: tight fit preferred (low post residual), with smooth non-linear shaping.
    let mut score = pr as f64;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let tight = 1.0 - fit; // 0..1, higher = tighter fit
    score -= tight * tight * (40.0 + 60.0 * progress);

    // Penalize dead space that is too small for typical future items (smooth curve).
    let dead = fit * (1.0 - fit); // peaks at half-full residual
    score += dead * 20.0;

    // Lookahead coupling: if next item fits into post residual, reward smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 30.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 15.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: only one fitting bin; using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure against opening new bins when many are open and mean residual is high.
    let mean_fit = mean_residual / cap;
    score += 0.5 * open_bins_count as f64 * (1.0 - mean_fit);

    // Early stream: slightly favor consolidating into existing bins (smooth ramp).
    score += 10.0 * (1.0 - progress) * (fit - 0.5).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod 10 classes) ---
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Residuals in "harmonically useful" classes (0, 5, and small values) are
    // more likely to be filled by future items; penalize dead zones.
    if pr == 0 {
        score -= 25.0; // perfect closure: best possible outcome
    } else if pr <= 10 {
        score -= 12.0; // small gap, easily fillable
    } else if pr <= 20 {
        score -= 4.0;  // moderately fillable
    } else if pr <= 40 {
        score += 2.0 + 0.1 * class; // dead-zone risk grows
    } else {
        score += 5.0 + 0.05 * (pr as f64 - 40.0); // large residual: wasteful
    }

    // --- Lookahead: does the next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly or leaves a good class again
            let next_post = pr - next_item_size;
            if next_post == 0 {
                score -= 18.0; // two-step perfect closure
            } else if next_post <= 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else if next_item_size > pr && next_item_size <= bin_capacity {
            // Next item won't fit here; a near-full bin is fine, but leaving
            // a large unusable gap for it is bad.
            if pr > 0 && pr < 10 {
                score += 3.0; // awkward sliver that blocks the next item
            }
        }
    } else {
        // Last item of the stream: prefer tightest closure aggressively
        score = pr as f64 * 1.5;
    }

    // --- Last-chance bonus: only this bin fits the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; // avoid opening a new bin if this is the only option
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of consuming a new unit of capacity.
        // Attractive when open bins would be left with ugly residuals.
        score = bin_capacity as f64 - (item_size as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room for a paired placement in the fresh bin
        }
        // Late in the stream, opening new bins is less recoverable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // --- Congestion modulation: many open bins -> prefer consolidation ---
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Mean-residual alignment: prefer bins close to the mean residual ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // --- Modulo tiebreak on bin residual: harmonically "round" bins first ---
    let rmod = bin_residual % 10;
    if rmod == 0 {
        score -= 1.5;
    } else if rmod == 5 {
        score -= 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: if the leftover gap cannot host the lookahead
    // item, that residual becomes dead weight -> penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.5 * (next_item_size - post_residual) as f64;
    }
    // Perfect closure bonus (zero waste).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward residuals that sit below the current mean residual of open bins
    // (this bin is already tighter than average -> prefer packing here).
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64).min(50.0);
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage creating another one.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.4 * open_bins_count as f64;
    } else {
        score -= 1.0 + 0.05 * open_bins_count as f64;
    }

    // Late-stream consolidation: near the end, prefer tightest possible fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into post_residual: strong lookahead bonus scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post-residual too small for next item: dead-space penalty, worse if very small.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins already tighter than average (good packing density).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // but allow it when post_residual would be perfectly tight.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { 80.0 } else { 0.0 };
        score += open_pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late in the stream, close gaps aggressively (avoid many tiny leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 40.0;

    // Penalize dead space: post residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
        } else {
            // Next item won't chain here; penalize more if the leftover is awkward.
            score += (post_residual as f64).sqrt() * 1.2;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins with less residual (best-fit behavior).
        score += bin_residual as f64 * 0.15;
    }

    // Global pressure: when many bins are open relative to progress, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high or late in the stream.
        score += 12.0 + pressure * 45.0 + progress * 10.0;
        // But if the item is large and mean residual is low, a new bin may be needed.
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins when mean residual is high (consolidation).
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
        // Slight preference for filling bins with high residual when many bins open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Early stream: be more willing to open bins to build diversity of residuals.
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * (1.0 + 3.0 * p2 + 5.0 * p3) * 20.0;

    // Penalize large dead space quadratically, stronger late in stream
    score += norm_pr * norm_pr * (10.0 + 60.0 * p2);

    // Reward tight fits (small post_residual) with cubic term
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0;

    // Coupling with next item lookahead: favor residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening new bin when few alternatives
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Alignment with mean residual: prefer bins near mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: penalize slightly unless item is large or stream is early
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets treat dead space in classes.
    let r = post_residual % 10;
    // Dead space in class 1..9 is "usable-ish"; class 0 is a perfect closure.
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if r == 0 {
        score -= 8.0; // round residual likely reusable by future items
    } else if r <= 3 {
        score += 10.0; // small dead space is nearly useless
    } else if r >= 7 {
        score -= 3.0; // large-ish leftover still flexible
    }

    // Harmonic pairing: does post_residual exactly fit the lookahead item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // chains perfectly
        } else if post_residual >= next_item_size {
            score -= 4.0; // lookahead fits, mild reward
        } else {
            score += 6.0; // lookahead cannot use this bin's leftover
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to it.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Opening fresh bins for small items wastes capacity; penalize.
        score += 30.0 * (1.0 - frac);
        // But if open bins have tiny residuals (harmonic mismatch), fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Integer-division threshold: bins whose residual is in a "half-capacity" band
    // are attractive targets (half-full bins balance future large items).
    let half = bin_capacity / 2;
    if bin_residual <= half + 10 && bin_residual >= half - 10 {
        score -= 5.0;
    }

    // Early stream: be conservative, prefer tight fits; late stream: close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item * 10.0 + 9.0 {
        // unusable tiny gap: strong penalty
        score += 200.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 300.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward bins that remain useful for the next item
        score -= 25.0;
    }

    // Prefer tighter fits overall: relative fill ratio bonus.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill * fill;

    // Open-bin pressure: discourage scattering across many open bins,
    // but allow opening a new bin when existing fits are poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 8.0 + 12.0 * progress;
    score += pressure * (open_bins_count as f64).ln();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: neutral-ish baseline; only win if open fits are bad.
    if bin_residual == bin_capacity {
        score += 90.0 + 0.1 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose post_residual is small.
    let cap = bin_capacity as f64;
    let frag = post_residual as f64 / cap;
    score += 40.0 * frag * frag;

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits but wastes (post_residual - next_item_size)
            let waste = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - waste / cap);
        } else {
            // next item won't fit here; penalize dead space proportional to gap
            let gap = nxt - post_residual as f64;
            score += 10.0 * (gap / cap).min(1.0);
        }
    } else {
        // last item: minimize post_residual directly (already base)
        score += 5.0 * frag;
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    if mean_residual > 0.0 {
        score -= 8.0 * ((post_residual as f64) / mean_residual - 1.0).clamp(-1.0, 1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - frag);
    }

    // New-bin candidate handling: only allow opening a new bin when the item is
    // large and current residuals are all poor fits for it.
    if bin_residual == bin_capacity {
        // neutral base for empty bin; discourage unless open bins are fragmented
        score += 15.0;
        if mean_residual > 0.0 {
            score -= 20.0 * (mean_residual / cap).min(1.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 10.0; // pairing two large items in a fresh bin
        }
    }

    // Early stream: be slightly more willing to open bins to build diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (open_bins_count as f64).max(1.0).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: squared post-residual penalty.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this bin;
    // if the next item would NOT fit here, mildly penalize wasting small residuals.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0);
        } else {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the item is
    // large relative to the mean residual of open bins (poor fits everywhere).
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        score += 30.0;
        // Opening a fresh bin is attractive when the item is big and open bins are
        // already crowded (small mean residual), or many bins are open (fragmentation).
        let crowdedness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= item_f * 0.4 + crowdedness * 20.0 + (open_bins_count as f64).min(20.0);
    }

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (long future to exploit them); late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    } else {
        score += progress * 5.0;
    }

    // Mild preference for bins already below mean residual (balance fragmentation).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // As the stream progresses, penalize residual space more strongly (waste matters more)
    score += pr * (0.4 * p2 + 0.8 * p3);

    // Smooth reward for tight fits: post_residual near zero is doubly good, weighted by progress
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (2.0 + 4.0 * p3);

    // Penalize dead space that is too small for typical items (post_residual in awkward range)
    let awkward = (pr / 30.0 - 1.0) * (pr / 30.0 - 1.0);
    score -= 3.0 * (-awkward) * (progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 {
        // next item won't fit here; mild penalty proportional to wasted opportunity
        score += 2.0 * progress;
    }

    // New-bin candidate: prefer opening a new bin only when current bins have small residuals
    if bin_residual == bin_capacity {
        let mean_pr = mean_residual;
        if mean_pr < 25.0 {
            score -= 12.0 * (1.0 - mean_pr / 25.0);
        } else {
            score += 6.0 + 10.0 * progress;
        }
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Small smooth nudge toward balanced residuals across bins
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 are perfect fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modular class reward: post_residual divisible by common item classes
    if post_residual % 10 == 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 {
        score -= 12.0;
    }

    // Dead-space penalty: small unusable residuals (below min item size 1 -> use threshold)
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 4.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic class match: next item leaves again a clean residue
            let next_post = post_residual - next_item_size;
            score -= 25.0;
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Integer-division threshold on residual fraction
    let frac = pr / cap;
    if frac < 0.1 {
        score += 20.0; // nearly full bin: fine, but avoid tiny scraps -> slight penalty offset
        score -= 10.0;
    } else if frac < 0.35 {
        score -= 8.0; // sweet spot for medium items
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep it available but not preferred unless residuals are poor
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5 - (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 100.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

