    // Small unusable gaps are the enemy: penalize residuals that most items (>=10) cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0; // worst dead space
    } else if post_residual < 20 {
        score += 10.0; // marginal gap
    }

    // Reward extremely tight fits (snug placement).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // --- Last-chance pressure ---
    // If this is the only bin that can fit the item, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 8.0 * progress;
    }

    // Prefer bins that are already relatively full compared to the fleet mean.
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Open-bin pressure: with many open bins, discourage spreading into emptier bins.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    // --- Lookahead: keep bins usable for the next item ---
    if next_item_size > 0 && (next_item_size as f64) <= score.max(0.0) {
        // placeholder no-op to avoid unused warning logic below
    }
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 4.0; // this bin remains useful for the next item
        } else if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 2.0 * progress; // bin likely becomes dead space after this
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        score += 22.0; // default: prefer existing bins
        // Large items justify a fresh bin more readily.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If nothing else fits and item is big, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Don't open a new bin if the next item is small and could share.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

