    }

    // 2-step lookahead: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 200.0 - 0.5 * snug;
    }

    // Dead space too small for any item (sizes >= 1, but typical min 10): penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 50.0;
        }
    }

    // Slight preference for keeping few bins open.
    score += open_bins_count as f64 * 0.1;

