}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill is excellent
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(50.0) / 50.0;
        }
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // current bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: allow new bins more freely; late: discourage.
        let new_bin_penalty = 45.0 + 55.0 * progress;
        // If item is huge relative to capacity, new bin is fine.
        let big_item_discount = 30.0 * (item_size as f64 / bin_capacity as f64);
        // If open bins are mostly full (low mean residual), new bin justified.
        let crowding = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score = item_size as f64 + new_bin_penalty - big_item_discount - 25.0 * (1.0 - crowding) * 0.5;
        // If nothing else fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving fresh space for a bigger next item
        }
    } else {
        // Slight penalty for bins already fragmented relative to mean.
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Mild preference to spread across bins when many are open and empty-ish.
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
