        score += 0.05 * open_bins_count as f64;
    }

    // Mild penalty for deviating from mean residual (encourage balanced bins)
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste classes modulo common item sizes.
    // Post-residuals divisible by small sizes (<=10) are "reusable" -> reward.
    let reusable = post_residual > 0
        && (post_residual % 5 == 0 || post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0);
    if reusable {
        score -= 6.0;
    } else if post_residual > 0 {
        // Penalize awkward dead space in fine-grained classes
        score += (post_residual % 5) as f64 * 1.5;
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space thresholds: post_residual too small for the minimum item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: harmonic match between post_residual and next item size classes
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // next item fits perfectly after this one
        } else if gap % 5 == 0 || gap % 10 == 0 {
            score -= 12.0;
        } else {
            score += (gap % 5) as f64;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin afterwards: penalize proportionally
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            score -= 8.0;
        } else {
            score += 15.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Fraction-of-capacity harmonics: prefer bins whose residual is a nice fraction
    let residual_frac = (bin_residual as f64) / (bin_capacity as f64);
    if residual_frac > 0.5 {
        score -= 3.0;
    } else if residual_frac < 0.2 {
        score += 4.0;
    }

    // Mild pressure toward consolidation as stream progresses
    score += 0.05 * (step_index as f64 / (total_items as f64).max(1.0)) * (open_bins_count as f64);

    // Prefer bins tighter than the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // nearly unusable sliver
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 100.0;
    }

    // Reward filling a bin almost completely (post_residual small but usable).
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // If this bin is the only one that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit into open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when justified.
        score += 40.0;
        // Pressure grows with number of open bins (consolidation preferred).
        score += open_bins_count as f64 * 2.0;
        // If open bins are nearly full on average, a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins unnecessarily.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 30.0;
        }
    } else {
        // Reward using existing bins, scaled by how full they already are.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 15.0;
        // Mild pressure to keep the number of open bins from exploding.
        score += open_bins_count as f64 * 0.5;
        // Lookahead synergy: if next item fits exactly in the post residual,
        // this placement sets up a perfect follow-up.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item nests perfectly here: strong reward.
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot follow here: mild penalty scaled by overflow gap.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fit bonus relative to mean residual.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.1 * dev; // below-mean residual (tighter packing) favored
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current bin would leave large waste
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let waste_if_existing = mean_residual - item_size as f64;
        score += 60.0
            - 0.3 * item_size as f64
            - if waste_if_existing > 20.0 { 45.0 } else { 0.0 }
            + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Late in stream: prefer closing bins tightly (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (min size 1) can be excluded from,
    // but especially penalize residuals in the awkward mid-range.
    if post_residual >= 1 && post_residual <= 9 {
        score += 20.0; // tiny sliver, nearly unusable
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mild reward
            score -= (post_residual - next_item_size).min(30) as f64 * 0.5;
        } else {
            // next item won't fit here afterwards: slight penalty
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual are already tight;
    // filling them further is good. Bins far above mean are wasteful to top up.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in the stream, prefer opening new bins to keep flexibility
    // (mild); late in the stream, pack into existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: make it attractive only when the item fits poorly everywhere.
    // An empty bin has post_residual = capacity - item_size, which the tightness and
    // lookahead terms already score; add a mild opening cost so we prefer good fits
    // into existing bins but don't over-penalize when item is large.
    if bin_residual == bin_capacity {
        score += 5.0 + (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: squared normalized residual weighted by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic decay term: strongly punish near-empty post residuals early, less late
    score -= 25.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Interaction of item size with residual: prefer tight fits, smooth polynomial
    score -= 30.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: reward if next item can use the post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_kernel = (norm_pr - nx).max(0.0);
        score -= 20.0 * fit_kernel * (1.0 - fit_kernel) * 4.0 * nx * (1.0 - nx);
    }

    // Last-chance bonus: smooth function of fitting bins count
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean residual deviation penalty (quadratic)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev;

    // Open bins pressure: mildly discourage spreading when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // New-bin candidate: penalize unless post residual would be very useful
    if bin_residual == bin_capacity {
        score += 12.0 - 24.0 * norm_item * (1.0 - norm_item * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 10-unit classes.
    let post_class = (post_residual / 10) as f64;
    // Exact-fit / perfect-class bonus: post residual in the "dead zone" (1..10) is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward residuals that are reusable by common size classes (multiples of 10/20).
    if post_residual % 10 == 0 && post_residual >= 20 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual >= 40 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.3 * slack;
        // Harmonic match: next item leaves a class-aligned residual too
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0; // next item can't use this bin's leftover
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity and few bins fit it, soften.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with large residual when mean residual is high (consolidation).
    score -= 0.15 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, tighten packing: penalize large leftovers more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are toxic.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it creates dead space, handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a better
    // future fit. A fresh bin is attractive when the item barely fits any open bin
    // or when the post-fit residual would be unusable anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Pressure grows with number of open bins (avoid bin sprawl).
        score += 2.0 * open_bins_count as f64;
        // But if placing in an open bin creates dead space, the new bin is better.
        let open_bin_would_dead = post_residual > 0 && post_residual < dead_threshold
            && bin_residual >= item_size; // this is the new-bin call, post_residual == capacity - item
        if open_bin_would_dead {
            score -= 70.0;
        }
        // If the next item could combine with this item's leftover, opening fresh is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight packing) over
    // wasting a large residual bin on a small item.
    let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 15.0 * waste_ratio;

    // Mild pressure to keep open_bins_count low: favor filling existing bins
    // proportionally to how many bins are open.
    score += 0.5 * open_bins_count as f64 * (1.0 - waste_ratio);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < dead_threshold {
        // Placing here would leave the next item unable to use the leftover well.
        score += 10.0;
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (use up emptier bins first),
    // keeping the distribution of residuals tight.
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Core 2-step lookahead: perfect chain match (post_residual == next_item_size) ---
    if next_item_size > 0 && post_residual == next_item_size {
        // This bin becomes exactly full after the next item: extremely desirable.
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits here afterwards; reward closeness of the chain.
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 / (1.0 + slack * 0.25)).min(18.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this residual: penalize proportionally
        // to how much dead space would be stranded relative to the lookahead.
        let dead = next_item_size as f64 - post_residual as f64;
        score += dead * 0.6;
    }

    // --- Tight fit reward: small post_residual relative to item size ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // --- Penalize creating tiny unusable residuals (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins first) ---
    score += (mean_residual - bin_residual as f64) * 0.3;

    // --- Last-chance bin: only one open bin can fit this item ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, we can afford to be picky: prefer best fit more strongly.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when it enables a perfect lookahead chain
        // or when existing bins are badly fragmented.
        let chain_bonus = if next_item_size > 0 && post_residual == next_item_size { 70.0 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64) * 40.0;
        score += 45.0 - chain_bonus - fragmentation;
    }

    // --- Slight preference for consolidating into fewer bins early in the stream ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post-placement residual (tight fit).
    let mut score = post_residual as f64;

    // Fractional waste: penalize relative waste of the bin's usable space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Lookahead: reward bins whose post-residual can still host the next item,
    // penalize bins left with dead space that nothing (known) can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space relative to the smallest plausible item.
            let dead = (post_residual as f64).min(next_item_size as f64 - 1.0);
            score += 0.6 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer using bins whose residual is close to the item (best-fit refinement),
    // and slightly prefer more-filled bins via mean-residual contrast.
    if bin_residual < bin_capacity {
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * tightness;
        if (mean_residual - bin_residual as f64).abs() < 1e-9 {
            score -= 3.0; // tie-break toward the average-residual bin
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would be badly fragmented. Estimate fragmentation of the best open option
    // via post_residual vs next item; if the empty bin keeps large usable space
    // while open bins leave unusable slivers, discount the empty bin.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let usable_after = post_residual as f64 / bin_capacity as f64;
        // Early stream: opening bins is cheap-ish; late stream: consolidate.
        let new_bin_penalty = 25.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
        let mut empty_score = post_residual as f64 + new_bin_penalty;
        if next_item_size > 0 && post_residual >= next_item_size {
            empty_score -= 10.0 * usable_after;
        }
        // If the only fitting open bin exists, opening a new bin is wasteful.
        if fitting_bins_count >= 1 {
            empty_score += 35.0;
        }
        return empty_score;
    }

    // Dynamic time horizon: as the stream nears its end, squeeze harder
    // into existing bins (fragmentation matters less than bin count).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - waste_ratio);

    // Mild penalty for accumulating many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr) + 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual), stronger late in the stream
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.8 * progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for proliferation of open bins late in stream
    score += (open_bins_count as f64) * 0.5 * progress;

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate residual mass)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-to-slightly-high baseline so it is chosen
    // only when open bins would create bad fits
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (10..80 range) are reusable.
    let post = post_residual;
    let harmonic_bonus: f64 = if post == 0 {
        -60.0 // perfect fit is ideal
    } else if post % 50 == 0 {
        -25.0
    } else if post % 25 == 0 {
        -12.0
    } else if post % 10 == 0 {
        -8.0
    } else if post % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residual class
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post {
            // next item fits but leaves another residual; penalize by leftover awkwardness
            let next_post = post - next_item_size;
            score += (next_post as f64) * 0.4;
            if next_post % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot use this residual: penalize large dead space
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (post_residual.min(30) as f64) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin when stream is early
    // or many bins already open with usable mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) + (open_bins_count as f64) * 1.5;
        // but if mean residual across open bins is tiny (all nearly full),
        // opening a new bin is fine
        score -= (mean_residual.min(50.0)) * 0.6;
    }

    // Mild preference for tighter bins overall (waste minimization)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Dead-space penalty scaled by how much of the bin remains stranded
    if post > 0 && post < 10 {
        score += 15.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the smallest plausible item (<=3) are dead space.
    if post_residual > 0 && post_residual < 3 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // gap too small for next item: likely dead space
    }

    // Open-bin pressure: penalize adding to bins when many bins are open,
    // encouraging consolidation; but reward tight fits which reduce spread.
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // reserving a fresh bin for pairing can be good
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins get filled first, keeping large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late-stream consolidation: as the stream progresses, favor tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: small post_residual is good, but very
    // small non-zero leftovers are the worst (unusable slivers).
    if post_residual > 0 {
        score += 12.0 / (post_residual as f64).powf(0.35);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual
    // (chained perfect fit), penalize when next item cannot use the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            score += 0.3 * next_leftover as f64;
        } else {
            // Next item cannot fit into this bin's leftover: leftover is dead
            // space for at least one more step.
            score += 8.0;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below mean concentrates waste poorly; above mean is fine.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when the item
    // is large (a fresh bin gives it room) or late in the stream.
    if bin_residual == bin_capacity {
        score += 5.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the known next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also absorb the next item.
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(4.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins are open, favor consolidating into fuller bins.
    let pressure = (open_bins_count as f64 / 20.0).min(1.5);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Time horizon: early in the stream, prefer compacting (low post_residual);
    // late in the stream, be more tolerant of spreading to reduce wasted capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 6.0 * tightness;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Coupling with global mean residual: if this bin's residual is far below the
    // mean, it is "fuller" than average -> reward placing here.
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.15 * residual_gap;

    // Penalize leaving residuals in the awkward zone (e.g., 1..=9) that few items fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 18.0;
        // But if the item barely fits anywhere or fits nowhere well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Compare: if the lone fitting bin would leave a worse residual, allow new bin.
            let lone_fit_quality = (bin_residual - item_size) as f64;
            if lone_fit_quality > post_residual as f64 + 10.0 {
                score -= 30.0;
            }
        }
        // Late in stream with large mean residual across bins, prefer packing into
        // existing bins rather than proliferating bins.
        if progress > 0.7 && mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = prn;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, larger residuals are acceptable; late, punish them quadratically.
    let progress_weight = 0.6 * progress + 1.8 * progress * progress;
    score += progress_weight * prn * prn;

    // Smooth cubic residual term modulated by mean residual state:
    // penalize leaving residual far from the mean residual (fragmentation signal)
    let dev = (mean_residual - pr) / cap;
    score += 0.35 * dev * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, reward strongly (smoothly scaled by fit tightness)
    if fitting_bins_count <= 1 {
        score -= 0.9 * (1.0 - prn);
    }

    // Lookahead coupling: reward residual that still accommodates next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr >= n) as i32 as f64;
        let slack = (pr - n).max(0.0) / cap;
        score += fits_next * (0.15 * slack * slack - 0.25 * (1.0 - slack));
    }

    // Mild penalty for proliferating open bins, smoothly scaled by residual quality
    score += 0.02 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by modulo arithmetic.
    // Residuals in small classes (<=10) are "dead space"; residuals divisible
    // by large strides are more reusable.
    let dead = if post_residual == 0 { 0.0 } else if post_residual <= 10 { 60.0 } else { 0.0 };
    score += dead;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Harmonic class: post_residual divisible by 25 (quarter-capacity) leaves
    // room for typical item classes.
    if post_residual > 0 && post_residual % 25 == 0 {
        score -= 20.0;
    }
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 10.0;
    }

    // Penalize residuals in awkward modulo classes (prime-ish remainders).
    let awkward = post_residual % 7 + post_residual % 13;
    score += awkward as f64 * 1.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.3;
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't use this residual; penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline so it
    // only wins when all open bins are bad.
    if bin_residual == bin_capacity {
        score = 100.0 + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins tighter than the mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (1..=10) are wasted forever. Penalize small-but-nonzero post_residual hard.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: heavier than a full empty gap would justify.
            score += (10.0 - post_residual as f64) * 8.0;
        } else {
            // Usable residual: mild reward scaled by how much stays usable.
            score -= (post_residual as f64).ln() * 2.0;
        }
    } else {
        // Perfect fill is the ideal outcome.
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: with many bins open, prefer reusing existing space
    // over opening more; with few bins, allow spreading.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, avoid wasting it
    // unless the fit is excellent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has perfect flexibility.
    // Only prefer it when no open bin offers a good fit (poor post_residual
    // or the item barely fits anywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Escalate cost as stream progresses (sunk investment in open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // Cheap to open when open bins are already cluttered with dead space.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight bonus for matching residual to the lookahead item,
        // so the next item can also land here.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
        }
        // Penalize bins whose residual deviates strongly from the mean
        // (keeps residual distribution balanced and reusable).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 45.0 / (1.0 + diff);
        // Extra bonus for an exact 2-step match.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize post_residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Penalize large post_residual relative to mean residual (wasteful bin).
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening a new bin is attractive if the item would leave a tiny,
        // hard-to-fill sliver in any existing bin.
        if post_residual > 0 && post_residual < 10 {
            score -= 22.0;
        }
    }

    // Mild penalty for very small post_residual (unusable dead space),
    // unless it exactly matches the next item (already rewarded above).
    if next_item_size == 0 || post_residual != next_item_size {
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio of post-residual relative to capacity.
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible future item can use:
    // items are >= 1, but typical items are mid-sized; penalize residuals
    // that are small but nonzero (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled
            // by how much of the remainder is wasted relative to next item.
            score += 6.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fullness * (5.0 + 10.0 * progress);

    // Compare against mean residual: bins far below mean residual are
    // "emptier" — mildly deprioritize them to keep a spread of usable bins.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: opening a fresh bin is attractive early
    // or when few bins are open; penalize it when open bins are abundant
    // and this item fits reasonably well elsewhere.
    if bin_residual == bin_capacity {
        let consolidation_pressure = (open_bins_count as f64) * (0.5 + progress);
        let fit_quality_elsewhere = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 8.0 + consolidation_pressure * fit_quality_elsewhere;
        // But if next item is large and current item is large, a fresh bin
        // can be a good long-term investment.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 12.0;
        }
    }

    // Small global regularization toward lower total residual variance.
    score += 0.02 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress)) + 1.5 * progress * norm_pr * cap;

    // Smooth coupling: small post-residuals are better late in the stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth cubic term).
    let gap = pr - mean_residual;
    score += 0.15 * gap * gap * gap / cap;

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - nxt).abs() / cap);
        score -= fit_next * 8.0 * closeness * (1.0 + progress);
        score += (1.0 - fit_next) * 6.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it (smooth exponential bonus).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Crowding effect: many open bins -> prefer tighter fits.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += crowd * norm_pr * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residuals are dead space.
    // Class 0: residual in [0,10)  -> nearly dead, strongly penalize
    // Class 1: residual in [10,25) -> usable only for tiny items
    // Class 2: residual in [25,50) -> medium utility
    // Class 3: residual >= 50      -> high utility
    let class = if post_residual < 10 { 0 }
        else if post_residual < 25 { 1 }
        else if post_residual < 50 { 2 }
        else { 3 };
    score -= class as f64 * 12.0;

    // Perfect fit bonus: exact fill (post_residual == 0) is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: residual that is a multiple of a "harmonic" quantum
    // (e.g. divisible by 10) pairs well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: can the next item fit exactly in the
    // post residual? Reward chains of consecutive fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward if next item fills the bin completely after this one.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional to waste.
            score += (next_item_size.min(post_residual) as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid wasting it
    // on a bad fit (large post residual relative to capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when residual
    // classes of existing bins are poor. Penalize opening a new bin mildly,
    // scaled by stream progression and number of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 18.0;
        }
    }

    // Mean residual coupling: when the average residual across open bins is
    // large, prefer consolidating into existing bins (penalize new bins implicitly,
    // reward bins below the mean residual since they are tighter fits).
    if bin_residual != bin_capacity {
        let r = bin_residual as f64;
        if r < mean_residual {
            score -= 4.0;
        } else {
            score += (r - mean_residual) * 0.1;
        }
    }

    // Harmonic fraction of capacity used: reward high fill fraction
    // using integer division thresholds.
    let used = bin_capacity.saturating_sub(post_residual);
    let fill_class = used / 25; // 0..4
    score -= fill_class as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (nonlinear).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize moderately for gaps that only fit very small items.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (low post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item does NOT fit post_residual, mild penalty (dead space likely).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Slight preference for bins below mean residual (fill emptier bins less).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: give it a moderate default score so it only wins
    // when open bins have genuinely bad fits (high post_residual / penalties).
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Early stream: be more willing to open bins (less pressure later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // reward heavily (chain of perfect fills).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves residue: mild reward proportional to fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 2.0;
        } else {
            // Next item cannot use the residue: penalize dead space, worse for tiny leftovers.
            let dead = post_residual as f64;
            score += dead * 1.5 + 50.0;
        }
    }

    // Small post residuals are hard to fill later: penalize residue below the
    // minimum plausible item size unless it's exactly consumable.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 150.0 + (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Compare against mean residual: bins with residual below mean are more
    // "scarce" — filling them is valuable; bins above mean are roomy.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.8;

    // Early in the stream, keep bins roomy (avoid fragmenting early);
    // late in the stream, be aggressive about packing tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.5;

    // If many bins are open, encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 20.0 * (open_bins_count.min(20) as f64 - 3.0) * 0.1;
    }

    // New empty bin candidate: make it unattractive unless it's the only option
    // or the item is huge and would leave awkward residue elsewhere.
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size >= 60 || (next_item_size > 0 && next_item_size >= 60) {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual more when it is small but nonzero
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual > 0 {
        score += (1.0 - fit_ratio) * 20.0;
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Penalize very small dead space that is hard to reuse (below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - next_tight / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize dead space
            score += 8.0;
        }
    } else {
        // Last item: just minimize residual waste
        score += 0.0;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual > mean_residual {
        score -= 2.0 * (bin_residual as f64 - mean_residual) * progress;
    }

    // New empty bin candidate: make it moderately attractive only when it beats
    // poor fits — penalize it so existing bins are preferred unless they score badly
    if bin_residual == bin_capacity {
        score += 12.0 + 5.0 * (1.0 - progress);
        // If the item is large relative to mean residual, new bin is less wasteful
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild preference for bins with low residual overall (fill nearly-full bins)
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space below half capacity is quadratically bad.
    let norm_post = post / cap;
    score += 18.0 * (1.0 - norm_post).powi(2) * norm_post.max(0.0);

    // Smooth progress coupling: early on, tolerate slack; late, demand tight fits.
    score += 10.0 * progress * (1.0 - norm_post);

    // Reward tight fits (small post_residual) with a non-linear discount.
    score -= 12.0 * (-norm_post * 6.0).exp();

    // Lookahead: penalize if next item cannot use this bin's post-residual.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0 * (1.0 - (post / (next_item_size as f64 + 1.0)));
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - (next_item_size as f64 / (post + 1.0)));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it competitive only when few bins are open or fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 4.0 * (open_bins_count as f64).ln();
        }
    }

    // Penalize bins far from the mean residual (outliers create fragmentation).
    score += 2.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of small sizes) are more attractive.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -12.0 // leftover reusable by typical small items
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 20 {
        -2.0
    } else {
        8.0 // dead space below 20 is nearly unusable
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover bucketed by quarter-capacity.
    let quarter = (pr * 4) as f64 / cap;
    score += 10.0 * (1.0 - quarter); // prefer bins that become "emptier" fractions

    // Lookahead coupling: reward leftover that can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 5.0 + (pr - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // or the stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (post_residual as f64) / cap;
        if waste > 0.5 || (progress < 0.2 && open_bins_count > 4) {
            score -= 18.0;
        } else {
            score += 10.0 + 5.0 * progress;
        }
    }

    // Mild preference for tighter bins when mean residual is high (fragmentation risk).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can ever use
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Very small gaps slightly above the minimum item size are also hard to fill.
    if post_residual >= 10 && post_residual <= 15 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // But if this bin would leave a bad gap elsewhere, opening a new bin
        // becomes attractive: relax the penalty when the fit is poor.
        if post_residual < 10 || post_residual > 40 {
            score -= 20.0;
        }
        // If the next item would fit perfectly in the fresh bin, favor opening it.
        if next_item_size > 0 && next_item_size >= bin_capacity - post_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap -> the gap is likely dead space.
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Slight preference for filling bins with larger residuals first when
    // residuals are far below the mean (keeps mean residual balanced).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    // Mild stream-progress scaling: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: small post_residual is good.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect chain: post_residual exactly fits the next item -> big reward.
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        } else if post_residual as f64 >= next {
            // Next item fits after this placement; reward proportional to how snugly.
            let slack = post_residual as f64 - next;
            if slack <= 10.0 {
                score -= 35.0 - 2.0 * slack;
            } else {
                score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item will NOT fit here: residual becomes dead space unless tiny.
            if post_residual < 10 {
                score -= 5.0; // tiny dead space is nearly perfect packing
            } else {
                score += 10.0 + 0.5 * (post_residual as f64 - next).abs();
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive only
    // when the fit into open bins would create large dead space.
    if bin_residual == bin_capacity {
        score = 0.7 * bin_capacity as f64
            - 0.5 * item_size as f64
            + if next_item_size > 0 && next_item_size >= item_size {
                5.0
            } else {
                0.0
            };
    }

    // Mild stream-progression pressure: later in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively for larger items.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Penalize leaving dead space that no typical item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // dead space relative to the known next item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item
    // fits poorly everywhere else or open-bin space is fragmented.
    if bin_residual == bin_capacity {
        // Base mild penalty so a decent existing fit wins.
        score += 6.0;
        // But if many bins are open with scattered residuals, a fresh bin is fine.
        if open_bins_count > 4 && (mean_residual < item_size as f64) {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If next item is large, keeping a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // scaled by how many alternatives exist.
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.05 * (1.0 + fitting_bins_count as f64 * 0.1);
        // Slight preference to fill bins with larger residuals when few bins fit.
        if fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Global fragmentation: if mean residual is high, encourage consolidation
    // into existing bins.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: prefer low post residual, with progress-dependent curvature
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm * (0.5 + progress));

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 12.0 * tightness * tightness * (0.4 + progress);

    // Penalize post residual close to next item's fit (wasted near-match)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score += 6.0 * gap * gap;
        } else {
            let shortfall = (nxt - post) / cap;
            score -= 3.0 * shortfall * shortfall;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Dead-space penalty for tiny unusable residuals, smoothed
    let dead = if post_norm > 0.0 && post_norm < 0.1 { (0.1 - post_norm) / 0.1 } else { 0.0 };
    score += 20.0 * dead * dead;

    // Mild pressure toward consolidating bins when many are open
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    // Prefer bins with residual above mean (keep balanced bins free)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev - 2.0 * dev;

    // New-bin candidate: penalize opening new bins unless item is large relative to residual
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 25.0 * (1.0 - fill * fill) * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class (0..=10)
    score += match class {
        0 => -60.0,                    // near-perfect fit
        1 => -35.0,                    // excellent
        2 => -15.0,                    // good (fits small items 10..20)
        3 => 0.0,
        4 => 8.0,
        5 => 18.0,                     // half-full: awkward class
        6 => 14.0,
        7 => 6.0,
        8 => -5.0,                     // large item may still land
        9 => -12.0,
        _ => -25.0,                    // empty-ish bin (new bin candidate)
    };

    // Fine modulo structure within classes: reward residuals divisible into
    // common item granularities (multiples of 10 are highly reusable).
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or with small slack -> strong reward
            let slack = pr - next_item_size;
            score -= 25.0;
            if slack == 0 { score -= 20.0; }
            else if slack <= 10 { score -= 8.0; }
        } else if next_item_size > pr && next_item_size <= bin_residual {
            // this bin wastes the lookahead opportunity vs keeping residual
            score += 6.0;
        }
        // harmonic match: next item size class equals post residual class
        if next_item_size / 10 == pr / 10 && pr > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / 10.0;
        score = 100.0 - 20.0 * congestion - 10.0 * progress;
        // if the mean residual can't hold typical future items, new bin is fine
        if mean_residual < 15.0 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins tighter than the mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let smallest_item = 1u32;
        if post_residual < smallest_item {
            score += 1000.0;
        }
        // Penalize gaps too small for the lookahead item (unusable for next step).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Non-linear penalty on very small dead space (hardest to reuse).
        let pr = post_residual as f64;
        if pr <= 10.0 {
            score += (10.0 - pr) * 3.0;
        }
    } else {
        // Perfect fit is highly rewarded.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor filling existing.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if mean residual is high, prefer bins that reduce it most.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current placements are very poor.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -1.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Progression: later in stream, be more conservative (prefer exact fills).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect chain: place current here, next fills bin exactly
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportionally to how tight the chain is
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * tightness;
        } else {
            // next item cannot follow here: penalize dead space creation
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter (smaller residual) than average
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Penalize leaving large unusable gaps (dead space below typical small item size)
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0; // tiny leftover is nearly full utilization
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tightness = mean_residual / bin_capacity as f64;
        score = 60.0 + 80.0 * progress + 40.0 * avg_tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin is good if the next item also chains well after this one
            let chain = (bin_capacity - item_size) as f64;
            if next_item_size as f64 <= chain {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize bins whose residual after placement is small but nonzero.
    if post_residual > 0 {
        let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 40.0 * tight;
    } else {
        score -= 25.0; // perfect fill is highly desirable
    }

    // Reward using bins that would otherwise leave awkward gaps relative to mean residual.
    let res_gap = bin_residual as f64 - mean_residual;
    score -= 0.3 * res_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to encourage consolidation among many candidates
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Lookahead coupling: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: maximize fill
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when current
    // open bins are crowded (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let item_fits_somewhere = fitting_bins_count > 0;
        let mut new_bin_cost = 30.0 + 10.0 * crowdedness + 20.0 * (1.0 - progress);
        if item_fits_somewhere {
            new_bin_cost += 25.0;
        }
        if post_residual < 20 {
            new_bin_cost -= 10.0; // big item in fresh bin is fine
        }
        score += new_bin_cost;
    }

    // Time horizon: late in the stream, discourage leaving loose residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 + progress);
    score += 20.0 * poly;

    // Penalize small post_residual more strongly late in the stream (dead space)
    score += (1.0 - progress) * (norm_pr * (1.0 - norm_pr)) * 10.0;

    // Reward near-perfect fits via smooth term
    let fit_quality = 1.0 - (norm_pr - 0.0) * (norm_pr - 0.0);
    score -= fit_quality * 5.0 * progress;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / cap.max(1.0));
    }

    // Discourage spreading across many bins when mean residual is high
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - norm_pr);

    // New-bin candidate handling: prefer opening a fresh bin only when fit is bad
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 12.0 * (1.0 - progress) + 25.0 * (fitting_bins_count as f64 / (fitting_bins_count as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by small item sizes (10, 20, 25) are reusable dead space.
    let pr = post_residual;
    if pr > 0 {
        let div10 = (pr % 10 == 0) as i32;
        let div20 = (pr % 20 == 0) as i32;
        let div25 = (pr % 25 == 0) as i32;
        let small = (pr <= 10) as i32;
        // Reward residuals in friendly harmonic classes
        score -= 6.0 * div10 as f64;
        score -= 4.0 * div20 as f64;
        score -= 4.0 * div25 as f64;
        // Tiny leftovers (<10) are dead space: penalize heavily
        score += 12.0 * small as f64;
        // Mid-range awkward residuals (11..19) also dead-ish
        if pr > 10 && pr < 20 {
            score += 6.0;
        }
        // Integer-division threshold: residual that can hold the next item
        if next_item_size > 0 {
            if pr >= next_item_size {
                // how many times next item fits: finer division = better packing
                let fits = pr / next_item_size.max(1);
                score -= 3.0 + fits as f64;
                // exact fit for next item is excellent
                if pr % next_item_size.max(1) == 0 && fits >= 1 {
                    score -= 5.0;
                }
            } else {
                // next item cannot fit here: residual may become waste
                score += 4.0;
            }
        }
    } else {
        // Perfect closure: zero residual is ideal
        score -= 20.0;
    }

    // Capacity-fraction coupling: prefer bins filled to high fraction of capacity
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // When many bins are open, encourage consolidating into tight fits
    if open_bins_count > 4 {
        score -= 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Progress-aware: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill_frac;

    // Penalize opening new bins when mean residual across open bins is large
    score += 0.05 * mean_residual;

    // New-bin candidate: only attractive if current residual is unusable
    if bin_residual == bin_capacity {
        if pr >= 10 && (pr % 10 == 0 || pr >= 30) {
            score += 15.0; // keep using open bins when residual is reusable
        } else {
            score -= 2.0; // fresh bin may beat a dead-space bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    }
    // If next item nearly fits but leaves a dead gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual - next_item_size as i64 as u32 > 0 {
        // next item won't fit here; small residual becomes dead space
        if post_residual < 15 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: only attractive when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit = post_residual as f64 > 0.0 && (item_size as f64 / bin_residual as f64) < 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 25.0 + 5.0 * pressure;
        } else {
            score += 35.0 + 3.0 * open_bins_count as f64;
        }
    }

    // Late in the stream: consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_ratio);

    // Prefer bins tighter than the mean residual (fill the emptiest-relative need correctly).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual too small to ever hold the smallest item (1..=100 range,
    // but treat anything below a practical threshold as waste proportional to its size).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit bonus, stronger the tighter the chain fit.
            score -= (next_item_size as f64) * 1.5;
            // Extra reward when the chain consumes nearly everything.
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Next item won't fit here after placement: penalize, scaled by how much
            // post_residual is wasted relative to the next item.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than the mean,
    // penalize bins that are outliers of slack.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize the brand-new-bin candidate so it is only chosen when it truly wins
    // (e.g., no open bin can chain the next item well).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
    }

    // Slight early-stream preference for opening bins (builds structure), late-stream
    // preference for filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    } else {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin consumed by placing the item
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract proportional to how full the bin becomes
    score -= 2.5 * fill * fill * (bin_capacity as f64);

    // Penalize unusable dead space: small post_residual that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins can fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // Cost of a new bin is ~capacity; scale by how poor the best existing fit likely is
        score += (bin_capacity as f64) * (0.5 + 0.5 * (1.0 - progress));
        // If an existing bin would end up with tiny residual, opening new bin is even worse
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Reward opening a new bin early when open bins are nearly full / fragmented
    if bin_residual == bin_capacity {
        score -= 0.2 * mean_residual.min(50.0) * progress;
    }

    // Mild penalty for spreading across too many open bins (fragmentation control)
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins with residual close to mean (balanced packing)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual waste, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Perfect fit reward (smooth, no piecewise).
    score -= 20.0 * (-pr as f64 / 5.0).exp();

    // Penalize leaving a residual that no typical item can use (dead space),
    // expressed smoothly via distance to the small-item range.
    let dead = (pr as f64 - 10.0).max(0.0) / cap;
    score += 8.0 * dead * dead * cap;

    // Lookahead coupling: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let gap = (pr as f64 - next_item_size as f64).abs();
        score -= 10.0 * fits_next * (1.0 - gap / cap);
        score += 6.0 * (1.0 - fits_next) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation early).
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral baseline with slight offset so only genuinely
    // poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // Deviation from mean residual: prefer bins below mean (tighter packing).
    score += 0.5 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space below half-capacity is hard to reuse.
    let half = bin_capacity / 2;
    if post_residual > 0 && post_residual < 10 {
        // Tiny sliver: nearly dead space.
        score += 45.0;
    } else if post_residual < half {
        // Penalize dead space quadratically within lower half.
        score += (half - post_residual) as f64 * 0.6;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair well
    // with items in the 10..80 range.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 - (gap as f64).min(40.0);
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin anyway; residual is free real estate.
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) > 0.6 * bin_capacity as f64;
        let poor_options = fitting_bins_count <= 1;
        if large_item || poor_options {
            score -= 25.0 + 30.0 * progress;
        } else {
            // Prefer existing bins early on; new bins get default (post_residual = capacity) score.
            score += 20.0;
        }
    }

    // Mild preference toward tighter bins overall (balance residual distribution).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Prefer filling bins when many are open (reduce bin count pressure).
    if open_bins_count > 4 && bin_residual >= item_size {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Integer-division threshold: residual in [item class boundaries].
    let q = post_residual / 20;
    score -= q as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

