    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here -> residual likely dead space.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins (penalize the new-bin candidate implicitly via residual,
    // and reward using existing bins when bin count is high).
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score -= 2.0 + pressure;
    } else {
        // New empty bin: penalize more when many bins already open.
        score += (open_bins_count as f64) * 1.5;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is relatively full -> prefer it (fills tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Slight progression bias: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-match with lookahead (within a small window).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Penalize post-residuals that are small dead space (unusable chunks).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, prefer filling existing bins less aggressively
    // (keep flexibility); later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (fitting_bins_count as f64);
        // If lookahead fits perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be reused:
    // small post_residual that is still larger than typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 25 {
        score += 5.0; // awkward gap zone
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * lookahead_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item: mild penalty for stranding space.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist with large mean residual,
    // unless this call IS the new-bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only if existing residuals are fragmented/small
        // or many bins are open (spreading load late in stream).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0;
        score -= 15.0 * (mean_residual / bin_capacity as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // New bin looks better if item is large relative to typical residual.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward bins whose residual is close to item (good match).
        let waste = (bin_residual - item_size) as f64;
        score += 0.1 * waste;
        // Slight preference for bins with residual below mean (consolidating tight bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time horizon: late in the stream, favor filling bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly
    let coupling = (pr_norm * (1.0 - pr_norm)).powi(2);
    score += 30.0 * coupling * (0.5 - progress).abs() * 2.0;

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Penalize bins deviating from mean residual (keep residuals balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 0.05 * (next_item_size as f64 - pr).abs();
    }

    // Slight preference for fewer open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common small item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are divisible into nice chunks (harmonic classes).
        let class_bonus = if pr % 10 == 0 {
            12.0
        } else if pr % 5 == 0 {
            6.0
        } else if pr % 20 == 0 {
            10.0
        } else if pr % 25 == 0 {
            8.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Penalize dead space: residuals below the smallest item size are wasted.
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fill is ideal.
        score -= 30.0;
    }

    // Integer-division thresholds: residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 5.0; // tight bin, low flexibility
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual && next_item_size >= 10 {
            // Next item fits but leaves a residual; prefer if resulting residual is harmonic.
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 15.0;
            } else if nr < 10 {
                score += 10.0; // creates dead space for the next placement
            }
        }
        // If next item is large and this bin's residual is a poor class, prefer new bin.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual - (mean_residual as u32) as f64; // fractional part proxy
        let avg_open = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        // Open a new bin if existing bins are mostly tight or fragmented late in the stream.
        if avg_open < 25.0 || (fragmentation > 0.5 && progress > 0.3) {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Mild preference to fill fuller bins first (tight coupling with residual fraction).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    // A post_residual that is too small for typical items (1..100) is dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - (post_residual as f64) / 20.0);
    }
    // Moderate penalty for gaps that only fit the smallest items.
    if post_residual >= 20 && post_residual < 35 {
        score += 15.0 * (35.0 - post_residual as f64) / 15.0;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 12.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and pressure is high.
        score += 25.0 + open_pressure;
        // But allow a new bin if the item would leave a bad gap in any bin.
        if post_residual < 20 && post_residual > 0 {
            score -= 35.0;
        }
    } else {
        // Existing bin: reward slightly as open pressure grows.
        score -= open_pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, be more aggressive about tight packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits snugly into the new residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit after this placement: dead-end penalty scaled by waste
    else if next_item_size > 0 {
        score += 150.0 + 0.5 * post_residual as f64;
    }

    // Reward low post-residual relative to mean residual (tight packing)
    score -= 30.0 * (1.0 - post_residual as f64 / (mean_residual + 1.0).max(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 40.0 * progress;

    // Slight penalty for leaving large unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny leftover is fine (near-perfect fill)
    } else if post_residual >= 10 && post_residual < 30 {
        score += 20.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual relative to capacity is better.
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            score += 10.0;
        }
        // Chain fit: next item exactly fills post residual.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that
    // shrinks as the stream progresses (late in stream, prefer consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * (1.0 - progress) + 15.0;
    }

    // Prefer bins whose residual is far from the mean (deviation exploitation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Slight preference for bins with larger residual when many bins are open.
    score -= bin_residual as f64 * 0.05 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Early stream: encourage keeping residuals flexible (avoid tiny leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Core: prefer tight fits, with non-linear sharpening of small residuals.
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized.
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Dead-space penalty: residuals too small for typical future items.
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += dead * dead * cap * (0.5 + progress);

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // Penalize near-misses that block the next item.
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.5 * gap * (0.5 + progress);
    }

    // Penalize opening a new bin when open bins could fit (encourage reuse).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 12.0 + 8.0 * progress - 2.0 * scarcity;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 6.0 + 5.0 * progress;
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score += 0.15 * (pr as f64 - mean_residual).abs().signum() * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residuals divisible by small classes (10/20/25/50)
    // are more reusable, so reward them.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, best outcome
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -9.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 // awkward residual, penalize
    };
    score += class_bonus;

    // Dead-space penalty: tiny residuals that nothing (min size 1, but practically
    // small items) can use later are wasted; the smaller the residual the worse
    // unless it is exactly zero.
    if pr > 0 && pr < 10 {
        score += 15.0 - pr as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next fits with slack: reward proportional to tightness
            score -= 10.0 * (1.0 - (post - nx) / cap);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 3.0 * (nx / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling already-open bins when many bins are open; discourage
    // opening new bins unless the fit is genuinely good.
    score += 0.15 * open_bins_count as f64;

    // Progress-aware tilt: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Deviation from mean residual: bins already tighter than average are
    // preferred targets (compactness pressure).
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap too small for the lookahead item => likely permanent dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 1.5;
        }
        // Very small absolute gaps (< 10) are almost certainly wasted.
        if post_residual < 10 {
            score += 30.0;
        }
        // Progressive penalty as gap shrinks relative to capacity (non-linear).
        score += (1.0 - pr / bin_capacity as f64).powf(3.0) * 20.0;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual below the running mean (compact bins).
    score += (pr - mean_residual).max(-30.0).min(30.0) * 0.3;

    // New-bin candidate: neutral baseline, only chosen when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.1 - pr * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
