        } else if post_residual > next_item_size {
            // slack left after placing next item: penalize proportionally
            score += 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here afterwards; residual becomes dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize unusable dead space (residual below minimum item size 1..small)
    if post_residual < 10 {
        score += 15.0; // tiny dead space is nearly worthless
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score += 8.0; // default slight penalty; lookahead rewards can override
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin leaves room for a big next item
        }
    }

    // Late in the stream, tighten packing (less room to recover)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual), with a soft knee.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize exact-fit waste asymmetrically: leaving a residual that can
    // still host a typical small item is fine; leaving 1..=9 is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 12.0 * (nr / 100.0);
        } else {
            // Next item won't fit here: penalize proportionally to how wasted it is.
            score += 6.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Global state: when many bins are open and mean residual is high,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 4.0 * crowding * progress;

    // New-bin candidate handling: empty bin gets a base penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
        // But if item is large and few bins fit it, opening a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (0.5 + 0.5 * progress * progress);
    let quad = 60.0 * norm_pr * norm_pr * (1.0 - progress) + 20.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual), stronger later in stream
    let tight_reward = -40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Last-chance bonus: avoid opening new bin when only this bin fits
    let last_chance = if fitting_bins_count == 1 { -25.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead: penalize if next item won't fit in post residual
    let look = if next_item_size > 0 {
        if (next_item_size as f64) <= pr { -8.0 } else { 6.0 * (next_item_size as f64 - pr) / cap }
    } else { 0.0 };

    // Mild penalty for spreading across many open bins relative to mean residual
    let spread = 5.0 * ((open_bins_count as f64).ln1p()) * (norm_pr - mean_residual / cap).abs();

    base + quad + tight_reward + last_chance + look + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals that few item sizes can fill are bad.
    // Items are 1..=100, so a residual r is fillable by sizes 1..=r.
    let r = post_residual;
    let fillable_fraction = (r as f64 / bin_capacity as f64).min(1.0);
    score += (1.0 - fillable_fraction) * 30.0;

    // Modulo-class logic on residual: residuals matching common item-size
    // harmonic classes (multiples of 10, 25, 50) are easier to close out.
    if r % 10 == 0 { score -= 8.0; }
    if r % 25 == 0 { score -= 6.0; }
    if r % 50 == 0 { score -= 6.0; }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            if (r - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // Next item cannot use this bin's remainder; slight penalty.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with residual close to the item (tight fit) beyond raw residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference for reusing bins as the stream progresses (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // Penalize opening new bins when mean residual across open bins is large.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.15;
    }

    // Integer-division threshold: residuals < 10 are nearly dead space.
    if r > 0 && r / 10 == 0 {
        score -= 12.0; // tiny leftover is fine (unusable anyway, so don't chase it)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (or the lookahead item) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(100)) {
        score += 40.0;
    }
    // Dead space that cannot fit the next item but could fit a small item:
    // moderate penalty proportional to the gap's uselessness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= 15.0 * (item_size as f64 / (item_size + post_residual) as f64);
    }

    // Perfect or near-perfect fills get a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when existing
    // bins would leave bad dead space or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing open bins with good fits.
        score += 18.0;
        // Pressure: many open bins -> discourage opening yet another one.
        score += 2.0 * open_bins_count as f64;
        // But if the current bin is the only fitting option, opening a new
        // bin competes directly; relax its penalty.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Large next item may deserve a fresh bin.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor it strongly
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins), penalize placing into unusually roomy bins.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild open-bin pressure: spreading load across many bins is costly.
    if bin_residual != bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fixed costs dominate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= (60.0 - gap.min(60.0)) * 4.0;
        } else {
            // Next item won't fit here: leftover becomes dead space,
            // penalize proportionally to how small the leftover is
            // (small leftovers are least reusable).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 2.0;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious;
    // filling them is good, so reward small post_residual more when
    // bin_residual is far below mean_residual.
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= tightness * 0.5;
    } else {
        score += (-tightness) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Opening a new bin is acceptable if the item is large and no
        // open bin leaves a good post-fit state.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 100.0;
        }
        // Fewer open bins relative to stream progress: new bins cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 1000.0;
        } else {
            score -= progress * 20.0;
        }
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tight * tight;

    // Penalize dead space that is too small to be useful later:
    // unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot use the leftover; mild penalty scaled by waste.
            score += 0.15 * post_residual as f64;
        }
    }

    // Prefer filling bins when many bins are already open (consolidation pressure).
    let open_f = open_bins_count as f64;
    score -= 2.0 * open_f * (bin_residual as f64 / cap);

    // Global balance: penalize bins whose residual deviates from mean residual
    // (prefer uniform fill levels, avoids stranding many half-empty bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    // New-bin candidate (empty bin) gets a dynamic penalty: expensive early,
    // cheaper late only if existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - 0.5 * progress);
        // Extra penalty if plenty of open bins already exist.
        score += 1.5 * open_f;
    } else {
        // Late-phase consolidation: reward using existing bins more.
        score -= 20.0 * progress;
    }

    // Mild preference for bins that are already partially filled
    // (avoid fragmenting across many bins).
    score -= 0.1 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial smoothing
    let mut score = pr.powf(1.4);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costlier)
    let late = progress * progress;
    score += late * norm_pr.powi(3) * cap;

    // Reward near-perfect fits smoothly (quadratic bump around pr=0)
    score -= (1.0 - norm_pr).powi(6) * isz;

    // Penalize residuals that can't plausibly fit future items (smooth gate)
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (n - pr).max(0.0) / cap;
        score += gap.powi(2) * cap * 0.5;
        // Reward leaving room exactly for the next item
        score -= (1.0 - ((pr - n).abs() / cap).min(1.0)).powi(4) * 5.0;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins)
    score += ((bin_residual as f64 - mean_residual) / cap).powi(2) * 8.0;

    // Smooth new-bin discouragement: opening bins late is penalized via progress
    if bin_residual == bin_capacity {
        score += cap * (1.0 + progress * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

