    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        score += pressure
            + (open_bins_count as f64) * 0.5
            + (mean_residual - 50.0).max(0.0) * 0.1;
