    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Stream progression: late in the stream, close bins aggressively (favor tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

