        score += 4.0;
    }

    // Mean residual coupling: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: neutral base, penalize opening early
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by integer division.
    // Small post_residual = tight fit = reward strongly.
    let tight_class = post_residual / 10; // 0..=10
    score -= (10 - tight_class as f64) * 6.0;

    // Dead-space class: residuals that few item sizes can use (mod 10 residues 1..9)
    let residue = post_residual % 10;
    if residue > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if residue != 0 && residue < 5 {
        score += 4.0;
    }

    // Exact fit: perfect packing
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain of exact fits
        } else if next_item_size <= post_residual {
            let next_post = post_residual as f64 - next_item_size as f64;
            // prefer chains leaving clean multiples of 10
            if next_post as u32 % 10 == 0 {
                score -= 20.0;
            }
            score -= next_post * 0.3;
        } else {
            // next item cannot follow here: penalize moderately, more if residual is odd-sized
            score += 8.0 + residue as f64;
        }
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: fresh bin has post_residual == capacity - item_size.
    // Penalize opening a new bin unless current residual is fragmented.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but allow new bin when current bins are very full (mean residual small)
        score -= mean_residual * 0.5;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 20.0; // next item won't fit here anyway, fresh space is fine
        }
    }

    // Stream progression: early on, prefer consolidation; late, accept tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Tie-break toward bins with residuals harmonically aligned with item (multiples of 10)
    if bin_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps below the minimum item size (1..~15)
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (15.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual == 0)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // If next item cannot fit post residual but would fit elsewhere, mild penalty
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Mild bias toward fuller bins (small residual relative to capacity)
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (lower score) when post_residual is small but usable.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-chain match
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward lookahead fit, decaying with leftover slack after next item
            score -= 20.0 - 0.15 * slack;
        } else {
            // next item cannot fit here: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.1 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: avoid wasting the only fitting bin on a poor fit,
    // but reward using it when the fit is tight.
    if fitting_bins_count == 1 {
        if post_residual as f64 <= mean_residual {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Penalize creating tiny unusable dead space (< smallest item, assume ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // New-bin candidate: only attractive when current fit is bad and lookahead fails.
    if bin_residual == bin_capacity {
        let lookahead_ok = next_item_size > 0 && post_residual >= next_item_size;
        if post_residual <= 20 || lookahead_ok {
            score += 40.0; // keep using open bins when fit is decent
        } else {
            score -= 2.0; // allow opening a new bin for poor fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that is too small for typical items (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * chain_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual likely unusable for the known next item -> penalize.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation into existing bins;
    // when few bins are open, allow opening new bins more freely.
    let consolidation_pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 / consolidation_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: bins far below mean residual are better
    // candidates to fill up (balance residual distribution).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (keep flexibility); late in the stream, pack tightly into what exists.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as i32 as f64;
    score -= progress * 4.0 * tightness;

    // Prefer bins whose residual is close to the item (perfect fit zone).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.03 * fit_gap;

    // Mild penalty on opening a brand-new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Base: reward tight fits (low post residual) with a smooth non-linear coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 + progress));

    // Smooth polynomial interaction: mid-size residual waste penalized more as stream progresses
    let waste_curve = norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 30.0 * waste_curve * (0.5 + progress);

    // Lookahead: reward bins whose post residual can host the next item (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        let kernel = (-4.0 * diff * diff).exp();
        score -= 12.0 * kernel * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Deviation from mean residual: prefer bins deviating smoothly from the mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Small smooth tilt favoring fuller bins (larger item fraction) as stream advances
    score -= 10.0 * fit_frac * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = bin_capacity / 4;
    let class = post_residual / q; // 0..=4 harmonic class
    // Reward residuals that fall in "usable" harmonic classes (large enough for typical items)
    match class {
        0 => score -= 12.0,               // post_residual < 25: dead space, but tiny bin already tight
        1 => score += 6.0,               // 25..50: awkward zone
        2 => score -= 4.0,               // 50..75: decent
        3 => score -= 9.0,               // 75..100: excellent
        _ => {}                           // full bin
    }

    // Exact-fit reward: post_residual divisible by common harmonic steps
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does post_residual accommodate next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // bonus if next item then leaves a class-0 or exact residual
            let nr = post_residual - next_item_size;
            if nr == 0 || nr < q {
                score -= 6.0;
            }
        } else {
            // bin becomes dead for the next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.5);
        // base cost of opening a bin
        score += 30.0 + 8.0 * pressure * (1.0 - progress);
        // but if the current bin leaves bad dead space relative to next item, new bin gains appeal
        if next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Mild tie-break: prefer tighter bins (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Slight preference to balance residuals toward mean
    score += ((post_residual as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver (items >= 10... but sizes can be >=1) => heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Penalize medium-small gaps that few item sizes can use.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: fill fraction of the consumed space.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; post_residual becomes long-lived dead space
            score += post_residual as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: fresh bin only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline: prefer reusing an open bin unless it would create bad dead space.
        score = 55.0 - fill * 10.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: opening a new bin is fine
        }
        if post_residual == bin_capacity && item_size as f64 > mean_residual.max(0.0) + 20.0 {
            score -= 10.0; // large item, open bins are mostly full anyway
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // heavily favor this bin (chains two items).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item cannot follow here; penalize relative to leftover size
            score += 0.3 * (post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless current item is large and would waste space.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 - 0.2 * waste;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // fresh bin can host both items sequentially; make it competitive
            score -= 35.0;
        }
    }

    // Late in stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space (residual too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: this is the only open bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Strong synergy: exact pair fit (item + next item fills bin).
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item is large, prefer bins with more room.
        if next_item_size > 50 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits concentrate space).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream: be picky, prefer tight fits; late: accept more to limit bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Many open bins: discourage opening new bins / spreading items.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.4;
    }

    // New-bin candidate: make it attractive only for large items with no good fit elsewhere.
    if bin_residual == bin_capacity {
        score += 6.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 5.0;
        }
        if progress > 0.7 {
            score -= 3.0; // late stream: new bins are fine
        }
    }

    // Slight preference for fuller bins (smaller residual).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized post_residual modulated by progress
    score += 20.0 * (norm_pr * norm_pr) * (0.5 + progress);

    // Penalize post_residual that is close to but not zero (dead space) — smooth bump
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score -= 15.0 * dead * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * 10.0 * progress;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Discourage opening new bins late in stream when open bins fit
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * progress;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score += 8.0 * slack * slack;
            score -= 5.0 * (1.0 - slack);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Mild coupling with mean residual and open bins count
    score += 0.05 * open_bins_count as f64;
    score += 0.02 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: dead space analysis.
    // Class 0: post_residual in [0, 10) -> unusable for any item (min size 10... but sizes can be >=1)
    let dead = if post_residual < 10 { 3 } else if post_residual < 20 { 2 } else { 0 };
    score += dead as f64 * 25.0;

    // Modulo-style classes: residuals that can't combine with common sizes.
    // If next item fits exactly into post_residual, big reward (lookahead pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover after hypothetically placing next item
            let r2 = post_residual - next_item_size;
            if r2 == 0 {
                score -= 400.0;
            } else if r2 < 5 {
                score -= 150.0;
            } else if r2 < 10 {
                score += 30.0;
            } else {
                // mod-10 harmonic class: small odd-ish remainders are less useful
                let cls = r2 % 10;
                if cls >= 5 && cls <= 9 {
                    score += 10.0;
                } else {
                    score -= 5.0;
                }
            }
        } else {
            // next item cannot fit here; if this bin is the last chance, prefer using it anyway
            if fitting_bins_count == 1 && post_residual < 10 {
                score -= 200.0;
            } else if fitting_bins_count == 1 {
                score -= 50.0;
            }
        }
    }

    // Integer-division thresholds on post_residual: half / quarter capacity classes.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == half || post_residual == quarter {
        score += 15.0; // round numbers tend to be reusable, but slight penalty vs odd values? keep mild
    }
    if post_residual > half {
        // bin still very roomy; opening new bin is wasteful here
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should rarely win unless current bin leaves bad residue.
    if bin_residual == bin_capacity {
        // penalize opening a new bin mildly; scale with stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 80.0 * progress;
        // but if no open bin can fit and item is huge, allow new bin
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 300.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strong preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Prefer bins tighter than average (best-fit flavor) via mean residual coupling.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Small coupling with open bins count: many open bins -> consolidate.
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Dead space: tiny sliver that almost nothing can use.
            score += (11 - post_residual) as f64 * 30.0;
        } else {
            // Usable gap: reward proportionally to how well next item fits.
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 25.0; // gap can host the lookahead item
            }
            // Diminishing value of large leftovers: prefer moderate usable gaps
            score -= (post_residual as f64 / bin_capacity as f64) * 5.0;
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 100.0;
    }

    // Exact-fill preference relative to item size: big items closing a bin are great.
    if item_size >= bin_residual {
        score -= 40.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: many open bins -> prefer packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: only attractive when the item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        if item_size >= 70 || (fitting_bins_count == 0) {
            score -= 60.0;
        } else {
            score += 50.0 + 20.0 * progress; // keep existing bins tight
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize proportionally to the gap
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (gap / bin_capacity as f64);
    }

    // Penalize small dead space (unusable fragments), reward large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than average (good fits), discourage wasteful use of loose bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in stream: be conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual >= 0 && (bin_residual as i64 - item_size as i64) >= 0;
        if fitting_bins_count == 0 || (next_item_size > 0 && next_item_size > bin_capacity - item_size) {
            score -= 20.0;
        } else {
            score += 30.0;
        }
        let _ = bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: penalize large post_residual, especially small dead space
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Dead-space penalty: residual too small for smallest plausible item (1..100 unknown, use item_size as guide)
    let min_next = if next_item_size > 0 { next_item_size } else { item_size };
    if post_residual > 0 && (post_residual as u64) < (min_next as u64) {
        score += 60.0;
    }

    // Lookahead: reward bins that can also fit the next item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    }
    // Lookahead conflict: placing here leaves too little for next item while it fits elsewhere
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 2 {
        score += 15.0;
    }

    // Last-chance bonus: this is the only fitting bin; strongly prefer it over opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        // Prefer new bin when open bins are either too full or wastefully empty
        let poor_state = (mean_residual < item_size as f64 * 1.1) || (mean_residual > bin_capacity as f64 * 0.9 && open_bins_count > 1);
        if poor_state && avg_fit_gap > 5.0 {
            score -= 50.0 + 30.0 * (1.0 - progress);
        } else {
            score += 120.0 + 50.0 * (1.0 - progress);
        }
    }

    // Global balance: prefer bins whose residual deviates below mean (consolidating fullness)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early stream: mild preference to fill existing bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = r * r * (1.0 - r) + r * (1.0 - r) * (1.0 - r);
    score += 12.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 18.0 * (1.0 - r) * (1.0 - r) * (0.4 + 0.6 * progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Lookahead coupling: favor bins whose post-residual fits the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 30.0) * (1.0 - r);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - r);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress * (1.0 - r);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in low classes (small slivers)
    // are nearly dead space -> penalize.
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / (c / 8.0)).floor(); // 0..8 harmonic class
    match class as u32 {
        0 => score += 12.0,                       // dead sliver (<12.5)
        1 => score += 6.0,                        // poor
        2 => score += 2.0,
        3 => score -= 1.0,
        4 => score -= 3.0,                        // ~half bin: very reusable
        5 => score -= 2.0,
        6 => score += 1.0,
        _ => {}                                   // near-full: excellent closure
    }

    // Exact fit or tiny remainder is perfect: reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Harmonic compatibility: does post_residual pair well with the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits exactly into the leftover -> strong reward.
            let gap = post_residual - next_item_size as f64;
            if gap == 0.0 { score -= 20.0; }
            else if gap <= 10.0 { score -= 8.0; }
            else { score -= 4.0 * (1.0 - gap / c); }
        } else {
            // Lookahead cannot reuse the leftover: penalize proportionally
            // to how much dead space this creates.
            score += 5.0 * (1.0 - (next_item_size as f64) / post.max(1.0));
        }
        // Modulo coupling: leftover divisible by common item sizes is reusable.
        let pr = post_residual;
        if pr != 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    // (high mean residual spread) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs() / c;
        score = 55.0
            - 20.0 * fragmentation
            - 15.0 * (1.0 - progress)
            - 2.0 * open_bins_count as f64;
        // A new bin is bad if the item fits snugly somewhere else.
        if item_size * 2 >= bin_capacity { score += 10.0; }
    }

    // Mild preference for fuller bins as stream matures.
    let fill_ratio = 1.0 - (bin_residual as f64) / c;
    score -= 4.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are 1..=100, but small residuals (< 20) are hard to fill.
    let dead = if post_residual == 0 {
        -50.0 // perfect fit is gold
    } else if post_residual < 20 {
        60.0 // tiny unusable gap
    } else if post_residual < 35 {
        25.0
    } else {
        0.0
    };
    score += dead;

    // Reward tightness: fraction of bin filled by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Open-bins pressure: many open bins -> prefer compacting into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * open_bins_count as f64 * (0.5 + progress);

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > item_size {
        // next item won't fit here anyway; tight packing is safer
        score -= 5.0;
    }

    // Mean residual coupling: placing into a bin far above mean residual balances the pool.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin, softened when many bins are open
        // or when this bin would otherwise be a bad host.
        let mut new_bin_penalty = 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // no alternative, must open
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item exactly fills the remainder.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Slight extra pull when post_residual matches next item closely.
            score -= 10.0 * (1.0 - slack as f64 / (post_residual as f64 + 1.0));
        } else {
            // Next item cannot follow into this bin: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average waste is good.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny dead space (<10) that likely becomes unusable.
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    }

    // New-bin candidate: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or with few bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Opening a new bin: mild baseline penalty so tight fits in open bins win,
        // but becomes attractive when open bins are fragmented (high mean residual
        // spread) or when few bins can fit the item.
        score = 0.55 * (bin_capacity as f64) + 12.0 * progress;

        // If open bins are mostly full (low mean residual), new bin is cheap.
        score -= 0.25 * (bin_capacity as f64 - mean_residual);

        // Many open bins with poor fitting options -> prefer opening a fresh bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count <= 2 {
            score -= 8.0;
        }

        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx >= 0.5 * bin_capacity as f64 {
                score -= 10.0 + 0.1 * nx;
            }
        }
        return score;
    }

    // Penalize large dead space quadratically (wasted capacity).
    let pr = post_residual as f64;
    score += 0.012 * pr * pr / bin_capacity as f64;

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Reward residual small relative to mean residual of open bins
    // (this bin is tighter than average -> good consolidation).
    score -= 0.35 * (mean_residual - pr).max(0.0);

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly favor this bin; if it cannot fit anything later, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_after_next = pr - nx;
            if slack_after_next == 0.0 {
                score -= 60.0;
            } else if slack_after_next <= 10.0 {
                score -= 20.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: dead space risk grows with progress.
            score += 6.0 + 14.0 * progress;
        }
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // When many bins can fit, prefer the tightest (already handled by post_residual),
    // but add a small penalty for spreading across too many open bins.
    if open_bins_count > 8 {
        score += 0.8 * (open_bins_count as f64 - 8.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post;
    score += 8.0 * (post / cap).powi(2) * (1.0 - progress);
    score += 6.0 * (post / cap).powi(3) * progress;

    // Reward tight fits via a smooth penalty on relative fill
    let fill = 1.0 - post / cap;
    score -= 10.0 * fill * fill;

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt);
        } else {
            score -= 3.0 * (1.0 - post / (nxt + 20.0)).max(0.0);
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild preference to avoid bin proliferation early
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Diverge from mean residual state smoothly
    score += 0.05 * (post - mean_residual).powi(2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo common item-size
    // divisors of capacity (100 = 2^2 * 5^2). Residuals divisible by 20 or 25
    // are "harmonic" — likely to be exactly filled by future items.
    let r = post_residual;
    let harmonic_bonus = if r == 0 {
        60.0
    } else if r % 20 == 0 || r % 25 == 0 {
        25.0
    } else if r % 10 == 0 {
        12.0
    } else if r % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals in awkward small zones (1..10, 11..19
    // non-multiples of 5) can rarely be used since items >= 1 but typically
    // larger; penalize small unusable leftovers, reward tight fits.
    if r > 0 && r < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let leftover = r - next_item_size;
            score -= 10.0;
            if leftover % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much would be stranded.
            score += (r as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are all poor (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = mean_residual < (item_size as f64) * 0.5;
        if poor_fits {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Fractional-capacity harmony: prefer post_residual close to capacity
    // fractions 1/2 or 1/4 (classic harmonic thresholds).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if r == half || r == quarter {
        score -= 8.0;
    }

    // Spread control: slightly prefer bins below mean residual (tighter bins
    // first keeps large residuals for large future items).
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are pure waste.
    if post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless it yields a tight fit
    // or the item is large relative to the empty bin.
    if bin_residual == bin_capacity {
        score = item_size as f64 + 5.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if post_residual < 20 {
            score -= 20.0;
        }
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && (post_residual as f64) > 0.0 {
        score += 4.0;
    }

    // Late in the stream, be slightly more conservative with residual space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement: penalize dead space creation.
        score += 8.0 + 0.5 * (post_residual as f64);
    }

    // Tight fit reward: small post_residual is good.
    score += 0.35 * post_residual as f64;

    // Compare against mean residual: prefer bins tighter than average.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening new bins; overcome only when fit is bad.
        score += 30.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 5.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 5.0;
        }
    }

    // Prefer filling bins that are already relatively full vs mean residual.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Late in the stream, avoid opening new bins; consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with progress and with number of open bins.
        score += 30.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // Opening a new bin is fine if the item is huge and fits well alone.
        if item_size as f64 > 0.75 * cap {
            score -= 45.0;
        }
    } else {
        score += 2.0 * progress * (open_bins_count as f64);
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    score += 0.1 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = post * post / cap;
    score += p2 * (0.5 + 0.5 * progress * progress) * 0.5;

    // Reward tight fits more strongly as the stream progresses
    let fit = item_size as f64 / cap;
    score -= (1.0 - fit) * (1.0 - fit) * cap * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: smooth exponential coupling with fitting scarcity
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize leaving space that neither fits nor helps next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 3.0 * (nx / cap);
        } else {
            score += 2.0 * (1.0 - post / cap);
        }
    }

    // Mild penalty for proliferating bins late in stream
    score += 0.2 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 pair well
    // with the known item granularity; penalize awkward dead space classes.
    let pr = post_residual;
    let class = pr % 10;
    score += match class {
        0 => -6.0,
        1 | 9 => 3.0,
        2 | 8 => 1.0,
        3 | 7 => 2.5,
        4 | 6 => 0.5,
        _ => 4.0,
    };

    // Small post_residual is good (tight fit), but only if a future item
    // could still use it. Penalize residual classes that no item of the
    // plausible size range can fill.
    if pr > 0 && pr < 10 {
        score += 8.0; // near-dead space
    }

    // Exact fill is perfect.
    if pr == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit in any plausible future
    // residual, penalize wasting the lookahead opportunity.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size < pr {
            let rem = pr % next_item_size;
            if rem == 0 {
                score -= 5.0; // next item divides residual evenly
            } else {
                score += rem as f64 * 0.3;
            }
        } else {
            score += 2.0; // lookahead item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: prefer it only when the current item leaves an
    // awkward residue in every existing bin (i.e., item is large relative
    // to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frac = item_size as f64 / bin_capacity as f64;
        // New bin bonus: big items or early stream favor fresh bins.
        score -= frac * 20.0 + (1.0 - progress) * 5.0;
        // But if an existing bin would be nearly filled, discourage new bin.
        if pr == 0 || pr < 5 {
            score += 15.0;
        }
        // Many open bins with slack: discourage opening yet another.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 10.0;
        }
    }

    // Mild penalty for scattering across many bins when mean residual is low.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps after placement are very costly.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }
    if post_residual > 50 {
        score += 15.0; // wasted a large residual on a small item
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only when no good open option exists.
        score += 10.0 + open_bins_count as f64 * 2.0 - progress * 5.0;
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item can use the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // residual too small for the known next item
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits perfectly after this placement
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += 10.0 + 20.0 * (gap / bin_capacity as f64);
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Compare against mean residual: bins below mean residual are "tighter" — prefer them
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = post_residual as f64 > 60.0 && next_item_size as f64 > post_residual as f64;
        if fitting_bins_count > 0 && !poor_fit {
            score += 80.0;
        }
        // reward new bin if it can host next item too (fresh pairing)
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 15.0;
        }
    }

    // Early stream: slightly more willing to open bins (build diversity)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 14.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let future_tight = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 10.0 * future_tight;
        } else {
            // Next item cannot fit here: mild penalty scaled by wasted potential.
            let waste = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Time horizon: early in the stream, be conservative (favor spreading items,
    // keeping residuals balanced); late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    // Global state coupling: if mean residual is high, prefer bins above the mean
    // (drain the fullest usable bins); if mean residual is low, prefer tighter bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 5.0 * dev;

    // Many open bins: encourage consolidation into existing bins over opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: make it attractive only when the item is large relative to
    // typical residuals or no open bin is a good fit.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 22.0 * poor_fit * big_item;
        score += 10.0 * (1.0 - poor_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual, with a non-linear (quadratic) dead-space penalty.
    let mut score = pr + 0.8 * (pr / cap) * (pr / cap) * cap;

    // Smooth interaction: as the stream progresses, weight compactness more strongly.
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Penalize creating residuals too small to ever fit future items (dead space),
    // using a smooth saturating term rather than a hard threshold.
    let dead = ((10.0 - pr).max(0.0)) / 10.0;
    score += 15.0 * dead * dead;

    // Reward tight fits: interaction between item size and residual used.
    score -= 2.0 * (it / cap) * (bin_residual as f64 - pr) / cap * cap * 0.01;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 25.0;
    } else if next_item_size > 0 {
        // Smooth penalty if next item cannot use the leftover space.
        let gap = ((next_item_size as f64 - pr).max(0.0)) / cap;
        score += 10.0 * gap * gap;
    }

    // New-bin candidate: mildly penalize opening new bins early, allow it late
    // or when open bins are already quite full (mean residual low).
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        score = cap * (1.0 + progress) - 30.0 * (1.0 - openness) * (1.0 - openness);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of 10 are "clean" slots
    let post = post_residual as i64;
    let class = post % 10;
    if post == 0 {
        score -= 30.0; // perfect fit: strongly reward
    } else if class == 0 {
        score -= 12.0; // residual divisible by 10: highly reusable slot
    } else if class <= 2 || class >= 8 {
        score += 8.0; // tiny sliver / near-full: dead space penalty
    } else if class == 5 {
        score -= 4.0; // half-class slot still usable
    }

    // Integer-division thresholds on post_residual (harmonic bands of capacity)
    let band = post / 25; // 0,1,2,3 bands
    score += match band {
        0 => 10.0,          // 0..24 nearly full
        1 => 0.0,           // 25..49
        2 => -3.0,          // 50..74
        _ => -6.0,          // 75..99 roomy
    };

    // Lookahead coupling: does the next item fit the post residual harmonically?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt > post {
            score += 6.0; // next item won't fit here anyway
        } else if post % nxt == 0 {
            score -= 10.0; // next item exactly tiles the leftover space
        } else if (post - nxt) % 10 == 0 {
            score -= 5.0; // leaves a clean multiple-of-10 again
        } else {
            let leftover_class = (post - nxt) % 10;
            if leftover_class <= 2 || leftover_class >= 8 {
                score += 5.0; // would create sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive early or when open bins are congested
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / 10.0;
        score += 18.0 + 20.0 * progress - congestion.min(3.0) * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can absorb the pair comfortably
        }
    }

    // Mild bias toward tighter (smaller-residual) bins overall
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
