    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Early stream: be more permissive about opening bins; late stream: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild penalty so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 8.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
