    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - 20.0 * pressure - 2.0 * open_bins_count as f64;
    }

    // Slight late-stream conservatism: consolidate more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Quadratic waste penalty: dead space grows quadratically more costly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more strongly early in the stream
    // when consolidation still pays off; relax slightly near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 14.0 + 22.0 * (1.0 - progress);
        // If no other bin truly fits well, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: this is the only open bin that fits; avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling (k=2): reward residual that can host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            score += 4.0;
            // If next item fits this bin better than the current one would have,
            // mild penalty for grabbing a versatile residual now.
            if bin_residual as f64 >= nxt {
                score += 2.0;
            }
        }
    }

    // Global state coupling: prefer using bins whose residual is below the mean
    // (consolidate tight bins), discourage burning roomy bins on small items.
    let deviation = mean_residual - post_residual as f64;
    score += 0.15 * deviation;

    // Slight preference for keeping the number of open bins low early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, slightly damped at high fill
    let mut score = pr * (1.0 - 0.3 * pr_norm * pr_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, prefer tighter fits (penalize residual more)
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += pr_norm * pr_norm * 100.0 * progress_weight;

    // Penalize dead space that is too small to be useful (smooth via sigmoid-like term)
    let dead = (pr_norm - 0.2).tanh();
    score += 20.0 * dead * dead;

    // Reward when this bin is the last chance to fit
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits in post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 + 8.0 * (nx / cap);
        } else {
            score += 6.0 * (nx / cap) * (1.0 - pr / nx.max(1.0));
        }
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Alignment with mean residual: prefer bins near mean fill state
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: smooth penalty growing with progress
    if bin_residual == bin_capacity {
        score += 25.0 * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let class_penalty = match pr % 10 {
            0 => -6.0,                     // perfectly reusable residue
            1 | 2 | 3 => 4.0,              // nearly-full dead space
            4 | 5 | 6 => 1.5,
            _ => 0.0,
        };
        score += class_penalty;

        // Dead-space cliff: tiny leftovers are almost useless.
        if pr < 10 {
            score += 12.0;
        } else if pr <= 20 {
            score -= 3.0;                  // sweet spot for small future items
        }
    } else {
        score -= 15.0; // perfect fill is best
    }

    // Fraction-of-capacity coupling: prefer filling bins past harmonic
    // thresholds (25%, 50%, 75% of capacity).
    let fill_frac = (bin_residual as f64) / cap;
    if fill_frac >= 0.75 {
        score -= 5.0;
    } else if fill_frac >= 0.5 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if it cannot fit any residual well, penalize waste.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;                 // perfect chained fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 3.0;                  // next item won't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (smaller post residual
        // relative to mean residual of the pool).
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is
    // large relative to capacity and no tight fit exists, or the stream is
    // early and many items remain.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let big_item = item_size as f64 / cap > 0.6;
        let poor_pool = fitting_bins_count == 0 || mean_residual < item_size as f64 + 5.0;
        if big_item && poor_pool && progress < 0.8 {
            score -= 25.0;                 // open a fresh bin for big items
        } else {
            score += 30.0;                 // discourage wasting fresh bins
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10) are unusable for any item.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to capacity).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bonus: if this is the only bin that fits, prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // encourage filling existing ones (new-bin candidate gets full residual).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if existing bins would leave bad dead space, opening is fine.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            score -= 25.0;
        }
    }

    // Mild progression scaling: later in the stream, be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Deviation from mean residual: prefer bins that are more filled than average.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * next_item_size as f64 - 0.5 * slack;
        } else {
            // dead space for the next item
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tiny unusable residuals relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large or residuals are messy
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if big_item || mean_residual < item_size as f64 * 0.3 {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 50.0;
        }
    }

    // Prefer tighter bins (below mean residual) among open bins
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that can never be reused by typical items (<=80).
        let dead = if post_residual > 80 { (post_residual - 80) as f64 } else { 0.0 };
        score += 4.0 * dead;
    }

    // Tightness: reward small relative waste.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill;
        } else {
            // next item cannot use this residual: penalize large leftovers slightly
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // open bins are crowded or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base cost of opening a new bin, discounted late in the stream
        score += 120.0 * (1.0 - 0.5 * progress) + pressure * 50.0;
        if mean_residual > 40.0 {
            score -= 20.0; // open bins are fragmented; fresh bin is fine
        }
    }

    // Fragmentation pressure: if mean residual is high, prefer bins below mean
    // (consolidate small leftovers), prefer bins above mean less.
    if bin_residual as f64 > mean_residual {
        score += 0.25 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // Many open bins: encourage closing them out (favor bins with small residual).
    score += 0.05 * open_bins_count as f64 * tightness;

    // Early stream: be conservative, prefer best-fit; late stream: fill aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;

    // Non-linear coupling: small post-residuals are valuable; penalize dead space quadratically,
    // with strength that grows as the stream progresses.
    let dead_space_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * dead_space_penalty;

    // Reward tight fits (item nearly fills bin) with smooth saturating term.
    let fill_ratio = it / cap;
    score -= 12.0 * fill_ratio * (1.0 - norm_pr);

    // Last-chance bonus: only one bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward; if it wastes it, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let leftover_after_next = pr - nxt;
            score -= 15.0 * (1.0 - leftover_after_next / cap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mild preference for more-utilized bins relative to mean residual.
    let bin_res = bin_residual as f64;
    score -= 3.0 * (bin_res - mean_residual) / cap;

    // Slight penalty for proliferating open bins, smoothed by progress.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when it beats a bad fit (empty bin has zero dead-space reward),
    // but bias against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small dead space is good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: post_residual in [0,5] -> near-perfect fit, strong reward.
    // Class 1: [6,15] -> usable for small items (10..80 range), mild reward.
    // Class 2: [16,30] -> moderate.
    // Class 3: >30 -> wasteful unless bin is fresh.
    let class: u32 = if post_residual <= 5 { 0 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 30 { 2 }
        else { 3 };

    match class {
        0 => score -= 40.0,
        1 => score -= 18.0,
        2 => score -= 4.0,
        _ => score += 10.0,
    }

    // Integer-division harmonic: post_residual / 10 tier — reward alignment
    // with the item size granularity (items are 1..100, often multiples of 10).
    let tier = post_residual / 10;
    score -= (tier % 2) as f64 * 3.0; // odd tiers slightly favored (5,15,25,...)

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 35.0;
        } else {
            score -= (post_residual as f64 - next_item_size as f64) * 0.35;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize leaving a stranded residual.
        score += (next_item_size as f64 - pr) * 0.25;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + pr * 0.1;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good only when the current fit is poor or
        // the item is huge (little waste potential later).
        let fit_quality = pr / cap; // 1 - item_size/cap
        score = 30.0 + fit_quality * 60.0
            - (fitting_bins_count as f64) * 2.0
            - (item_size as f64 / cap) * 20.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; penalize wasting it on a bad fit.
    let frag = mean_residual - pr;
    if frag > 0.0 {
        score += frag * 0.05;
    } else {
        score -= (-frag) * 0.03;
    }

    // Modulo harmonic on item_size: multiples of 10 pack cleanly; when the
    // item is a multiple of 10 and post_residual is too, reward exactness.
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // (calibrated near 10) but nonzero — pure waste.
    let dead_threshold: f64 = 9.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 8.0;
    }

    // Zero residual (perfect fit) gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving gaps that cannot fit the lookahead item (k=2 lookahead),
    // but only if the gap would otherwise be dead space for it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward when the lookahead item exactly fits the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // the current bin already fits well; encourage consolidation.
    let obp = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = obp * (0.4 + 0.6 * progress);
    // Better fit (smaller post_residual) reduces the effective pressure penalty.
    score += pressure * (pr / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild reward for bins tighter than the mean residual (dense bins).
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when current item leaves a large
    // awkward gap elsewhere; a fresh bin has full flexibility. Penalize it
    // mildly by default so consolidation wins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * pr;
        // But if no open bin can fit well (post residual very small everywhere
        // else is unknown), reduce penalty late in stream.
        if progress > 0.8 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post residual) is better.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect 2-chain: post residual exactly matches next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: reward proportionally to slack.
            let slack = post_residual as f64 - nx;
            score -= 40.0 - slack.min(40.0);
        } else {
            // Next item cannot fit after this placement: penalize dead space,
            // scaled by how "wasted" the leftover is.
            let dead = nx - post_residual as f64;
            score += dead * 0.8;
        }
        // If the next item fits this bin exactly after placement, extra bonus.
        if (bin_residual as f64 - nx).abs() < 0.5 {
            score -= 15.0;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score -= 20.0;
    }

    // --- Mean residual coupling ---
    // Prefer bins whose residual deviates favorably from the mean:
    // a bin with residual well above mean is a good "dumping ground".
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits: strongly prefer using it
        // over opening a new bin.
        score -= 70.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: only attractive when no open bin fits,
        // or the item is huge and would leave a very tight residual elsewhere.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if item_size >= 60 {
            score -= 10.0;
        } else {
            // Discourage opening new bins when existing bins can fit.
            score += 55.0;
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: reward small waste quadratically.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial credit proportional to how well the next item nests.
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * nest;
        } else {
            // Next item won't fit here: mild penalty scaled by overflow amount.
            let over = (next_item_size - post_residual) as f64;
            score += 0.25 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Reward using bins whose residual is close to the item (good relative fit).
    let rel_fill = item_size as f64 / bin_residual as f64;
    if rel_fill <= 1.0 {
        score -= 25.0 * rel_fill;
    }

    // Penalize bins that deviate strongly from the mean residual (keeps residual spread tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream: be more willing to consolidate into existing bins;
    // late in the stream: allow new bins since end-of-stream leftovers matter less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also cheaper when many bins open.
        let new_bin_penalty = 40.0 * (1.0 - progress) + 8.0;
        let open_relief = if open_bins_count > 4 { 4.0 * (open_bins_count as f64 - 4.0).min(10.0) } else { 0.0 };
        score += new_bin_penalty - open_relief;
    } else {
        // Existing-bin bonus grows with progress.
        score -= 10.0 * progress;
    }

    // Slight preference for bins with more open competitors (spread load when crowded).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream penalize waste more strongly
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 12.0 * coupling;

    // Quadratic interaction: tight fits matter more as stream progresses
    score += 6.0 * norm_pr * progress * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Penalize bins far from mean residual (fragmentation), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild new-bin penalty to avoid excessive bin opening, decaying with progress
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low classes.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -50.0 // perfect closure: strongly reward
    } else if pr <= 10 {
        -20.0 // tiny dead space, nearly perfect
    } else if pr < 10 || (pr % 10 == 0 && pr <= 50) {
        // divisible-by-10 residuals are "usable" slots
        -5.0
    } else {
        // awkward residual: penalize by distance to nearest multiple of 10
        let off = (pr % 10).min(10 - pr % 10) as f64;
        off * 1.5
    };
    score -= class;

    // Fractional capacity coupling: reward tight fits relative to capacity.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 8.0;

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: residual becomes dead space risk
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading when many bins already open and mean residual is low.
    if open_bins_count > 0 && mean_residual < (item_size as f64) {
        score += 3.0;
    }

    // New-bin candidate: only attractive early in stream or when item is huge
    // and residual waste would be large elsewhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // baseline for new bin: slightly above a perfect-fit existing bin
        score = 55.0 - fill_frac * 20.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps that no plausible item of size 1..=100 can use well).
    let pr = post_residual;
    if pr > 0 {
        // Dead-space zones: tiny leftovers (1..=10) and awkward mid gaps
        // that are too small for typical items (11..=30).
        if pr <= 10 {
            score += 60.0; // nearly unusable
        } else if pr <= 30 {
            score += 25.0; // awkward gap, only small items fit
        } else if pr <= 50 {
            score += 8.0; // moderate penalty
        } else {
            // Large residual: reward leaving room for big future items
            score -= 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when enough open bins exist,
        // reward when the item would create dead space elsewhere.
        score += 40.0 * open_pressure;
        if post_residual > 0 && post_residual <= 30 {
            score -= 30.0; // new bin leaves a flexible large residual
        }
    } else {
        // Filling an existing bin relieves pressure
        score -= 5.0 * open_pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(30) {
        // This placement blocks the next item's best options
        score += 12.0;
    }

    // Mild preference for filling bins earlier in the stream (keep fresh bins open)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    // Tie-break: prefer bins with residual close to the mean (balanced usage)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 300.0; // next item fills this bin perfectly afterwards
        } else if gap <= 5.0 {
            score -= 100.0;
        } else {
            // Penalize residuals that are too small for the next item (dead space)
            score += gap * 0.5;
        }
        // If next item cannot fit here anyway, slight bonus for leaving room elsewhere
        if next_item_size as u32 > post_residual {
            score += 20.0;
        }
    }

    // Relative to mean residual: bins tighter than average are preferred.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting bins exist (new bin has residual == capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && item_size <= 60 {
            score += 120.0;
        }
        // Large items with no good fit: opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space: residuals too small for any plausible item (items >= 1, typically >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // leftover likely wasted relative to lookahead
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage using bins with residual above mean.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
        score -= (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // New-bin candidate: penalize more when many bins are open and stream is late.
        score += 12.0 + 2.5 * (open_bins_count as f64).sqrt() + 15.0 * t;
        // But if mean residual is tiny (all bins nearly full), opening new bin is fine.
        score -= 1.5 * mean_residual;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > 60 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 30.0 * progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 25.0 * progress;
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize divergence from mean residual (keeps bins balanced)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference to fill existing bins rather than open new ones
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity/10 buckets (C=100 -> classes of 10)
    let class = post_residual % 10;
    // Dead-space penalty: small residuals (<10) are unusable for items >=1... actually
    // items are >=1 here, but tiny residuals waste capacity; penalize via harmonic weight
    if post_residual < 10 {
        score += 25.0; // near-dead bin, discourage ending up here
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect-fit harmonic reward: post_residual exactly divisible by 10 (clean class)
    if class == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Exact fill reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic compatibility: post_residual % next_item_size small => good chain
            let r = post_residual % next_item_size.max(1);
            score -= 4.0 + (next_item_size as f64) * 0.05 - (r as f64) * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to how far off
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin: baseline attractiveness, adjusted by stream progress and load
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 12.0 + 10.0 * progress;
        // discourage new bins when many open bins already fit the item
        score = base + (fitting_bins_count as f64) * 4.0;
        // encourage fresh bin for large items that would leave awkward splits elsewhere
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild pressure toward tighter bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / bin_capacity as f64) * 2.0;

    // Mean-residual coupling: prefer bins deviating below mean residual (tighter than average)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Nonlinear waste penalty on residual squared, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * (post_residual as f64).powi(2) * (0.5 + progress);

    // Open bins pressure: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            // next item can't use the gap -> penalize gap
            score += 0.3 * post_residual as f64;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: make empty bin attractive only when no tight fit exists
    // among open bins; otherwise it competes via its high residual (100).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        // but if item is large, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (low post_residual), with a slight superlinear penalty
    // on large wasted space to combat dead-space accumulation.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        // Perfect chain (next item exactly fills the remainder) gets a strong reward.
        if gap <= 1.0 {
            score -= 25.0;
        } else {
            // Reward proportional to how closely post_residual matches next item size,
            // but only if the next item actually fits (post_residual >= next_item_size).
            if pr >= nxt {
                score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // Next item won't fit here: penalize leaving a残 residual that's too small to be useful.
                score += 6.0 * (nxt - pr) / bin_capacity as f64;
            }
        }
        // Bonus if next item fits perfectly into the *pre-placement* residual too (chained tightness).
        if bin_residual as f64 >= nxt && (bin_residual as f64 - nxt) <= 2.0 {
            score -= 4.0;
        }
    }

    // Relative-to-mean coupling: placing into a bin with residual far above the mean
    // wastes space elsewhere; prefer bins near/below the mean residual for big items.
    let dev = pr - mean_residual;
    score += 0.15 * dev;
    if item_size > 50 && dev > 20.0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        // Many options: be pickier, penalize mediocre fits more.
        score += 0.05 * (fitting_bins_count as f64 - 3.0) * pr;
    }

    // New-bin candidate handling: an empty bin is attractive early in the stream or when
    // the item is large and fits poorly anywhere else; discourage habitual new-bin opening.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items late in the stream justify fresh bins; small items should pack into open bins.
        let new_bin_appeal = 20.0 * item_frac - 15.0 * (1.0 - progress);
        score += 30.0 - new_bin_appeal;
        // If no open bin fits (this call is the only option), opening is inevitable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-phase modulation: early on, keep residuals balanced (encourage spreading);
    // later, allow aggressive tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that nothing can reuse (min item size ~1..100 unknown, assume small)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Chain fit: next item exactly fills post residual
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tightness reward: prefer fuller bins (relative fill)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Global state coupling: many open bins -> prefer consolidation into existing bins
    let crowding = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 3.0 * crowding;

    // Mean residual deviation: prefer bins with residual below mean (filling emptier-of-space bins)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when better fits exist
        let mut new_bin_pen = 40.0 + 60.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_pen += 30.0;
        }
        // Early stream with large item: allow fresh bin sometimes
        if progress < 0.2 && item_size > bin_capacity / 2 {
            new_bin_pen -= 45.0;
        }
        score += new_bin_pen;
    } else if progress > 0.7 {
        // Late stream: discourage wasteful placements
        score += 0.5 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space
    let mut score = x * x * cap;

    // Smooth non-linear coupling of post-residual with stream progress
    let wave = (progress * std::f64::consts::PI).sin();
    score += 12.0 * x * (1.0 - wave.abs()) * cap * 0.25;

    // Penalize bins whose residual drifts far from mean residual (fragmentation)
    score += 0.6 * (pr - mean_residual).abs();

    // Reward using nearly-full bins more aggressively as stream progresses
    score -= 20.0 * (1.0 - x) * (0.5 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into resulting post residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized late when open bins suffice
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // classes (e.g. multiples of 10) are more reusable by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Reward residuals that are "harmonic" with capacity: multiples of 10, 20, 25, 50
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.5; }
        if pr % 50 == 0 { score -= 2.0; }
        // Perfect fit reward
        if pr == 0 { score -= 40.0; }
    } else {
        score -= 40.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual,
    // strongly reward this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward proportionally to how snugly
        let snug = (pr - next_item_size) as f64;
        score -= 8.0 * (1.0 - snug / cap);
    } else if next_item_size > 0 && next_item_size > pr {
        // dead space for the lookahead item: penalize small dead space
        // (large dead space is fine, small waste is bad)
        let dead = (next_item_size - pr) as f64;
        if dead < 20.0 {
            score += 0.6 * (20.0 - dead);
        }
    }

    // Integer-division threshold: residual class by half-capacity
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 4.0; // still roomy bin, keep filling it
    } else if post_residual <= bin_capacity / 10 {
        score += 5.0; // nearly dead residual, deprioritize unless perfect
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer denser bins (fill high-occupancy bins first)
    let occupancy = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * occupancy;

    // New-bin candidate logic: only open a new bin when it's early in the
    // stream or all open bins would leave bad residuals, or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let huge = item > 0.8 * cap;
        let poor_fit = post > 0.0 && post < 15.0 && (next_item_size == 0 || next_item_size > post);
        if !huge && !poor_fit && progress < 0.85 {
            score += 30.0 + 10.0 * (1.0 - progress); // bias toward existing bins
        } else if huge {
            score -= 5.0; // huge items: fresh bin is acceptable
        }
        // fresh bin baseline: post_residual == capacity is already high
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it's an outlier worth consolidating.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual - 0.5 * cap {
        score += 3.0;
    } else if residual_f > mean_residual + 0.5 * cap {
        score -= 3.0;
    }

    // Mild pressure to close out bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap that cannot hold even the smallest plausible item (<= 12) is "dead".
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    } else if post_residual > 12 && post_residual < 25 {
        // Semi-dead zone: risky gap, moderate penalty growing as gap shrinks.
        score += 8.0 * (25.0 - post_residual as f64) / 13.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item could use the post_residual gap,
    // soften the dead-space penalty; if not, harden it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins when residuals are healthy,
    // but make the fresh empty bin attractive when open bins are fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if mean residual across open bins is low
        // (fragmented state) or few bins are open.
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 25.0 * (1.0 - fragmentation) * (1.0 - progress);
        score -= 10.0 * (open_bins_count as f64).recip();
    } else {
        // Mild pressure to consolidate into fewer bins.
        score += 0.15 * open_bins_count as f64 * (1.0 - progress);
        // Prefer bins tighter than the mean residual (use up the fullest bins first).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_slack = post_residual - next_item_size;
        // Perfect chain fit bonus, decaying with slack.
        let chain_quality = 1.0 - (next_fit_slack as f64) / (bin_capacity as f64);
        score -= 14.0 * chain_quality * chain_quality;
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize creating dead space,
        // scaled by how much of the residual is wasted.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += 6.0 * waste * waste;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev.abs();

    // Prefer consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight pressure over stream progression: be more selective about new bins later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    // Discard trivially useless placements leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for next item: mild penalty for wasted potential.
            score += 4.0;
        }
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted over stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 + 20.0 * (1.0 - progress);
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 15.0 * fitting_bins_count as f64;
        }
        // If mean residual is large, prefer reusing bins.
        score += mean_residual * 0.3;
        // Perfect-fit lookahead for the fresh bin: next item fits exactly with item_size? mild.
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm - 20.0 * pr_norm * (1.0 - pr_norm);

    // Stream progress coupling: tighter packing matters more later in the stream
    let tight = 1.0 + progress;
    score *= 0.5 + 0.5 * tight;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - pr_norm;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits into the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / (pr + next_item_size as f64));
    } else if next_item_size > 0 {
        // penalize creating residual that wastes space relative to next item
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }

    // Coupling with mean residual: prefer bins whose residual differs favorably
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Mild preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64) * 0.05 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is more wasted.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let class = pr / 10; // integer division threshold: class 0 = tiny dead space
    match class {
        0 => score -= 30.0,               // near-perfect fit: strongly reward
        1 => score -= 12.0,               // good fit
        2 => score -= 4.0,                // ok
        3 => score += 6.0,                // mediocre
        4 => score += 14.0,               // poor
        _ => score += 20.0,               // large dead space
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling: does next_item_size land in the same modulo class as post_residual?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == pr {
            score -= 45.0; // next item exactly fills this bin
        } else if n < pr {
            // next item fits here: reward proportional to how well it uses leftover
            let fill_frac = n as f64 / pr as f64;
            score -= 25.0 * fill_frac;
            // residue after next placement, harmonic class again
            let r2 = pr - n;
            score -= (10 - (r2 / 10).min(10)) as f64;
        } else {
            // next item cannot use this residual: penalize large unusable leftovers
            score += (pr as f64) * 0.35;
            // extra penalty if leftover is in "unusable band" (too small for typical items)
            if pr > 0 && pr < 15 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is truly unusable
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can serve next item too
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Many open bins: discourage leaving many half-empty bins; favor tightest fits
    score += (mean_residual - post_residual as f64).abs() * 0.15;
    if open_bins_count > 8 {
        score += 3.0;
    }

    // Small tie-break toward minimal post_residual
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..100, but typical
    // small items exist) can use are pure waste. Penalize unusable slivers hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: fully consumed bin is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: the smaller the gap relative to capacity, the better.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are badly fragmented
        // (high mean residual spread) or item is large relative to residuals.
        score += 30.0 + 2.0 * open_bins_count as f64;
        let mean_r = mean_residual;
        if mean_r >= item_size as f64 {
            // An open bin could plausibly host this item; discourage new bin.
            score += 20.0;
        } else {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 1.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use this gap; slight penalty for stranding space.
            score += 5.0;
        }
    }

    // Progress-aware tightening: later in the stream, be more conservative
    // about residual quality since fewer chances remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty if this bin's residual deviates far above mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space, worse for small leftovers
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Compare post_residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins more when many bins are already open
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    }

    // Late in the stream: consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Slight preference for leaving round, reusable residuals
    if post_residual <= 10 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin for a small leftover.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit perfectly in the post-residual,
    // reward this placement (chain fit); otherwise mildly penalize leaving a gap
    // sized awkwardly relative to the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // Last item: strongly prefer filling an existing bin to the max.
        score -= 40.0;
    }

    // Time horizon: early in the stream, be more willing to open bins
    // (mildly penalize existing bins); late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    // Global state: if many bins are open with slack, prefer consolidating
    // into bins with below-average residual (spread the load).
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and the leftover would be tiny (near-perfect single-item usage).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 20.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: early on, tolerate slack; late, punish it harder.
    score += 12.0 * norm_post * progress * (1.0 + progress);

    // Dead-space penalty: post-residual too small for typical future items is wasted.
    let dead = (1.0 - (post / 30.0)).max(0.0).min(1.0);
    score += 15.0 * dead * dead * (1.0 - progress * 0.5);

    // Lookahead: reward if next item fits the post-residual well.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = post - next_item_size as f64;
        score -= 8.0 * (1.0 - slack / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * (1.0 - norm_post);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.15 * (mean_residual - post);

    // Mild penalty for spreading across many bins when a tight option exists.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 6.0 + 25.0 * (1.0 - progress) + 10.0 * norm_post * (fitting_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets (capacity fractions of 100)
    let class = post_residual % 10;
    // Dead-space classes: residuals in 1..=9 are nearly unusable for items >=10
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // worst dead space
    } else if class == 0 {
        score -= 25.0; // perfectly harmonic residual (10/20/.../90)
    } else if class <= 3 {
        score += 12.0; // poor class
    }

    // Integer division thresholds on post_residual
    let q = post_residual / 10;
    score -= (q as f64) * 3.0; // larger usable residual preferred

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0; // chainable placement
            // harmonic match between next item and post residual
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item can't chain here
        }
        // next item exactly fills post residual
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Tight fit reward (small post residual but still usable)
    if post_residual >= 10 && post_residual <= 20 {
        score -= 10.0;
    }

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (fill emptier bins first to preserve tight ones)
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical items, i.e. < 10) is pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        // Small gap that only tiny items can use: strong penalty.
        score += 40.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space coupling: penalize if the gap cannot fit the lookahead item
    // but the bin could have been saved for it (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward if post_residual exactly or comfortably fits the next item
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Penalize new bin unless existing residuals are all poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full unused capacity is potential waste.
        score = bin_capacity as f64 - 20.0;
        // If many open bins with large residuals, opening another is cheap-ish;
        // if few open bins, prefer consolidating.
        score += open_bins_count as f64 * 2.0;
        // If the only fitting bin is this new one, it must be chosen.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If current bin would leave a bad gap anyway, new bin is attractive.
        if post_residual < 20 && post_residual > 0 {
            score -= 45.0;
        }
    }

    // Open-bins pressure: mildly prefer bins that reduce fragmentation when
    // many bins are open (encourage closing out nearly-full bins).
    if bin_residual < bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    // Mean residual coupling: when mean residual is low, tight fits matter more.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one; scale reward by how tight the
            // leftover after both placements would be.
            let two_step_left = post_residual as f64 - next_item_size as f64;
            score -= 100.0 * (1.0 - two_step_left / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's residual — penalize dead space
            // proportionally, especially if residual is too small to matter.
            let waste = post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Compare residual against the mean: bins with below-mean residual are
    // already "tight", prefer packing into them (they'd be wasted otherwise).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Mild preference for packing into fewer bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere (the lookahead/last-chance bonuses above can
    // override this for open bins).
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin used by this placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual,
    // penalty if post residual is awkward relative to next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 5.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = avg_fill * open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score = score.max(0.0) + 12.0 - 18.0 * pressure - 8.0 * progress
            - 6.0 * (item_size as f64 / bin_capacity as f64);
        // Discourage opening a new bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 {
            let best_possible_waste = fitting_bins_count as f64;
            score += best_possible_waste * 2.0;
        }
    }

    // Mild global-state coupling: prefer filling bins below mean residual
    // (keeps residual distribution balanced).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += poly * cap;
    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - prn).powi(3) * 8.0 * (0.5 + progress);
    // Penalize near-empty fills that waste bin space early
    score += (prn - 0.5).abs() * (1.0 - progress) * 5.0;
    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= (1.0 - gap / cap) * 4.0;
    }
    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;
    // Mean residual coupling: prefer bins deviating favorably from mean residual
    score += (mean_residual - pr) * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space by
    // integer division thresholds (capacity/4 bands).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Tiny residue classes (<= capacity/8): near-perfect, reward heavily.
    else if post_residual <= bin_capacity / 8 {
        score -= 60.0 + (bin_capacity / 8 - post_residual) as f64;
    }
    // Usable mid classes: residue in (cap/8, cap/4] can host small items.
    else if post_residual <= quarter {
        score -= 15.0;
    }
    // Half-class: residue near half is still valuable.
    else if post_residual <= half {
        score -= 8.0;
    }
    // Awkward class (half, 3/4]: dead-space risk, penalize.
    else if post_residual <= three_quarter {
        score += 6.0;
    }
    // Large residue: placing a small item in a fat bin wastes it; penalize.
    else {
        score += 12.0;
    }

    // Modulo-10 harmonic class: residues divisible by 10 pair well with
    // typical item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 80.0;
        } else if next_post <= bin_capacity / 8 {
            score -= 25.0;
        }
    }
    // If next item does NOT fit here, mild penalty proportional to gap.
    else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with low residual relative to the fleet mean
    // (best-fit flavor with mean anchoring).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins to build a
    // diverse residual pool; late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base score with progress-dependent bonus.
        score = bin_capacity as f64 - 20.0 * (1.0 - progress) + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: new bin is necessary
        }
        if post_residual as f64 > mean_residual + half as f64 && fitting_bins_count > 0 {
            score += 15.0; // discourage opening when open bins are roomy
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10, the minimum item size)
    // are pure waste. Penalize them heavily, scaling with how "stuck" the stream is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 60.0 + 40.0 * progress;
    } else if post_residual <= 15 {
        // Gaps that only the smallest items could use: soft dead-space penalty.
        score += 12.0 + 8.0 * progress;
    }

    // Reward tight fits: post_residual close to 0 but still usable.
    if post_residual >= 10 {
        let tightness = 1.0 - (post_residual as f64) / 50.0;
        if tightness > 0.0 {
            score -= 15.0 * tightness;
        }
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // into fresh space; prefer consolidating into existing residuals.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chains well); if next item is large and this
    // bin is a poor fit for it, slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 5.0; // next item cannot use this dead space anyway
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing fits are bad (post_residual tiny/unusable)
    // or mean residual is already fragmented.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by stream position
        // and fragmentation of open bins.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 45.0 + 25.0 * (1.0 - progress) + 20.0 * fragmentation;
        // If this is a last-chance situation, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit: penalize creating residual that is useless
            // for the lookahead item (dead space trap).
            let waste = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.4 * waste;
        }
    }

    // Penalize large residual relative to mean residual of open bins
    // (avoid leaving oversized holes when tighter bins exist).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a bad fit everywhere, or lookahead needs fresh space.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin useful for the upcoming big item
        }
    }

    // Late in the stream, prefer tightening existing bins (less waste overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * (0.5 + 0.5 * progress);

    // Penalize large dead space that cannot fit the average item.
    let dead = post_residual as f64;
    if dead < item_size as f64 * 0.5 {
        score += dead * 1.5; // unusable sliver penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1.0) as f64) * 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.4;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - dead / bin_capacity as f64);

    // Mean residual coupling: bins below mean residual are more "shaped" for filling.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // nothing fits well; penalize new bins mildly so tight fits win.
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin useful if a similar/bigger item follows
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let w = 1.0 + progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score -= prn * prn * 30.0 * w; // reward small-but-not-tiny post residuals more over time
    score += prn * prn * prn * 20.0; // penalize large wasted residuals cubically

    // Dead-space penalty: post residual too small for smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Lookahead coupling: smooth interaction between next item and post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = if pr >= nx { 1.0 - (pr - nx) / cap } else { 0.0 };
        score -= fit * fit * 15.0 * w; // reward bins whose residual can host next item
        score += (1.0 - fit) * (1.0 - fit) * 5.0 * progress; // penalize future-dead bins late
    }

    // Last-chance bonus: smooth in fitting_bins_count scarcity
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure against proliferating bins late in stream
    score += open_bins_count as f64 * 0.3 * progress;
    // Alignment with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
