        // and this item is big.
        if mean_residual > 40.0 && item_size > mean_residual as u32 {
            score -= 30.0;
        }
    } else {
        // Slight reward for keeping bins balanced with mean residual.
        score += 0.1 * ((post_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 900.0; // chain: perfect two-item fill
        } else if next_item_size <= post_residual {
            let leftover = post - next_f;
            score -= 300.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large post-residuals that strand space
            score += 0.3 * post;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize bins far above mean residual (likely to become dead space).
    let cap = bin_capacity as f64;
    let dev = (post as f64 - mean_residual) / cap;
    score += 50.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (but the new-bin candidate has fitting_bins_count counted before it, treat carefully).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin's identity on tiny items late in stream? No:
    // instead penalize opening new bins when existing bins fit well.
    if bin_residual == bin_capacity {
        // new-bin candidate: keep it unattractive unless post_residual is large enough
        // to serve the next item well.
        score += 120.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0;
        }
    }

    // Mild stream-progression term: early on, tolerate slack; late, tighten.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post as f64 / cap);

    // Small penalty per extra open bin pressure to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (post as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_frac) * (1.0 - fit_frac) * 25.0;

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (post_residual as f64) * 0.15; // stranded space
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global balance: prefer bins deviating from mean residual.
    score -= (bin_residual as f64 - mean_residual).abs() * -0.05;

    // Time horizon: early on, be more willing to spread (favor tight fits less,
    // favor new bins more); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 60.0
            - pressure * 70.0
            - (1.0 - progress) * 10.0
            + if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 { 0.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 12.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as the stream progresses
    score += (pr * pr) / cap * (0.2 + 0.8 * progress);

    // Reward tight fits: small post residual gets a bonus amplified by progress
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: bonus if next item fits into the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 6.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    let dev = pr - mean_residual;
    score -= 0.5 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills (residue 0) are golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space classes: residues in (0, 10) are nearly unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Integer-division thresholds: post_residual bucketed by 20s.
    let bucket = post_residual / 20;
    score += bucket as f64 * 3.0;

    // Modulo coupling: post_residual % 10 measures fine-grain waste.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.8;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score -= (next_item_size as f64) * 0.5;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover: penalize proportional to leftover size
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // unless current bin leaves a bad harmonic class.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Prefer filling bins with smaller residuals (tight packing pressure).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Mean residual coupling: keep spread small.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // A residual below the minimum conceivable item size (1) is impossible, but treat
    // small residuals (< 10, below the classic minimum) as near-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // barely usable, risky dead space
    } else if post_residual < 35 {
        score += 8.0; // moderately risky
    } else {
        // Larger usable residuals are rewarded
        score -= 0.15 * post_residual as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 40.0; // next item creates a near-perfect fit here
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space for the known next item
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Compare against mean residual: bins tighter than average are preferred targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: a fresh empty bin should only win when the best
    // existing fit is poor. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.6 * open_bins_count as f64 * (0.5 + progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room for lookahead pairing in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-exact placements.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 250.0 / (1.0 + diff);

        // Exact 2-step chain: place next item perfectly too.
        if post_residual == next_item_size {
            score -= 500.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on tiny items.
    if fitting_bins_count == 1 && item_size < 40 {
        score += 150.0;
    }

    // Penalize leaving large unusable gaps (small post_residual but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // dead space < smallest item (1..100 unknown dist, be cautious)
    }

    // New-bin candidate: make empty bins less attractive unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin if lookahead chain fits perfectly in fresh bin.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 60.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 * (1.0 - tightness).clamp(0.0, 1.0);

    // Penalize large dead space that likely cannot be reused
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.25 {
        score -= 10.0; // small leftover, still hard to reuse
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; penalize if it leaves awkward gap
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > (item_size as f64) * 1.5 && open_bins_count > 2 {
        score += 3.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Early stream: slightly favor filling existing bins to keep bin count low
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else {
            // discourage opening a new bin when existing bins can fit
            score += 45.0 + 2.0 * open_bins_count as f64;
            if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
                score -= 20.0; // fresh bin has room for lookahead pairing
            }
        }
    }

    // Mild penalty for spreading across too many bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: favor tight fits (small post_residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * progress * pr / cap);

    // Quadratic dead-space penalty: small residuals are likely unusable
    let dead = pr / cap;
    score += 12.0 * (1.0 - dead).powi(2) * dead;

    // Lookahead coupling: if next item fits the post-residual, reward this bin
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening new bins unless stream is early or bin is empty-ish
    if bin_residual == bin_capacity {
        score = cap as f64 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 30.0; // never open new bin when an existing bin is the only option
        }
    }

    // Mild mean-residual coupling: prefer bins deviating from mean (consolidation)
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter/third of capacity remains
    let quarter = post_residual / (bin_capacity / 4);
    let eighth = post_residual / (bin_capacity / 8);

    // Dead-space penalty: small residuals (< ~item size of typical next item) are wasteful
    if post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (post_residual small but usable)
    if post_residual > 0 && post_residual <= 20 {
        score -= 15.0;
    }

    // Modulo-class coupling: residuals that are multiples of common item sizes (10, 20, 25)
    // are more likely to be filled exactly by future items.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 && post_residual != 0 { score -= 3.0; }

    // Integer-division thresholds on next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead item fits here: strong reward
            score -= 12.0;
            // extra reward if both fit exactly into harmonic class (residual divisible)
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // lookahead item will need another bin: slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are bad
    if bin_residual == bin_capacity {
        // base new-bin score: neutral-ish, slightly above good fits
        score = cap * 0.55;
        // if mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.5;
        // early in stream, allow more bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 5.0;
    }

    // Fractional capacity coupling: prefer residuals in the lower third (compact bins)
    let third = cap / 3.0;
    if (post_residual as f64) < third && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize leaving exactly awkward residuals (just below common item sizes)
    for awkward in [11u32, 21, 26, 31, 41] {
        if post_residual % awkward == 0 && post_residual > 0 && post_residual < 45 {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Eighth-class refinement: reward residuals in the 0th/4th eighth classes (nice fractions)
    if eighth == 0 || eighth == 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 4.0; // leaves a gap the next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 20.0 + pressure + mean_residual * 0.5;
    } else {
        // Existing bins get a mild discount proportional to how full they are.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) non-linearly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (creates a perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual >= 5 {
            // Dead space that the next item cannot use: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // If next item fits into post_residual, residual chain continues: reward.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below average concentrates waste; leaving it near/above
    // average keeps residuals uniform (easier future packing).
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual).min(30.0) * 0.6;
    } else {
        score += (mean_residual - post_residual as f64).min(30.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin: it has full residual, so penalize mildly
        // to prefer reusing existing bins unless fits elsewhere are bad.
        score += 15.0;
        if item_size >= 50 && (fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual != bin_capacity)) {
            score -= 90.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            // Next item could pair with this item in a fresh bin.
            score -= 20.0;
        }
    }

    // Late in the stream, prefer tightening existing bins (fewer leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Mild penalty when many bins are open and we keep spreading items thin.
    if open_bins_count > 10 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 {
        let small = post_residual < 10;
        if small {
            score += 25.0; // unusable sliver
        } else if post_residual < item_size.min(50) {
            score += 8.0; // hard-to-fill gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild preference for fuller bins.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // New-bin candidate logic: only attractive when item is large relative
    // to open-bin residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let mean_fit_gap = mean_residual - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open
        } else if mean_fit_gap > 20.0 {
            // existing bins are roomy; opening wastes capacity
            score += 35.0;
        } else if item_size >= 60 && post_residual < 20 {
            // big item nearly filling a fresh bin is fine
            score -= 15.0;
        } else {
            score += 12.0; // default: prefer reusing open bins
        }
        // Late in stream, avoid opening bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item could pair with the leftover space,
    // reward leaving a useful residual; otherwise penalize.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr && post_residual as f64 <= nr + 15.0 {
            score -= 18.0; // next item fits snugly here
        } else if (post_residual as f64) < nr && post_residual > 0 {
            score += 10.0; // leftover too small for next item
        }
        // If next item is huge, keep space in roomy bins for it.
        if nr >= 70.0 && bin_residual as f64 >= nr {
            score -= 6.0;
        }
    }

    // Global state: many open bins -> consolidate; few open bins -> flexibility.
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 1.5;
    } else if open_bins_count <= 2 {
        score -= 3.0;
    }

    // Mild alignment with mean residual: prefer bins near the mean fill.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits; waste penalty grows quadratically with stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Cubic coupling: dead space becomes increasingly unacceptable late in the stream
    score += 30.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward bins that are the last chance (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits into post_residual, penalize if it nearly misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let miss = (nx - pr) / cap;
            score += 10.0 * miss * (0.5 + progress);
        }
    }

    // Mild preference toward consolidating into fewer bins when mean residual is high
    score += 0.05 * (mean_residual - pr).abs();

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: dead space bucketed by divisibility.
    // Residuals divisible by 10 are "usable" for typical item sizes; odd/prime
    // residues tend to be dead space. Penalize non-decade residuals.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 8.0; // usable class
        } else if pr % 5 == 0 {
            score += 2.0;
        } else {
            score += 6.0; // awkward class
        }
        // Very small dead space is nearly useless unless a tiny item arrives.
        if pr < 10 {
            score += 15.0;
        }
    }

    // Coupling with lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability reward, stronger when the chained fit is tight.
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64) * 0.2;
            // Harmonic class of chained residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't chain here; slight penalty.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large and current item is small, new bin may be better.
        if next_item_size > item_size * 2 {
            score -= 10.0;
        }
    } else {
        // Prefer filling bins below mean residual (balancing via harmonic mean-ish).
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Integer-division threshold: bins whose post residual is in [0, capacity/8]
    // are nearly closed — reward pushing them closed.
    if post_residual > 0 && post_residual <= bin_capacity / 8 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=20)
    // are heavily penalized since few future items (1..100) can exploit them well.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - pr) * 6.0;
    }
    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0; // small but still usable gaps are mildly favored
    }

    // Reward tightness relative to bin capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin (only fitting bin): strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 50.0;
            } else if leftover <= 10 {
                score -= 20.0;
            } else if leftover <= 20 {
                score += 5.0;
            }
        } else if next_item_size > post_residual {
            score += 4.0; // this bin would become dead anyway
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to typical residuals or we have bin-spreading pressure.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let relief = (item_size as f64 / 100.0) * 30.0
            + (mean_residual / bin_capacity as f64) * 10.0;
        score += base_penalty - relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // chain placement possible: reward proportionally to how well next item fills the remainder
            let chain_fill = nxt / (post + 1.0);
            score -= 18.0 * chain_fill * (1.0 - post / cap);
        } else {
            // next item won't fit: penalize dead space left behind
            let waste = post / cap;
            score += 10.0 * waste * waste;
            // extra penalty if post_residual is a small unusable sliver
            if post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Compare against mean residual across open bins
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    let rel = post - mr;
    score += 0.35 * rel;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score = capacity, adjust by stream progress and congestion
        score += 12.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if open_bins_count > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for filling nearly-full bins early in the stream
    let fill_frac = 1.0 - bin_residual as f64 / cap;
    score -= 3.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible future item
    // (items >= 1, so residuals below ~10 are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 15.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; mild penalty for blocking future use.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.15;

    // Deviation from mean residual: prefer bins with less residual left
    // (fill fuller bins first), scaled by stream progress.
    score += progress * (bin_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate handling: an empty bin should only win when no
    // reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // forced to open a new bin
        } else if post_residual as f64 > mean_residual {
            score += 10.0 * progress; // discourage spreading out early
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let it_norm = it / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, tiny residuals become dead weight; penalize convexly.
    let dead = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += dead * cap;

    // Reward tight fits (small post-residual relative to item) with smooth term.
    score -= cap * (1.0 - pr_norm).powi(3) * 0.6;

    // Lookahead coupling: penalize if post-residual can't fit next item,
    // smoothly scaled by how "wasteful" the leftover is.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += gap * gap * cap * (1.2 - 0.6 * progress);
        // Reward if next item fits exactly-ish in leftover.
        if pr >= nx {
            score -= 3.0 * (1.0 - ((pr - nx) / cap).powf(2.0));
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward, smoother for big items.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * it_norm;
    }

    // Many fitting bins: mild penalty to avoid squandering flexibility.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // in the useful direction (place into larger-residual bins when mean is high).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 2.0 * dev * (0.5 + progress);

    // New-bin candidate handling: empty bin gets baseline cost that grows
    // with open-bin count and shrinks with progress (consolidate late).
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.05 * open_bins_count as f64) * (1.0 - 0.3 * progress)
            + 10.0 * (1.0 - it_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is tolerable, mid-range is worst
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows sharply for residuals in the "awkward" band (11..50)
        if pr >= 11 && pr <= 50 {
            score += 40.0 - 0.5 * pr as f64;
        }
        // Harmonic class via integer division: residuals divisible by common item sizes are reusable
        for &d in &[10u32, 20, 25, 33, 50] {
            if pr % d == 0 {
                score -= 12.0;
            }
        }
        // Residual too small for minimum item size = total dead space
        if pr < 10 {
            score += 60.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            score -= 20.0;
        } else {
            // next item won't fit here: mild penalty, more severe if this bin becomes dead
            if pr < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 80.0; // big next item benefits from fresh bin
        }
        // discourage opening when a decent existing fit exists
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible < mean_residual {
                score += 120.0;
            }
        }
    }

    // Slight preference for tighter bins overall (tie-break toward fuller bins)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).recip().min(1.0) * 10.0;

    // Stream progression: early on, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.5 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize medium dead space that can only host small items.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space is worse if it cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer tight bins (small residual relative to mean).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits after placement: reward closeness of the two-step chain.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 40.0 * (1.0 - chain_waste / bin_capacity as f64);
            // Bonus for exact two-step fill (item + next == residual).
            if next_item_size == bin_residual - item_size {
                score -= 60.0;
            }
        } else {
            // Next item cannot use the post residual: penalize proportional dead space.
            score += 0.5 * next_item_size as f64;
            if post_residual > 0 && post_residual < 10 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just minimize post residual, slight bonus for tight fit.
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (residual_f - mean_residual) / mean_residual;
        score += 5.0 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && fitting_bins_count > 0
            && open_bins_count > 0
            && (post_residual as u32 == next_item_size
                || (next_item_size <= post_residual
                    && (post_residual as f64 - next_item_size as f64) < 0.15 * bin_capacity as f64));
        if good_fit_exists || (fitting_bins_count == 1 && bin_residual - item_size >= 0) {
            score += 500.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 20.0; // encourage fresh bin for poor-fit situations
        }
    }

    // Late in stream: consolidate, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
