        }
    } else {
        // Last item: prefer zero-waste placements.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open,
        // and to how much total residual capacity exists.
        let avg_resid = mean_residual.max(0.0);
        score += 10.0 + 2.0 * open_bins_count as f64 + avg_resid * 0.3;
        // Early in the stream, new bins are cheaper; late in the stream, discourage them.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Existing bin: slight reward scaled by how full the bin already is.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fill;
    }

    // Mean-residual coupling: when mean residual is large, prefer bins below mean
    // (use up scattered space); when small, prefer bins above mean (keep big gaps).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly later in the stream.
    score -= (1.0 - norm_pr) * (1.0 + progress) * 8.0;

    // Penalize dead space relative to the mean residual of open bins.
    score += 0.5 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic classes on post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else {
        // dead space penalty grows for awkward residual classes
        let class = pr % 10;
        score += match class {
            1..=3 => 4.0,
            4..=6 => 8.0,
            7..=9 => 14.0,
            _ => 0.0,
        };
        // residual that can only host tiny items is dead space
        if pr < 10 {
            score += 20.0;
        }
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // residual reusable by next item: reward proportionally
            score -= 6.0 + 0.1 * (next_item_size as f64);
            // harmonic bonus if residual is a multiple-ish of next size
            if pr % next_item_size.max(1) <= 2 {
                score -= 4.0;
            }
        } else {
            // this placement strands the next item
            score += 12.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // prefer new bin when mean residual is small (open bins nearly full)
        let bias = (mean_residual / bin_capacity as f64) * 80.0 - 40.0 + 20.0 * progress;
        score = 100.0 - crowded * 5.0 + bias;
        // large items justify a fresh bin more
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild preference to fill bins with larger items
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (near-perfect packing).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.8;

    // If the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating a gap the next item cannot use.
        score += 8.0;
    }

    // Prefer bins below mean residual (larger gaps absorb big items better).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.6 {
            score -= 25.0;
        } else {
            score += 45.0;
        }
    }

    // Slight late-stream conservatism: keep residuals usable for the tail.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: minimize post_residual.
    let fit_quality = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * fit_quality * fit_quality;

    // 2-step lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize post_residuals that are too small to be useful (dead space),
            // scaled by how much the next item would waste.
            let waste = (next_item_size as i64 - post_residual as i64).max(0) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare residual against mean residual: prefer using bins with below-average
    // residual (tighter bins) to consolidate space.
    score -= 0.5 * ((mean_residual - post_residual as f64));

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the item would leave a large unusable gap in any existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more as stream progresses (consolidate later).
        score += 20.0 + 30.0 * progress;
        // But if no open bin fits at all, new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: a fresh bin can host both this and the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post-residual that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: opening a bin is only attractive when the item is large
    // relative to capacity or the current bin leaves a very poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_here = (bin_capacity as f64 - item_size as f64);
        let waste_open = (mean_residual - item_size as f64).max(0.0);
        // Prefer new bin if it wastes less than the best open-bin waste implied by mean.
        score += 5.0 + waste_here * 0.15 - waste_open * 0.2;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 10.0 * (1.0 - progress);
        // Large lookahead item pairs well with a fresh bin.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= waste_here {
            score -= 4.0;
        }
    } else {
        // Lookahead: reward bins whose post-residual can host the next item.
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 5.0;
            } else {
                score += 2.0;
            }
        }
        // Mild penalty for spreading across many open bins; encourage consolidation
        // when mean residual is already low.
        score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late, penalize them quadratically
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward filling the bin tightly, scaled by item size
    score -= 10.0 * norm_item * (1.0 - norm_pr) * (1.0 + progress);

    // Dead-space penalty: residuals too small to be useful later
    let dead = if next_item_size > 0 { next_item_size as f64 } else { 0.0 } / cap;
    let unusable = (dead - norm_pr).max(0.0);
    score += 15.0 * unusable * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + norm_item);
    }

    // Crowd-out pressure: many open bins -> favor consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead bonus: if next item fits exactly into the resulting residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Mild penalty for opening a new bin (empty-bin candidate), decaying with progress
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable residual (harmonic class 1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Harmonic class weighting: residue modulo 10 shapes desirability
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Lookahead: reward bins that can also host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
        } else if post_residual > 0 {
            // residual too small for next item: penalize proportionally
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: slight penalty to avoid spreading items thin
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Prefer opening a new bin for large items (small post_residual left behind)
        score -= 0.25 * item_size as f64;
        // Discourage opening new bins early in the stream / when bins are few
        score += 4.0 * (open_bins_count as f64).sqrt();
        // If an open bin would fit perfectly, never open a new one
        if post_residual == 0 {
            score += 100.0;
        }
        // If next item is huge and current item is small, opening fresh is attractive
        if next_item_size >= 70 && item_size <= 30 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins relative to mean residual across open bins
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Stream progression: later in stream, be slightly greedier about tight fits
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 3.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    // Penalize post_residual values that are too small to fit a typical item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: gap too small for even the smallest item.
            score += 40.0;
        } else if post_residual < 25 {
            // Marginal gap: only fits very small items.
            score += 18.0;
        } else if post_residual < 40 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over opening new ones.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward leaving that gap; otherwise penalize awkward gaps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Relative residual vs mean: prefer placing into bins with less residual
    // (tighter packing) when this bin's residual is below average.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early in the stream, allow new bins more freely; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64); // tight chain fits preferred
        } else {
            // next item won't fit here: penalize small dead space that wastes capacity
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fill
        score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a hopeless dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual {
            score -= 15.0;
        } else {
            score -= 6.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when the item fits comfortably in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // opening new bin wastes a chain opportunity
        }
    }

    // Prefer bins below mean residual (tighter bins) to keep loose bins flexible.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild reward for filling bins densely.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that no plausible item can fill.
        let t = step_index as f64 / total_items.max(1) as f64;
        let horizon_scale = 100.0 * (1.0 - 0.3 * t);
        if (post_residual as f64) < horizon_scale * 0.15 {
            score -= 50.0; // small gap, likely reusable
        } else {
            score += 0.8 * (post_residual as f64).powf(1.3) / 100.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting space.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // keeping larger residuals for future larger items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Mild penalty for spreading across many open bins early on.
    score += 0.05 * open_bins_count as f64 * t;

    // New-bin candidate: make it attractive only when current fit is poor
    // or the bin is genuinely fresh.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        score = 10.0 + 0.5 * poor_fit;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin also serves next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score -= 12.0 * t * norm_pr * norm_pr;
    score += 20.0 * progress * norm_pr * norm_pr;
    // Tight fits are valuable; penalize dead space more as stream advances
    score += (pr as f64).powi(2) / cap * (0.5 + progress);
    // Lookahead synergy: reward residual that fits next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 15.0 * (1.0 - (pr - ni) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.3);
    }
    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }
    // Divergence from mean residual: prefer bins near mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward small post_residual strongly (tight fit), super-linear.
    score += (post * post) / cap;

    // Harmonic class bonus: post_residual divisible by common class sizes
    // (10, 20, 25, 50) keeps the bin reusable by typical future items.
    let classes: [u32; 4] = [10, 20, 25, 50];
    for c in classes {
        if post_residual > 0 && post_residual % c == 0 {
            score -= 6.0 * (c as f64 / 10.0);
        }
    }
    // Penalize awkward residues (dead space unlikely to be filled).
    let awkward = post_residual % 10 != 0 && post_residual < 20;
    if awkward {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty so best-fitting bins still win among many options.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bins are fragmented
    // (high mean residual spread) or item barely fits anywhere.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs();
        if mean_residual < 25.0 {
            score -= 12.0; // open bins nearly full -> fresh bin is fine
        } else {
            score += 10.0 + fragmentation * 0.2;
        }
        if item_size >= 50 {
            score -= 5.0; // large items start fresh bins well
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post / cap);

    // Prefer bins with residual below mean (tighter than average).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let min_item = 1.0f64;
    let usable_threshold = if next_item_size > 0 { next_item_size as f64 } else { min_item };
    if (post_residual as f64) < usable_threshold {
        // Gap is dead relative to the lookahead item (or fully wasted at end of stream).
        score += 40.0 + (usable_threshold - post_residual as f64) * 0.5;
    }
    // Very small leftover slivers are almost always dead space regardless of lookahead.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Blocking the next item into this gap region: mild penalty.
        score += 8.0;
    }

    // Open-bins pressure: with many open bins, strongly prefer filling existing bins
    // over opening new ones (penalize the new-bin candidate implicitly by rewarding use).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and stream is advanced.
        score += 15.0 + pressure * 6.0 + progress * 10.0;
    } else {
        // Reward using an existing bin, scaled by how fragmented the state is.
        score -= pressure * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual diverges toward zero
    // (tighter bins first), a mild best-fit sharpening.
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Reward tight fits (small post_residual).
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // 2-step lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (slack_after_next as f64 / bin_capacity as f64 + 0.1);
        } else {
            // Next item won't fit here; penalize slightly if we leave awkward gap.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when few/no open bins fit well,
    // or late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let bonus = 45.0 - 25.0 * fragmentation - 8.0 * pressure + 10.0 * progress;
        // Default new-bin penalty unless conditions are favorable.
        score += bonus.max(-40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    // (smallest item is 1, but small slivers < 10 are nearly unusable).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: just minimize waste, reward fullness strongly.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: late in the stream, avoid opening new bins;
    // early, allow exploration of fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // many bins are already open with usable residual.
        score += 12.0 * progress + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0; // open bins have plenty of room; don't open a new one
        }
    } else {
        // Existing bin: reward using it more heavily late in the stream.
        score -= 4.0 * progress;
    }

    // Global state coupling: if mean residual is low (bins nearly full),
    // prefer bins with larger post_residual to keep flexibility.
    if mean_residual < 15.0 {
        score += 0.1 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    score += poly * (pr * pr) / cap;    // penalize dead space more late in stream

    // Reward tight fits (small post_residual) with smooth decay
    score -= (1.0 - fit) * (1.0 - fit) * 20.0;

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count > 0 {
        let urgency = 1.0 / (fitting_bins_count as f64);
        score -= 25.0 * urgency * (1.0 - fit);
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        let kernel = (-diff / cap).exp();
        score -= 15.0 * kernel;
    } else {
        // last item: strongly prefer filling bins completely
        score -= 30.0 * (1.0 - fit);
    }

    // Mild penalty for spreading across many bins, smoothed by mean residual
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // New-bin candidate: neutral-ish baseline scaled by progress
    if bin_residual == bin_capacity {
        score = cap * (0.5 + 0.5 * poly) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: dead-space classes on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Penalize post-residuals in awkward harmonic classes (small unusable slivers)
    let cls = post_residual % 10;
    if post_residual > 0 {
        match cls {
            1..=4 => score += 18.0,          // tiny slivers: nearly dead space
            5..=9 => score += 6.0,           // mid slivers: still fillable
            _ => score -= 10.0,              // exact decade: clean fit
        }
    } else {
        score -= 25.0; // perfect closure
    }

    // Integer-division threshold: post_residual / item_size ratio
    if item > 0.0 {
        let ratio = post / item;
        if ratio < 0.25 { score += 8.0; }     // bin mostly spent anyway
        else if ratio > 1.5 { score += 4.0; } // leaving lots over
        else { score -= 5.0; }                // sweet spot ~ half-used
    }

    // Harmonic pairing with lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next fits here: reward, stronger if it nearly fills (harmonic pair)
            let fill = nxt / post;
            if fill > 0.8 { score -= 20.0; }
            else if fill > 0.5 { score -= 12.0; }
            else { score -= 4.0; }
        } else {
            // next won't fit: penalize leaving a mid-range residual it misses
            if post >= 10.0 && post < nxt { score += 14.0; }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged when good fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Late-stream tightening: prefer closing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post / cap);

    // Mean residual coupling: prefer bins below mean (compact the spread)
    score += 0.15 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (min size 1, but practically small gaps < ~10) are wasted.
    // Penalize unusable small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (high fill ratio of the gap).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good; encourage using existing bins when few are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "dirty" bin; finishing it off is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap; if next item cannot fit, the gap is dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += post_residual as f64 * 0.5;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the empty-bin candidate (residual ==
    // capacity) so it is chosen only for poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 1.5;
        // But if item is large relative to capacity, new bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Mild stream progression: later in the stream, waste matters more
    // (less opportunity to amortize), tighten penalty on leftover space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        }
        // Penalize leaving a gap next item cannot fit into (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Bonus if next item fits snugly relative to capacity
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / post_residual as f64) * 8.0;
        }
    } else {
        // Last item: minimize post residual strongly
        score += 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus (only fitting bin before opening new one)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins exist, but allow it when
    // current bin would leave large dead space
    if bin_residual == bin_capacity {
        if post_residual >= 20.0 {
            score += 5.0 + post_residual * 0.1;
        } else {
            score += 40.0;
        }
    }

    // Slight preference for tighter fits via squared post residual
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large post-residual (dead space), superlinear.
    score += 0.35 * (post_residual as f64).powf(1.4);

    // Reward tight fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep options open.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below the mean (tighter bins first).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, opening new bins is cheaper; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
        // But early on, if the item is large and fits few bins, allow new bins.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
    } else {
        // Late stream: reward reusing open bins to avoid sprawl.
        score -= 5.0 * progress;
    }

    // Penalize many open bins (encourage packing into existing bins).
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, penalize residual waste more
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: tiny residuals that can't fit typical items
    if pr > 0 && pr < 10 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            score += 3.0 * (1.0 - (pr / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: mild penalty to avoid bin proliferation
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    score += 0.3 * (mean_residual - pr as f64).abs() * 0.1;

    // New-bin candidate: neutral-ish baseline, penalize slightly unless residuals are tight
    if bin_residual == bin_capacity {
        score = pr + 6.0 + 4.0 * progress - 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo arithmetic on post_residual.
    // Residuals in {0} are perfect; small classes (1..=9) are dead space; mid classes are reusable.
    let post = post_residual as i64;
    let class = post % 10;
    match class {
        0 => score -= 40.0,                       // perfect closure or clean decade residual
        1..=4 => score += 25.0,                   // tiny unusable sliver -> penalize
        5..=9 => score -= 5.0,                    // still usable sliver
        _ => {}
    }

    // Integer-division threshold: does the NEXT item fit into post_residual?
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            // Chain bonus scaled by how tightly the next item nests.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 * (1.0 - tight);
        } else {
            // Next item cannot chain here; penalize proportionally to wasted residual.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Last item: prefer closing bins exactly.
        if post_residual == 0 { score -= 100.0; }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: only attractive when no good fit exists
    // (many fitting bins means reuse is cheap; a fresh bin is penalized then).
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64) / ((open_bins_count as f64) + 1.0);
        score += 55.0 + 45.0 * pressure;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Harmonic penalty on large item filling a bin that was near-closed already.
    let fill = (item_size as f64) / (bin_capacity as f64);
    if fill > 0.7 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (typical item >= 10, but sizes may go down to 1) are heavily penalized.
    let dead_threshold = 8.0;
    if (post_residual as f64) < dead_threshold {
        // Deep in dead-space territory: penalty grows as gap shrinks.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty: small but nonzero gaps are worse than exact fits.
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual <= 3 {
        score += 15.0; // nearly dead space
    }

    // Reward filling a bin tightly relative to its capacity.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (20.0 + 40.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // If the leftover can still fit the lookahead item, this is a good placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover wastes the lookahead: mild penalty.
        score += 4.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large post_residual relative to mean residual) or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual * 0.9;
        if poor_fit && fitting_bins_count > 1 {
            // Slightly discourage opening when decent fits exist, but keep it
            // competitive against dead-space-heavy placements.
            score = mean_residual * 0.8 + 5.0;
        } else {
            // Favorable: current bins would create dead space or none fit well.
            score = dead_threshold - 6.0; // ~2.0, below most dead-space penalties
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match is heavily rewarded; near matches mildly rewarded.
        if diff == 0.0 {
            score -= 200.0;
        } else {
            score += diff * 0.8;
        }
        // Penalize leaving residual that cannot host the next item at all
        // unless it is small dead space (< 10% of capacity).
        if next_item_size > post_residual {
            let dead = post_residual as f64;
            if dead > 0.10 * bin_capacity as f64 {
                score += dead * 0.5;
            }
        }
        // Bonus if placing item here leaves room for BOTH a fraction of next item later
        if post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize bins whose residual is far below the mean residual (they are nearly full;
    // wasting them on a poor fit is costly) but reward using nearly-full bins for tight fits.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, discounted when many bins are open
        // or the item is large relative to capacity.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 40.0 + 60.0 * fill_ratio - 5.0 * (open_bins_count as f64).sqrt();
        // If lookahead suggests next item would pair with this item's residual, encourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Slight preference to keep residuals above small-item threshold usable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract a bonus proportional to fill
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 20.0 * next_tightness;
        } else {
            // Next item won't fit here after placement; mild penalty unless bin nearly full
            score += 5.0 * (1.0 - fill);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer filling existing bins over opening new ones
    if open_bins_count > 1 {
        score -= 0.5 * mean_residual.min(50.0) * (1.0 - progress);
    }

    // Early in stream: slightly favor compacting into few bins
    if progress < 0.3 {
        score -= 3.0 * fill;
    }

    // Late in stream: tolerate small residuals less (waste matters more)
    if progress > 0.7 {
        score += 0.1 * post_residual as f64;
    }

    // New-bin candidate: add a fixed opening cost so it's only chosen when it beats all open bins
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin can fit at all, opening is fine (score already lowest among non-fitting)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: penalize wasted residual with a cubic ramp
    let x = post / cap; // normalized post residual in [0,1]
    score += 12.0 * x * x * (1.0 - progress) + 20.0 * x * x * x;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Lookahead: reward if next item exactly fills remaining space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs() / cap;
        score -= 15.0 * (1.0 - diff * diff);
        // penalize if next item cannot use the leftover well
        score += 10.0 * diff;
    } else {
        // last item: strongly prefer minimizing leftover
        score += 25.0 * x;
    }

    // Last-chance bonus: only one bin can fit, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - x);
    }

    // New-bin candidate: make it unattractive unless item fits perfectly or no good fit exists
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).sqrt();
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Mild pull toward bins with residual close to item size relative to fleet mean
    score += 0.05 * (post - mean_residual).abs();

    // Smooth stream-progress coupling: late stream favors consolidation
    score -= 5.0 * progress * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of common small sizes) are rewarded; dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Class bonus: post_residual divisible by 10 (harmonic with item granularity)
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // odd dead space
    }

    // Integer-division thresholds on post_residual
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr < 10 {
        score += 30.0; // unusable sliver
    } else if pr <= 20 {
        score -= 6.0; // still usable for small items
    }

    // Fraction-of-capacity class of the fill level
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.9 {
        score -= 12.0;
    } else if fill_frac >= 0.7 {
        score -= 6.0;
    } else if fill_frac < 0.4 {
        score += 8.0; // poor utilization
    }

    // Lookahead coupling: prefer leftover that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
            // harmonic pair: post_residual - next_item_size lands on a nice class
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave bad dead space or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 && post_residual >= 30 {
            score -= 5.0;
        }
    }

    // Mild consolidation pressure via mean residual
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (1..=9) are usually unusable
    // given item sizes >= 1 but typically >= 10; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that the lookahead item could fill exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap that can still host next item is mildly valuable
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // i.e. penalize the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing residuals are small relative to item (poor fits elsewhere).
        score += 15.0 + 2.0 * bin_pressure + 10.0 * (1.0 - progress);
        // Attractive if item barely fits anywhere: mean residual much smaller than item.
        if (mean_residual as u32) < item_size + 5 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residual close to item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    // Penalize wasting large bins on small items when many bins are open.
    if item_size < 20 && bin_residual > 80 && open_bins_count > 3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact-ish fit (low post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        let chain_quality = 1.0 - (leftover2 as f64 / bin_capacity as f64);
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space more if it's small and unusable
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.35 * (next_item_size as f64 - dead);
        }
    }

    // Penalize leaving residuals that no typical item can use (< 10 in classic range)
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins with below-mean residual (fill fuller bins first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight preference for opening new bins early in the stream when fit is poor
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if this is a very poor fit for open bins
        score += 6.0 * (1.0 - progress);
        score += 0.15 * (post_residual as f64);
    }

    // Waste penalty scaled by how full the bin becomes
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: exact fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating small unusable dead space (post_residual < 10 can hold nothing).
    if post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize bins whose leftover is just below next size.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 15.0 - gap;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer filling bins that are already relatively full (low residual relative to mean).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Prefer bins with residual close to item size (tight packing) nonlinearly.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when many bins are open
        // (fragmented state) or late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 55.0 + 0.3 * open_bins_count as f64;
        new_bin_penalty -= 20.0 * progress;
        // If no open bin fits at all, opening is inevitable: soften the penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty = 10.0;
        }
        // Large items (>= 60) benefit from a fresh bin when residuals are scattered.
        if item_size >= 60 && mean_residual < item_size as f64 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    // Mild reward for consolidating bins: using a bin reduces effective open count pressure.
    if bin_residual < bin_capacity {
        score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress + 3.0 * progress * norm_pr);

    // Penalize large dead space more than proportionally (smooth quadratic)
    score += 1.5 * norm_pr * norm_pr;

    // Reward tight fits smoothly
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 4.0 * tightness * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> strong smooth reward
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits remaining space, reward this placement
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 3.0 * fits_next * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue mod 10
    let r = post_residual;
    let class = r % 10;
    // Residues that are highly reusable for typical item sizes (multiples of 5/10)
    let class_bonus: f64 = match class {
        0 => 6.0,
        5 => 4.0,
        2 | 4 | 6 | 8 => 1.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Quotient class: big leftover chunks are valuable
    let q = r / 20;
    score -= q as f64 * 2.0;

    // Perfect fit reward
    if r == 0 {
        score -= 40.0;
    } else if r <= 5 {
        score -= 15.0; // near-perfect fill, tiny dead space
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item also fits here: chain placement is great
            let slack_after_next = r - next_item_size;
            let next_class = slack_after_next % 10;
            let chain_bonus = 12.0 + (next_class == 0) as i32 as f64 * 6.0
                + (next_class == 5) as i32 as f64 * 3.0;
            score -= chain_bonus;
            // exact pairing: item + next fills bin completely
            if slack_after_next == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; penalize small dead space that blocks it
            let gap = next_item_size - r;
            if gap <= 15 {
                score += gap as f64 * 0.8; // just missed: this bin becomes waste
            }
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit poorly
        // (large post_residual elsewhere) or the item is huge relative to mean residual
        let pressure = item_size as f64 - mean_residual;
        if pressure > 0.0 && fitting_bins_count > 0 {
            score += pressure * 1.5; // discourage new bin when open bins are decent
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 8.0;
    }

    // Mild penalty for leaving residual far below mean (fragmentation)
    if (r as f64) < mean_residual * 0.4 && r > 0 {
        score += 4.0;
    }

    // Tight fit preference: smaller post_residual relative to item is efficient
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual in (0, 10) is unusable dead space: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead coupling: keep room for the next item if it fits snugly ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 15.0; // next item leaves dead space here
            } else {
                score -= 10.0; // next item still fits usefully
            }
        } else {
            // next item cannot use this residual: residual value drops
            score += 8.0;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, but discouraged when many bins are open
        // and the item could have gone somewhere with a decent fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 6.0 * pressure * (1.0 + progress);

        // Large items justify fresh bins more than small ones
        if item_size > 60 {
            score -= 18.0;
        } else if item_size < 25 {
            score += 12.0;
        }
        // If next item is large too, a fresh bin can host the pair better
        if next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (tight packing),
        // but only when the fit is not wasteful.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 10.0 * tightness;
    }

    // --- Open-bin pressure: mild bonus for filling existing bins vs. proliferation ---
    score -= 0.05 * (open_bins_count as f64).powi(2).min(400.0);

    // Prefer bins below the mean residual (they are the fullest -> fill them first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post residual ~ 0)
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, heavily reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves slack; reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placing current item: penalize slightly
            score += 10.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins that keep residuals near mean
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting large residual on small item (dead space creation)
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    // Early in stream, be more willing to open new bins (penalize existing bins less)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New empty bin candidate: mild penalty so it's chosen only when it beats bad fits
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space that no typical item can use:
    // post_residual too small relative to item range wastes the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5; // hard-to-fill zone
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving a gap it nearly fits
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.5 * gap;
            }
        }
    }

    // Global state coupling: prefer filling bins when many are open (consolidation).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * open_pressure * tightness;

    // Mean residual deviation: prefer bins below mean residual (fill the emptier-relative ones)
    // to keep a spread of large residuals for big future items? Actually prefer bins ABOVE mean
    // residual being consumed less: penalize drawing down bins already below mean.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev; // bins with more residual than mean get used first, keeping small ones for small items

    // Time horizon: early in stream, be conservative (keep residuals large for unknown future);
    // late in stream, pack greedily.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.35 * post_residual as f64;
    score -= t * 15.0 * tightness;

    // Mild penalty for opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if next item is huge and no bin is roomy, new bin is fine
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically as stream advances
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly early on
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalty scaled by scarcity of fitting bins
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_waste = pr - next_item_size as f64;
        score += 0.4 * slack_waste;
        if slack_waste < 1.0 {
            score -= 8.0;
        }
    }

    // Mild pressure from mean residual: prefer bins deviating from mean
    score += 0.15 * (pr - mean_residual).abs();

    // Many open bins: discourage spreading, encourage filling
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen
    // only when open bins have genuinely bad fits
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (post_residual small).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic class: items whose size divides capacity nicely (e.g. 10,20,25,50)
    // create reusable residuals; reward bins where post_residual belongs to a
    // "harmonic" class (multiple of 10 or 25).
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    } else if pr < 10 {
        // dead space below smallest item size (interface: sizes >= 1, but
        // tiny residuals are still poor) - mild penalty
        score += 3.0;
    }

    // Penalize residuals that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward if post_residual is a good host for next item
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 12.0;
            }
        } else {
            // this bin becomes dead after placement
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits. Base penalty for opening a bin scaled
    // by stream progression (early on, consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
        // But if the item is huge relative to capacity, a fresh bin is fine.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
        // If current bin would leave a very bad residual, opening new bin is ok.
        if bin_residual - item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals when few bins are open
    // (keeps bin count low); when many bins are open, prefer tight packing.
    if open_bins_count > 3 {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Integer-division threshold: bins whose residual is in the "awkward"
    // band (just above half capacity after placement) get a nudge penalty,
    // since half-filled bins are flexible but wasteful.
    if pr > bin_capacity / 2 && pr <= bin_capacity * 3 / 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A post_residual below the minimum item size (1) is impossible, but gaps
    // that are "small" relative to typical item sizes are likely dead space.
    let small_gap_threshold = 12.0;
    if (post_residual as f64) < small_gap_threshold && post_residual > 0 {
        score += (small_gap_threshold - post_residual as f64) * 4.0;
    }

    // Reward very tight fits (waste near zero).
    if post_residual <= 2 {
        score -= 8.0;
    } else if post_residual <= 6 {
        score -= 4.0;
    }

    // Perfect fit: absolutely prefer.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity and gets this
    // penalty naturally via high post_residual, but add explicit pressure).
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Lookahead: if the next item could exactly use the post_residual,
    // strongly favor leaving this bin in that state.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // post_residual can't fit next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Early in stream: be slightly more willing to open bins (better packing later);
    // late in stream: consolidate to avoid leftover open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 2.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the "useful" direction (smaller residual = tighter bin).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-step fill: post_residual == next_item_size is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize large dead space left behind.
            score += 0.35 * (post_residual as f64 - mean_residual).abs();
            // Extra penalty if post_residual becomes unusably small.
            if post_residual < 10 {
                score += 12.0;
            }
        }
        // If next item exactly matches current residual, this bin is prime target.
        if next_item_size == bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover as usual.
        score -= 5.0;
    }

    // Penalize deviating far from mean residual (keeps bin sizes homogeneous).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it costly unless it offers a clearly better
    // 2-step plan (fresh bin gets moderate score so it wins only on bad fits).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is huge, a fresh bin may be the right home.
        if next_item_size > item_size && next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild pressure against accumulating many open bins with big residuals.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: post_residual too small to fit any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can fit the next item.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // If next item fits exactly, extra reward.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual (using emptier bins keeps tight bins open).
    if (bin_residual as f64) > mean_residual + 1.0 {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Time horizon: early in stream, be conservative (penalize scattering);
    // late in stream, fill existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * (post_residual as f64) / (bin_capacity as f64);
    score -= progress * 5.0 * tightness;

    // New-bin candidate: only attractive when nothing fits well or bins are crowded.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) / (bin_capacity as f64);
        let crowd = open_bins_count as f64;
        // Default: discourage new bin; but allow it if open bins are all very full
        // (mean residual small) or the item is large.
        score += 15.0;
        score -= 10.0 * (mean_residual / (bin_capacity as f64));
        score -= (item_size as f64) / 20.0;
        score -= 3.0 * crowd.max(0.0).min(10.0);
        let _ = bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smoothly rising penalty on leftover space as stream progresses
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * (pr / cap) * cap * 0.5;

    // Reward tight fits (small post_residual) more aggressively mid-stream
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize opening a new bin when existing bins can fit the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let urgency = 1.0 + 2.0 * (fitting_bins_count as f64).recip();
        score += 10.0 * urgency * (0.3 + 0.7 * progress);
    } else if bin_residual == bin_capacity {
        score -= 2.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: penalize leaving residual just below next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 && gap < 0.25 * cap {
            score += 3.0 * (1.0 - gap / (0.25 * cap)) * (0.5 + progress);
        } else if gap <= 0.0 && gap > -nxt {
            score -= 2.0; // item could pair with next item exactly
        }
    }

    // Mean residual interaction: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space classes: harmonic classes on post_residual via integer division.
    // Very small post-residual = near-perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class: post_residual bucketed by capacity/8 slices
        let class = post_residual / (bin_capacity / 8);
        score -= 12.0 / (class as f64 + 1.0);
        // Small dead space (<=10) is still very usable -> extra reward
        if post_residual <= 10 {
            score -= 20.0;
        }
        // Dead space penalty for awkward residues (11..=20): hard to fill later
        if post_residual > 10 && post_residual <= 20 {
            score += 15.0;
        }
    }

    // Modulo harmonic coupling: item and residual share residue classes mod 10
    let m = (bin_residual % 10) as f64;
    let im = (item_size % 10) as f64;
    if (bin_residual % 10) == (item_size % 10) && post_residual % 10 == 0 {
        score -= 8.0;
    }
    score += (m * 0.15) + (im * 0.05);

    // Lookahead: penalize if next item fits the post residual (keeps bin useful)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; slight penalty for wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when no open bin
    // offers a good fit. Penalize opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * 0.5 + 60.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= (bin_capacity as u32 * 3 / 4) {
            score -= 15.0; // big next item: fresh bin may be valuable
        }
    }

    // Mild preference for tighter bins overall (relative to mean residual)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range,
    // assume tiny items are rare), so residual in 1..=8 is nearly worthless.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual <= 20 {
        // small gaps are risky but partially usable
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual (high fill fraction)
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item can fit into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (consolidating)
    if bin_residual != bin_capacity {
        score += 0.3 * ((bin_residual as f64) - mean_residual);
    }

    // Early stream: be a bit more willing to open bins to build diversity
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits perfectly in the post residual,
    // this bin becomes a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space the next item cannot use
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
        }
        // If next item cannot fit anywhere else and this bin could chain, prefer it.
        if fitting_bins_count == 1 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // remaining residuals or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used reluctantly.
        score += 35.0;
        // But if the item is large, a fresh bin gives a clean fit.
        if item_size >= 60 {
            score -= 45.0;
        } else if item_size >= 40 {
            score -= 15.0;
        }
        // If open bins are crowded on average, a new bin is more reasonable.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins with small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for tighter bins (small residual before placement)
    // to keep well-filled bins packed first.
    score += (bin_residual as f64) * 0.05;

    // Prefer reusing bins when many are open (consolidation).
    score -= open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual already favored).

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual too small for next item: penalize proportionally to wasted space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Penalize the empty-bin candidate mildly, but
    // reduce the penalty when the stream is early (many items remain to co-fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 8.0 * (1.0 - progress);
        // If item is large, a fresh bin wastes little
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 6.0;
        }
        // Many open bins with large mean residual -> don't open new bins
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Penalize leaving dead space that few items can use (post_residual < 10 unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for bins below mean residual (balance load)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in stream: prefer filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // for leaving awkward mid-range dead space (post residual near half of cap).
    let norm_post = post / cap;
    let mut score = post
        + 12.0 * (norm_post * (1.0 - norm_post)) * cap
        + 8.0 * (norm_post * (1.0 - norm_post)).powi(2) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer spreading (favor post_residual); later, pack tightly.
    let coupling = 2.0 * (progress - 0.5);
    score += coupling * (post * post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mild penalty when bin residual deviates from mean residual across open bins,
    // keeping residual distribution balanced (quadratic in deviation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Slight openness control: many open bins -> prefer filling existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 8 fractions.
    let class = post_residual / (bin_capacity / 8).max(1);
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward near-perfect fits (post_residual in the lowest class).
    if post_residual == 0 {
        score -= 60.0;
    } else if class == 0 {
        score -= 35.0;
    } else if class == 1 {
        score -= 15.0;
    } else if class == 2 {
        score -= 5.0;
    } else {
        // Dead-space penalty grows super-linearly for large leftovers.
        score += class as f64 * 4.0;
    }

    // Modulo-10 harmonic classes: leftovers that commonly pair with
    // typical item sizes (multiples of 5/10) are more reusable.
    let pr = post_residual;
    if pr >= 10 && (pr % 10 == 0) {
        score -= 12.0;
    } else if pr >= 10 && (pr % 5 == 0) {
        score -= 6.0;
    } else if pr < 10 && pr > 0 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead coupling: does the leftover exactly host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            score += 6.0;
        }
    }

    // Tightness reward: prefer filling the bin heavily.
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        // Penalize opening bins when plenty of slack exists overall.
        score += 55.0 + 40.0 * pressure + 20.0 * progress;
        // Allow new bin if item is huge and would leave a bad leftover anywhere.
        if item_size >= 70 && post_residual <= 20 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        }
    }

    // Mild preference to consolidate across many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are dead space.
    // Penalize heavily as post_residual approaches the "unusable" zone (1..=10),
    // with a smooth escalating penalty for any small gap.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 40.0 + (10.0 - pr) * 6.0; // unusable gap: hard penalty
        } else if post_residual <= 20 {
            score += (20.0 - pr) * 1.5; // risky small gap
        } else {
            score -= (pr - 20.0) * 0.3; // large usable leftover: mild reward
        }
    } else {
        score -= 25.0; // perfect fit: strong reward
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened and this residual is wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another;
    // the new-bin candidate (residual == capacity) gets a penalty scaled by open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 4.0;
        // But if no open bin fits well (this call is new-bin candidate and it's the only option),
        // fitting_bins_count reflects open bins that fit; if none fit, opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0 + open_bins_count as f64 * 4.0;
        }
    } else {
        // Reward reusing existing bins when bin pressure is high.
        score -= open_bins_count.min(10) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 { score -= 12.0 - slack * 0.5; }
        } else {
            // Next item won't fit here; small post_residual is wasted space.
            let pr = post_residual as f64;
            if pr < next_item_size as f64 && pr < 10.0 {
                score += 10.0;
            }
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (filling the emptiest-fitting bins keeps tight bins tight).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.4;
    } else {
        score += (res - mean_residual).min(30.0) * 0.2;
    }

    // Late-stream conservatism: near the end, tighten bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: small post_residual is already the base term.

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 25.0 * (1.0 - diff / 5.0);
        } else if post_residual as f64 >= nxt {
            // next item fits but leaves more waste: mild reward
            score -= 8.0 * (1.0 - diff / cap).min(1.0);
        } else {
            // next item will NOT fit here: penalize wasting this bin's
            // remaining space on the current item
            score += 6.0 * (diff / cap).min(1.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins; prefer filling those (they are hardest to reuse).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.10 * (item_size as f64);
    }

    // Penalize creating tiny unusable dead space (<10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive early in the stream or when the
    // current fit is poor; otherwise discourage proliferation of bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = item_size as f64 / cap;
        let openness = 0.35 * (1.0 - progress) + 0.10 * (open_bins_count as f64).recip();
        // New bin is tempting for large items (good standalone start) but
        // costly when many bins are already open.
        score += 20.0 - 30.0 * fit_quality - 25.0 * openness;
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 10.0; // room for the known next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Penalize dead space: small post_residual is good, but zero is perfect.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 55.0;
            } else if slack < 10.0 {
                score -= 25.0;
            } else {
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize leaving large unusable gap.
            let gap = nxt - pr;
            if gap < 10.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // elsewhere; penalize unless open bins are quite full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bins are more acceptable late in the stream or when existing bins are full.
        let openness = (1.0 - avg_fullness) * (1.0 - 0.5 * progress);
        score += 35.0 * openness + 5.0;
        // Avoid proliferating bins when many are already open with slack.
        score += 2.0 * (open_bins_count as f64).sqrt() * openness;
    } else {
        // Mild preference for bins tighter than average.
        score += 0.15 * (mean_residual - residual).max(-30.0);
    }

    // Slight time discount: early in the stream, be pickier about slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear tightening over stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize large dead space quadratically, weighted by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // mild penalty when many bins compete (encourage consolidation)
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_ratio = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack_ratio * slack_ratio) * (0.5 + 0.5 * progress);
        } else {
            // post-residual cannot host next item: penalize proportionally
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Context: compare against mean residual; bins far from mean get slight penalty
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bin less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 20.0 * (1.0 - avg_tightness * avg_tightness) + 10.0 * (1.0 - progress);
    }

    // Slight preference for fewer open bins
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, and small chunks) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: post_residual exactly divisible by 10 keeps room for
    // typical item granularities -> subtract to favor such bins.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Post residual divisible by 5 is second-best harmonic class.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }
    // Dead-space penalty: tiny unusable leftovers (1..9) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Integer-division thresholds: residual bucket (residual / 25).
    let bucket = bin_residual / 25;
    score -= 2.0 * bucket as f64;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills leftover.
            if next_item_size == post_residual {
                score -= 20.0;
            } else {
                score -= 5.0;
                // Bonus if next item also leaves a multiple-of-10 residual.
                if (post_residual - next_item_size) % 10 == 0 {
                    score -= 4.0;
                }
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by the wasted gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when current
    // residual is a poor harmonic fit (large leftover, bad class).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = cap * 0.5;
        // Attractiveness of opening new bin grows with open bins being
        // fragmented (low mean residual) and with bad fit quality.
        let fragmentation = 1.0 - (mean_residual / cap);
        score -= 8.0 * fragmentation;
        // If post residual in current best bin would be tiny/dead, new bin wins.
        if post_residual < 15 && !fitting_bins_count_ge_2(fitting_bins_count) {
            score -= 10.0;
        }
    } else {
        // Existing bin gets a stability discount scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 1.0 + 2.0 * progress;
    }

    // Penalty for leaving residual far from any harmonic class center.
    let frac = pr / cap;
    score += 4.0 * (frac - (frac * 10.0).round() / 10.0).abs();

    score
}

#[inline]
fn fitting_bins_count_ge_2(n: usize) -> bool {
    n >= 2
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1, but practically small gaps < ~10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger usable residuals are rewarded proportionally.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: penalize bins when many bins are open, to consolidate.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if the
    // item leaves a large residual AND no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // Penalize new bin when existing bins are roomy enough to absorb items.
        if mean_r > item_size as f64 * 1.5 {
            score += 30.0;
        }
        // Reward new bin slightly when the item is large and would leave a
        // clean residual, avoiding fragmentation of open bins.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Lookahead: if next item is small, a fresh bin is fine to keep clean.
        if next_item_size > 0 && next_item_size <= 15 {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: reward placing item so that the next item still
        // fits into this bin's residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // Creating a gap the known next item cannot use: dead space.
            score += 20.0;
        }
    }

    // Slight preference for tighter bins (best-fit flavor) on top of residual.
    score += (bin_residual as f64) * 0.05;

    // Early in the stream, allow more aggressive new-bin opening to build
    // diverse residual portfolios; late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits
    // the post residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.4 * chain_tightness; // tighter chains rewarded more
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize if we leave awkward dead space
        // relative to the mean residual across open bins.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - dead);
        }
        // Prefer bins whose leftover is near the mean residual (predictable reuse).
        score += 0.3 * (dead - mean_residual).abs();
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is
    // truly unusable dead space (small and less than any plausible item).
    if bin_residual == bin_capacity {
        score += 120.0;
        if post_residual == bin_capacity as f64 as u32 {
            if fitting_bins_count == 0 {
                score -= 500.0; // nothing fits anywhere: must open
            }
        }
    }

    // Mild pressure to keep bin count low: favor existing bins as stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight preference for filling larger residuals when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    // Items are 1..100, so residual < smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny slivers are near-useless
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // moderately awkward
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize a bit more if we leave big gap
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 2.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current bins are crowded or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * 0.4 + mean_residual * 0.05;
        // Base penalty so new bins are used sparingly; reduce penalty
        // late in the stream or when many bins are nearly full.
        let mut new_bin_score = 30.0 - 15.0 * progress - crowded.min(25.0);
        // If item is large and no open bin fits well, new bin more attractive.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 8.0;
        }
        if next_item_size > 0 && next_item_size > (bin_capacity - item_size) {
            // next item can't share the new bin either; less attractive
            new_bin_score += 6.0;
        }
        score = score.max(new_bin_score);
    }

    // Mild time-horizon exploration: slightly prefer consolidating into
    // existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * pr_norm) - 12.0 * progress * pr_norm * (1.0 - pr_norm);

    // Penalize dead space: small post-residuals that can't fit typical items.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            let slack = (pr - next_item_size as f64).abs();
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            score += 8.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalized so we prefer existing bins unless they're bad fits.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    // Prefer bins tighter than average (good fit relative to the fleet).
    score += 3.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect complements of small items
    // (multiples of 10) are reusable; odd residues are dead space.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0; // residue aligned with the item grid -> highly reusable
    } else if class <= 3 {
        score -= 3.0;  // nearly aligned
    } else if class >= 7 {
        score += 6.0;  // awkward large dead-space class
    }

    // Integer-division thresholds: reward leaving room for typical small items.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }
    if post_residual > 50 {
        score += 4.0; // wasting a nearly-full bin is fine, but don't over-prioritize
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
            // harmonic match: next item exactly complements leftover
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64;
        score += 25.0 - 30.0 * crowdedness;
        // late in the stream, prefer consolidating into open bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to prefer bins below mean residual (tighter packs first).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Scale by number of alternatives: many fitting bins -> be pickier about waste.
    if fitting_bins_count > 1 {
        score += 0.3 * post_residual as f64 * ((fitting_bins_count - 1) as f64).min(5.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 - (post_residual as f64) * 6.0; // gap of 1 -> +114, gap of 9 -> +66
    } else if post_residual >= 10 && post_residual < 25 {
        // medium waste: mild penalty relative to baseline
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless the current fit is bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If item leaves a large residual in a fresh bin and fits elsewhere, discourage.
        if fitting_bins_count >= 1 && post_residual > 40 {
            score += 40.0;
        }
        // Late in stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 60.0 * progress;
        }
    }

    // Open-bin pressure: many open bins -> favor filling existing ones (already doing so);
    // few open bins -> tolerate new bins more.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably (tighter than mean).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear penalty on wasted space).
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly here: big reward, sharper for exact match.
            score -= 30.0 * (1.0 - diff / cap);
        } else {
            // Next item would NOT fit after this placement: penalize dead space.
            score += 12.0 + 0.5 * diff;
        }
    }

    // Relative residual vs mean: prefer bins tighter than average (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && item_size as f64 >= 0.9 * cap {
            score -= 25.0; // large items: fresh bin is fine
        }
    }

    // Early in stream, be more willing to open bins (build diverse residual pool).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}
